                                onChange={(e) => setSubjectId(e.target.value)}
                                className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 text-sm"
                            >
                                {subjects.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                            </select>
                        </div>
                    )}
                </div>
                <div className="p-4 border-t bg-gray-50 rounded-b-xl flex justify-between gap-2">
                    <button onClick={onClose} className="px-3 py-2 text-sm font-medium text-gray-600 hover:bg-gray-200 rounded-lg">
                        Cancelar
                    </button>
                    <div className="flex gap-2">
                        <button 
                            onClick={() => {
                                if (type === 'detailed' && !subjectId) {
                                    alert('Selecione uma disciplina.');
                                    return;
                                }
                                onExport({ period, type, subjectId });
                                onClose();
                            }}
                            className="px-3 py-2 text-sm font-bold text-green-700 bg-green-100 hover:bg-green-200 rounded-lg shadow-sm flex items-center"
                        >
                            <TableCellsIcon className="w-4 h-4 mr-1" />
                            Excel
                        </button>
                        <button 
                            onClick={() => {
                                if (type === 'detailed' && !subjectId) {
                                    alert('Selecione uma disciplina.');
                                    return;
                                }
                                onConfirm({ period, type, subjectId });
                                onClose();
                            }}
                            className="px-4 py-2 text-sm font-bold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-sm flex items-center"
                        >
                            <PrinterIcon className="w-4 h-4 mr-1" />
                            Imprimir
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

const TurmaDetails: React.FC<TurmaDetailsProps> = ({ turma, onBack, allStudents, subjects, onUpdateStudents, settings, currentUser, hasExam = false, onAddNotifications, users }) => {
    const [activeView, setActiveView] = useState<ViewMode>('grades');
    const [selectedPeriod, setSelectedPeriod] = useState<PeriodOption>('1º Trimestre');
    const [selectedSubjectId, setSelectedSubjectId] = useState<string>('');
    const [isPrintModalOpen, setIsPrintModalOpen] = useState(false);

    const [unsavedChanges, setUnsavedChanges] = useState<Record<string, Grade>>({});
    const [unsavedExamChanges, setUnsavedExamChanges] = useState<Record<string, number>>({}); 

    const [isOverviewMode, setIsOverviewMode] = useState(false);
    const [isDetailedSummary, setIsDetailedSummary] = useState(false);

    const [attendanceDate, setAttendanceDate] = useState<string>(new Date().toISOString().split('T')[0]);
    const [attendanceChanges, setAttendanceChanges] = useState<Record<string, 'Presente' | 'Ausente' | 'Atrasado'>>({});

    const [expandedStudentId, setExpandedStudentId] = useState<string | null>(null);
    const [behaviorChanges, setBehaviorChanges] = useState<Record<string, BehaviorEvaluation>>({});

    const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');

    const availableSubjects = useMemo(() => {
        if (currentUser.role === UserRole.PROFESSOR) {
            const assignment = turma.teachers?.find(t => t.teacherId === currentUser.id);
            if (!assignment) return []; 
            return subjects.filter(s => assignment.subjectIds.includes(s.id));
        }
        return subjects;
    }, [subjects, turma, currentUser]);

    useEffect(() => {
        if (availableSubjects.length > 0) {
            if (!selectedSubjectId || !availableSubjects.find(s => s.id === selectedSubjectId)) {
                setSelectedSubjectId(availableSubjects[0].id);
            }
        } else {
            setSelectedSubjectId('');
        }
    }, [availableSubjects, selectedSubjectId]);

    const studentsInTurma = useMemo(() => {
        return allStudents
            .filter(s => turma.studentIds.includes(s.id))
            .sort((a, b) => a.name.localeCompare(b.name));
    }, [allStudents, turma]);

    const selectedSubject = useMemo(() => subjects.find(s => s.id === selectedSubjectId), [subjects, selectedSubjectId]);

    const canEditGrades = currentUser.role === UserRole.PROFESSOR && !isOverviewMode;
    const canEditAttendance = currentUser.role === UserRole.PROFESSOR;
    const canEditBehavior = currentUser.role === UserRole.PROFESSOR;

    const handlePrintConfirm = (options: PrintOptions) => {
        printClassPauta(turma, studentsInTurma, subjects, options, settings, hasExam);
    };

    const handleExportExcel = (options: PrintOptions) => {
        exportClassPautaToExcel(turma, studentsInTurma, subjects, options, settings, hasExam);
    };

    const calculateFinalGrade = (acs1: number = 0, acs2: number = 0, at: number = 0): number => {
        const p1 = settings.evaluationWeights?.p1 || 40;
        const p2 = settings.evaluationWeights?.p2 || 60;
        const mediaACS = (acs1 + acs2) / 2;
        const final = ((mediaACS * p1) + (at * p2)) / (p1 + p2);
        return parseFloat(final.toFixed(1));
    };

    const calculateExamFinalGrade = (mediaInterna: number, examGrade: number): number => {
        const p1 = settings.examWeights?.internal || 50; 
        const p2 = settings.examWeights?.exam || 50;     
        const totalWeight = p1 + p2;
        const final = ((mediaInterna * p1) + (examGrade * p2)) / totalWeight;
        return parseFloat(final.toFixed(1));
    };

    const getSubjectGrade = (student: Student, subjectName: string, period: string): number => {
        if (period === 'Situação Anual') {
            const t1 = getSubjectGrade(student, subjectName, '1º Trimestre');
            const t2 = getSubjectGrade(student, subjectName, '2º Trimestre');
            const t3 = getSubjectGrade(student, subjectName, '3º Trimestre');
            return parseFloat(((t1 + t2 + t3) / 3).toFixed(1));
        }
        const gradeObj = student.grades?.find(g => 
            g.subject === subjectName && 
            g.period === period &&
            g.academicYear === turma.academicYear
        );
        return gradeObj ? gradeObj.grade || 0 : 0;
    };

    const getDetailedGrades = (student: Student, subjectName: string, period: string) => {
        const gradeObj = student.grades?.find(g => 
            g.subject === subjectName && 
            g.period === period &&
            g.academicYear === turma.academicYear
        );
        const acs1 = gradeObj?.acs1 || 0;
        const acs2 = gradeObj?.acs2 || 0;
        const at = gradeObj?.at || 0;
        const mediaACS = parseFloat(((acs1 + acs2) / 2).toFixed(1));
        const finalGrade = calculateFinalGrade(acs1, acs2, at);
        return { acs1, acs2, mediaACS, at, finalGrade };
    };

    const getExamGrade = (student: Student, subjectName: string): number => {
        if (unsavedExamChanges[student.id] !== undefined && selectedSubject?.name === subjectName) {
            return unsavedExamChanges[student.id];
        }
        const exam = student.examGrades?.find(e => e.subject === subjectName && e.academicYear === turma.academicYear);
        return exam ? exam.grade : 0;
    };

    const handleGradeChange = (studentId: string, field: 'acs1' | 'acs2' | 'at', value: string) => {
        if (!canEditGrades || selectedPeriod === 'Situação Anual') return;
        const numValue = Math.min(20, Math.max(0, parseFloat(value) || 0));

        setUnsavedChanges(prev => {
            const student = studentsInTurma.find(s => s.id === studentId);
            if (!student || !selectedSubject) return prev;

            const existingGradeIndex = student.grades?.findIndex(g => 
                g.subject === selectedSubject.name && 
                g.period === selectedPeriod && 
                g.academicYear === turma.academicYear
            );

            const currentGradeObj = existingGradeIndex !== undefined && existingGradeIndex !== -1
                ? student.grades![existingGradeIndex] 
                : { 
                    subject: selectedSubject.name, 
                    period: selectedPeriod as '1º Trimestre' | '2º Trimestre' | '3º Trimestre', 
                    academicYear: turma.academicYear, 
                    acs1: 0, acs2: 0, at: 0, grade: 0 
                  };

            const prevChange = prev[`${studentId}`] || currentGradeObj;
            const updatedGradeObj = { ...prevChange, [field]: numValue } as Grade;
            updatedGradeObj.grade = calculateFinalGrade(updatedGradeObj.acs1 || 0, updatedGradeObj.acs2 || 0, updatedGradeObj.at || 0);

            return { ...prev, [`${studentId}`]: updatedGradeObj };
        });
        setSaveStatus('idle');
    };

    const handleExamChange = (studentId: string, value: string) => {
        if (!canEditGrades || selectedPeriod !== 'Situação Anual' || !hasExam) return;
        const numValue = Math.min(20, Math.max(0, parseFloat(value) || 0));
        setUnsavedExamChanges(prev => ({ ...prev, [studentId]: numValue }));
        setSaveStatus('idle');
    };

    const handleSaveGrades = () => {
        setSaveStatus('saving');
        const updatedStudents = [...allStudents];

        Object.entries(unsavedChanges).forEach(([studentId, val]) => {
            const newGrade = val as Grade;
            const studentIndex = updatedStudents.findIndex(s => s.id === studentId);
            if (studentIndex !== -1) {
                const student = { ...updatedStudents[studentIndex] };
                const grades = student.grades ? [...student.grades] : [];
                const gradeIndex = grades.findIndex(g => 
                    g.subject === newGrade.subject && 
                    g.period === newGrade.period &&
                    g.academicYear === newGrade.academicYear
                );
                if (gradeIndex !== -1) grades[gradeIndex] = newGrade;
                else grades.push(newGrade);
                student.grades = grades;
                updatedStudents[studentIndex] = student;
            }
        });

        if (selectedPeriod === 'Situação Anual' && hasExam && selectedSubject) {
             Object.entries(unsavedExamChanges).forEach(([studentId, gradeVal]) => {
                const studentIndex = updatedStudents.findIndex(s => s.id === studentId);
                 if (studentIndex !== -1) {
                    const student = { ...updatedStudents[studentIndex] };
                    const exams = student.examGrades ? [...student.examGrades] : [];
                    const examIndex = exams.findIndex(e => e.subject === selectedSubject.name && e.academicYear === turma.academicYear);
                    const newExam: ExamResult = { subject: selectedSubject.name, grade: gradeVal as number, academicYear: turma.academicYear };
                    if (examIndex !== -1) exams[examIndex] = newExam;
                    else exams.push(newExam);
                    student.examGrades = exams;
                    updatedStudents[studentIndex] = student;
                 }
             });
        }

        onUpdateStudents(updatedStudents);
        setUnsavedChanges({});
        setUnsavedExamChanges({});
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 3000);
    };

    const getGradeValue = (student: Student, field: 'acs1' | 'acs2' | 'at' | 'grade', period: string = selectedPeriod): number => {
        if (period === selectedPeriod && unsavedChanges[student.id]) {
            return ((unsavedChanges[student.id] as any)[field] as number | undefined) ?? 0;
        }
        const gradeObj = student.grades?.find(g => 
            g.subject === selectedSubject?.name && 
            g.period === period &&
            g.academicYear === turma.academicYear
        );
        return gradeObj ? ((gradeObj as any)[field] as number | undefined) ?? 0 : 0;
    };

    const getAttendanceStatus = (student: Student): 'Presente' | 'Ausente' | 'Atrasado' | '' => {
        if (attendanceChanges[student.id]) return attendanceChanges[student.id];
        const record = student.attendance?.find(a => a.date === attendanceDate);
        return record ? record.status : '';
    };

    // Helper to calculate total absences for a student in the current year
    const getTotalAbsences = (student: Student) => {
        if (!student.attendance) return 0;
        return student.attendance.filter(a => {
            const year = parseInt(a.date.split('-')[0]) || 0;
            return year === turma.academicYear && (a.status === 'Ausente' || a.status === 'Atrasado');
        }).length;
    };

    const handleAttendanceChange = (studentId: string, status: 'Presente' | 'Ausente' | 'Atrasado') => {
        if (!canEditAttendance) return;
        setAttendanceChanges(prev => ({ ...prev, [studentId]: status }));
        setSaveStatus('idle');
    };

    const handleSaveAttendance = () => {
        setSaveStatus('saving');
        const updatedStudents = [...allStudents];
        const notifications: AppNotification[] = [];
        const dateFormatted = new Date(attendanceDate).toLocaleDateString('pt-PT');

        studentsInTurma.forEach(student => {
            const newStatus = attendanceChanges[student.id];
            if (!newStatus) return; 

            const studentIndex = updatedStudents.findIndex(s => s.id === student.id);
            if (studentIndex !== -1) {
                const s = { ...updatedStudents[studentIndex] };
                const attendance = s.attendance ? [...s.attendance] : [];
                const recordIndex = attendance.findIndex(a => a.date === attendanceDate);
                const newRecord: AttendanceRecord = { date: attendanceDate, status: newStatus };
                if (recordIndex !== -1) attendance[recordIndex] = newRecord;
                else attendance.push(newRecord);
                s.attendance = attendance;
                updatedStudents[studentIndex] = s;

                // Enviar notificações se houver Falta ou Atraso
                if ((newStatus === 'Ausente' || newStatus === 'Atrasado') && users && onAddNotifications) {
                    const guardian = users.find(u => u.name === student.guardianName && u.role === UserRole.ENCARREGADO);
                    if (guardian) {
                        notifications.push({
                            id: `att_notif_${Date.now()}_${student.id}`,
                            userId: guardian.id,
                            type: 'message',
                            title: `Alerta de Assiduidade: ${student.name}`,
                            message: `Informamos que foi registado o status "${newStatus}" para o seu educando no dia ${dateFormatted}.`,
                            read: false,
                            timestamp: new Date().toISOString(),
                            relatedId: student.id
                        });
                    }
                }
            }
        });

        onUpdateStudents(updatedStudents);
        if (notifications.length > 0 && onAddNotifications) {
            onAddNotifications(notifications);
        }
        setAttendanceChanges({});
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 3000);
    };

    useEffect(() => { setAttendanceChanges({}); }, [attendanceDate]);

    const getStudentBehaviorEval = (student: Student): BehaviorEvaluation => {
        if (behaviorChanges[student.id]) return behaviorChanges[student.id];
        const evalObj = student.behaviorEvaluations?.find(b => 
            b.period === selectedPeriod && b.academicYear === turma.academicYear
        );
        return evalObj || {
            period: selectedPeriod as any, academicYear: turma.academicYear,
            scores: { assiduidade: 0, disciplina: 0, participacao: 0, responsabilidade: 0, socializacao: 0, atitude: 0, organizacao: 0 },
            percentage: 0
        };
    };

    const handleStarClick = (studentId: string, criteria: keyof BehaviorEvaluation['scores'], score: number) => {
        if (!canEditBehavior || selectedPeriod === 'Situação Anual') return;
        setBehaviorChanges(prev => {
            const studentRef = allStudents.find(s => s.id === studentId);
            if (!studentRef) return prev;
            const currentEval = getStudentBehaviorEval(studentRef);
            const newScores = { ...currentEval.scores, [criteria]: score };
            const totalScore = Object.values(newScores).reduce((a, b) => a + Number(b), 0);
            const maxScore = 7 * 5; 
            const percentage = Math.round((totalScore / maxScore) * 100);
            return { ...prev, [studentId]: { ...currentEval, scores: newScores, percentage } };
        });
        setSaveStatus('idle');
    };

    const handleSaveBehavior = () => {
        setSaveStatus('saving');
        const updatedStudents = [...allStudents];
        Object.entries(behaviorChanges).forEach(([studentId, val]) => {
             const newVal = val as BehaviorEvaluation;
             const studentIndex = updatedStudents.findIndex(s => s.id === studentId);
             if (studentIndex !== -1) {
                 const student = { ...updatedStudents[studentIndex] };
                 const evaluations = student.behaviorEvaluations ? [...student.behaviorEvaluations] : [];
                 const evalIndex = evaluations.findIndex(e => e.period === newVal.period && e.academicYear === newVal.academicYear);
                 if(evalIndex !== -1) evaluations[evalIndex] = newVal;
                 else evaluations.push(newVal);
                 student.behaviorEvaluations = evaluations;
                 updatedStudents[studentIndex] = student;
             }
        });
        onUpdateStudents(updatedStudents);
        setBehaviorChanges({});
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 3000);
    };

    const getBehaviorStatusColor = (percentage: number) => {
        if (percentage >= 80) return 'text-green-600 bg-green-100';
        if (percentage >= 60) return 'text-blue-600 bg-blue-100';
        if (percentage >= 40) return 'text-yellow-600 bg-yellow-100';
        return 'text-red-600 bg-red-100';
    };

    const getBehaviorStatusText = (percentage: number) => {
        if (percentage === 0) return 'Não Avaliado';
        if (percentage >= 80) return 'Excelente';
        if (percentage >= 60) return 'Bom';
        if (percentage >= 40) return 'Regular';
        return 'Precisa Melhorar';
    };

    if (!selectedSubject && availableSubjects.length === 0 && activeView === 'grades') {
         return (
            <div className="bg-white p-6 rounded-2xl shadow-lg">
                <button onClick={onBack} className="text-indigo-600 font-semibold mb-4 flex items-center hover:underline">
                    ← Voltar para Turmas
                </button>
                <div className="text-center text-gray-500 py-10 bg-gray-50 rounded-lg border border-dashed">
                    {currentUser.role === UserRole.PROFESSOR 
                        ? "Você não possui disciplinas atribuídas nesta turma."
                        : "Nenhuma disciplina encontrada para esta turma."}
                </div>
            </div>
        );
    }

    const hasChangesToSave = Object.keys(unsavedChanges).length > 0 || Object.keys(unsavedExamChanges).length > 0;

    return (
        <div className="bg-white p-6 rounded-2xl shadow-lg flex flex-col h-full w-full overflow-hidden">
            <PrintSettingsModal 
                isOpen={isPrintModalOpen} 
                onClose={() => setIsPrintModalOpen(false)} 
                subjects={subjects}
                onConfirm={handlePrintConfirm}
                onExport={handleExportExcel}
            />

            <div className="flex flex-col xl:flex-row xl:items-center justify-between mb-6 border-b pb-4 gap-4 flex-none">
                <div>
                    <button onClick={onBack} className="text-gray-500 text-sm font-semibold mb-1 hover:text-indigo-600 flex items-center">
                        ← Voltar
                    </button>
                    <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                        {turma.name}
                        {hasExam && <span className="text-xs bg-indigo-100 text-indigo-800 px-2 py-1 rounded-full border border-indigo-200">Classe com Exame</span>}
                    </h2>
                    <p className="text-sm text-gray-500">
                        {turma.classLevel} | {turma.shift} | {turma.academicYear} {turma.room ? `| ${turma.room}` : ''}
                    </p>
                </div>

                <div className="flex flex-wrap items-center gap-2">
                    {activeView === 'grades' && (
                        <button
                            onClick={() => setIsPrintModalOpen(true)}
                            className="flex items-center px-4 py-2 bg-gray-100 text-gray-700 hover:bg-gray-200 hover:text-gray-900 rounded-lg text-sm font-medium transition-colors"
                            title="Imprimir Pauta"
                        >
                            <PrinterIcon className="w-4 h-4 mr-2" />
                            Imprimir / Exportar
                        </button>
                    )}
                    <div className="flex space-x-1 bg-gray-100 p-1 rounded-lg self-start xl:self-auto overflow-x-auto">
                        <button
                            onClick={() => setActiveView('grades')}
                            className={`px-4 py-2 rounded-md text-sm font-medium transition-all whitespace-nowrap ${activeView === 'grades' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-600 hover:text-gray-800'}`}
                        >
                            <ChartBarIcon className="w-4 h-4 inline-block mr-2 mb-0.5" />
                            Pauta de Notas
                        </button>
                        <button
                            onClick={() => setActiveView('attendance')}
                            className={`px-4 py-2 rounded-md text-sm font-medium transition-all whitespace-nowrap ${activeView === 'attendance' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-600 hover:text-gray-800'}`}
                        >
                            <CalendarIcon className="w-4 h-4 inline-block mr-2 mb-0.5" />
                            Lista de Presenças
                        </button>
                        <button
                            onClick={() => setActiveView('behavior')}
                            className={`px-4 py-2 rounded-md text-sm font-medium transition-all whitespace-nowrap ${activeView === 'behavior' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-600 hover:text-gray-800'}`}
                        >
                            <ExclamationTriangleIcon className="w-4 h-4 inline-block mr-2 mb-0.5" />
                            Comportamento
                        </button>
                    </div>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto pr-2">
                {activeView === 'grades' && (
                    <>
                        <div className="flex flex-wrap items-center justify-between mb-6 gap-3">
                            <div className="flex gap-4 flex-wrap">
                                {!isOverviewMode && (
                                    <div>
                                        <label className="block text-xs font-medium text-gray-500 mb-1">Disciplina</label>
                                        <select 
                                            value={selectedSubjectId} 
                                            onChange={(e) => setSelectedSubjectId(e.target.value)}
                                            className="p-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 text-sm"
                                        >
                                            {availableSubjects.map(sub => (
                                                <option key={sub.id} value={sub.id}>{sub.name}</option>
                                            ))}
                                        </select>
                                    </div>
                                )}
                                <div>
                                    <label className="block text-xs font-medium text-gray-500 mb-1">Período</label>
                                    <select 
                                        value={selectedPeriod} 
                                        // @ts-ignore
                                        onChange={(e) => {
                                            setSelectedPeriod(e.target.value as PeriodOption);
                                            if (e.target.value === 'Situação Anual') setIsDetailedSummary(false);
                                        }}
                                        className="p-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 text-sm"
                                    >
                                        {periods.map(p => (
                                            <option key={p} value={p}>{p}</option>
                                        ))}
                                    </select>
                                </div>
                            </div>

                            <div className="flex flex-wrap items-center gap-3">
                                {saveStatus === 'saved' && <span className="text-green-600 font-bold animate-pulse text-sm">Salvo!</span>}
                                {isOverviewMode && selectedPeriod !== 'Situação Anual' && (
                                    <button 
                                        onClick={() => setIsDetailedSummary(!isDetailedSummary)}
                                        className={`flex items-center px-3 py-2 rounded-lg font-medium text-sm transition-colors border ${
                                            isDetailedSummary 
                                            ? 'bg-blue-100 text-blue-800 border-blue-200' 
                                            : 'bg-white text-gray-600 border-gray-300 hover:bg-gray-50'
                                        }`}
                                    >
                                        <BookOpenIcon className="w-4 h-4 mr-2" />
                                        {isDetailedSummary ? 'Visão Simples' : 'Resumo Detalhado'}
                                    </button>
                                )}
                                <button 
                                    onClick={() => {
                                        setIsOverviewMode(!isOverviewMode);
                                        setIsDetailedSummary(false);
                                    }}
                                    className="flex items-center px-3 py-2 bg-indigo-50 text-indigo-700 border border-indigo-100 rounded-lg font-medium hover:bg-indigo-100 transition-colors text-sm"
                                >
                                    {isOverviewMode ? (
                                        <>
                                            <CollectionIcon className="w-4 h-4 mr-2" />
                                            Ver por Disciplina
                                        </>
                                    ) : (
                                        <>
                                            <ChartBarIcon className="w-4 h-4 mr-2" />
                                            Visão Geral
                                        </>
                                    )}
                                </button>
                                {canEditGrades && !isOverviewMode && (
                                    <button 
                                        onClick={handleSaveGrades}
                                        disabled={!hasChangesToSave || saveStatus === 'saving'}
                                        className={`px-4 py-2 rounded-lg font-bold shadow-sm transition-all text-sm ${
                                            hasChangesToSave 
                                            ? 'bg-indigo-600 text-white hover:bg-indigo-700' 
                                            : 'bg-gray-300 text-gray-500 cursor-not-allowed'
                                        }`}
                                    >
                                        {saveStatus === 'saving' ? 'Salvando...' : 'Salvar Notas'}
                                    </button>
                                )}
                            </div>
                        </div>

                        <div className="overflow-x-auto border rounded-lg relative max-w-full">
                            <table className="min-w-full divide-y divide-gray-200 border-collapse">
                                <thead className="bg-gray-50">
                                    {isOverviewMode ? (
                                        isDetailedSummary && selectedPeriod !== 'Situação Anual' ? (
                                            <>
                                                <tr>
                                                    <th rowSpan={2} className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider min-w-[200px] sticky left-0 bg-gray-50 z-20 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)] border-r border-gray-200">Aluno</th>
                                                    {availableSubjects.map(sub => (
                                                        <th key={sub.id} colSpan={5} className="px-4 py-2 text-center text-sm font-bold text-indigo-800 uppercase tracking-wider border-b border-l border-gray-200 bg-indigo-50">
                                                            {sub.name}
                                                        </th>
                                                    ))}
                                                </tr>
                                                <tr>
                                                    {availableSubjects.map(sub => (
                                                        <React.Fragment key={sub.id}>
                                                            <th className="px-2 py-2 text-center text-xs font-medium text-gray-500 border-l border-gray-200 w-16">ACS1</th>
                                                            <th className="px-2 py-2 text-center text-xs font-medium text-gray-500 w-16">ACS2</th>
                                                            <th className="px-2 py-2 text-center text-xs font-medium text-gray-500 w-16 bg-gray-50">MAC</th>
                                                            <th className="px-2 py-2 text-center text-xs font-medium text-gray-500 w-16 font-bold">AT</th>
                                                            <th className="px-2 py-2 text-center text-xs font-bold text-indigo-900 w-16 bg-indigo-50">MF</th>
                                                        </React.Fragment>
                                                    ))}
                                                </tr>
                                            </>
                                        ) : (
                                            <tr>
                                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider min-w-[200px] sticky left-0 bg-gray-50 z-10 shadow-sm">Aluno</th>
                                                {availableSubjects.map(sub => (
                                                    <th key={sub.id} className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider min-w-[100px]">
                                                        {sub.name}
                                                    </th>
                                                ))}
                                                <th className="px-4 py-3 text-center text-xs font-bold text-indigo-900 uppercase tracking-wider min-w-[120px] bg-indigo-50">
                                                    Média Global
                                                </th>
                                            </tr>
                                        )
                                    ) : (
                                        <tr>
                                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider w-1/3">Aluno</th>
                                            {selectedPeriod === 'Situação Anual' ? (
                                                hasExam ? (
                                                    <>
                                                        <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider w-32">Média Interna</th>
                                                        <th className="px-4 py-3 text-center text-xs font-bold text-blue-700 uppercase tracking-wider w-32 bg-blue-50">Exame</th>
                                                        <th className="px-6 py-3 text-center text-xs font-bold text-indigo-900 uppercase tracking-wider w-32 bg-indigo-50">Nota Final</th>
                                                        <th className="px-6 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider w-32">Resultado</th>
                                                    </>
                                                ) : (
                                                    <>
                                                        <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider w-24">MF 1º T</th>
                                                        <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider w-24">MF 2º T</th>
                                                        <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider w-24">MF 3º T</th>
                                                        <th className="px-6 py-3 text-center text-xs font-bold text-indigo-900 uppercase tracking-wider w-24 bg-indigo-50">Média Anual</th>
                                                        <th className="px-6 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider w-32">Resultado</th>
                                                    </>
                                                )
                                            ) : (
                                                <>
                                                    <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider w-24">ACS 1</th>
                                                    <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider w-24">ACS 2</th>
                                                    <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider w-24 bg-gray-100">Média ACS</th>
                                                    <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider w-24 font-bold">AT (Prova)</th>
                                                    <th className="px-6 py-3 text-center text-xs font-bold text-indigo-900 uppercase tracking-wider w-24 bg-indigo-50">Média Final</th>
                                                </>
                                            )}
                                        </tr>
                                    )}
                                </thead>
                                <tbody className="bg-white divide-y divide-gray-200">
                                    {studentsInTurma.length > 0 ? studentsInTurma.map((student) => {
                                        if (isOverviewMode) {
                                            if (isDetailedSummary && selectedPeriod !== 'Situação Anual') {
                                                return (
                                                    <tr key={student.id} className="hover:bg-gray-50">
                                                        <td className="px-6 py-4 whitespace-nowrap sticky left-0 bg-white z-10 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)] border-r border-gray-200">
                                                            <div className="flex items-center">
                                                                <img className="h-8 w-8 rounded-full object-cover mr-3" src={student.profilePictureUrl} alt="" />
                                                                <div className="text-sm font-medium text-gray-900">{student.name}</div>
                                                            </div>
                                                        </td>
                                                        {availableSubjects.map(sub => {
                                                            const { acs1, acs2, mediaACS, at, finalGrade } = getDetailedGrades(student, sub.name, selectedPeriod);
                                                            return (
                                                                <React.Fragment key={sub.id}>
                                                                    <td className="px-2 py-4 text-center text-xs text-gray-500 border-l border-gray-200">{acs1 > 0 ? acs1 : '-'}</td>
                                                                    <td className="px-2 py-4 text-center text-xs text-gray-500">{acs2 > 0 ? acs2 : '-'}</td>
                                                                    <td className="px-2 py-4 text-center text-xs text-gray-600 font-medium bg-gray-50">{mediaACS > 0 ? mediaACS : '-'}</td>
                                                                    <td className="px-2 py-4 text-center text-xs text-gray-800 font-bold">{at > 0 ? at : '-'}</td>
                                                                    <td className={`px-2 py-4 text-center text-xs font-bold bg-indigo-50 ${finalGrade < 10 && finalGrade > 0 ? 'text-red-600' : 'text-indigo-900'}`}>{finalGrade > 0 ? finalGrade : '-'}</td>
                                                                </React.Fragment>
                                                            );
                                                        })}
                                                    </tr>
                                                );
                                            } else {
                                                let totalSum = 0;
                                                let subjectsCount = 0;
                                                return (
                                                    <tr key={student.id} className="hover:bg-gray-50">
                                                        <td className="px-6 py-4 whitespace-nowrap sticky left-0 bg-white z-10 shadow-sm border-r border-gray-100">
                                                            <div className="flex items-center">
                                                                <img className="h-8 w-8 rounded-full object-cover mr-3" src={student.profilePictureUrl} alt="" />
                                                                <div className="text-sm font-medium text-gray-900">{student.name}</div>
                                                            </div>
                                                        </td>
                                                        {availableSubjects.map(sub => {
                                                            const grade = getSubjectGrade(student, sub.name, selectedPeriod);
                                                            if (grade > 0) {
                                                                totalSum += grade;
                                                                subjectsCount++;
                                                            }
                                                            return (
                                                                <td key={sub.id} className={`px-4 py-4 text-center text-sm ${grade < 10 && grade > 0 ? 'text-red-600 font-medium' : 'text-gray-600'}`}>
                                                                    {grade > 0 ? grade.toFixed(1) : '-'}
                                                                </td>
                                                            );
                                                        })}
                                                        <td className="px-4 py-4 text-center text-sm font-bold text-indigo-900 bg-indigo-50 border-l border-gray-200">
                                                            {subjectsCount > 0 ? (totalSum / subjectsCount).toFixed(1) : '-'}
                                                        </td>
                                                    </tr>
                                                );
                                            }
                                        } else if (selectedPeriod === 'Situação Anual') {
                                            const mf1 = getGradeValue(student, 'grade', '1º Trimestre');
                                            const mf2 = getGradeValue(student, 'grade', '2º Trimestre');
                                            const mf3 = getGradeValue(student, 'grade', '3º Trimestre');
                                            const mediaInterna = parseFloat(((mf1 + mf2 + mf3) / 3).toFixed(1));

                                            if (hasExam && selectedSubject) {
                                                const examGrade = getExamGrade(student, selectedSubject.name);
                                                const finalWithExam = calculateExamFinalGrade(mediaInterna, examGrade);
                                                const isApproved = finalWithExam >= 10;
                                                return (
                                                    <tr key={student.id} className="hover:bg-gray-50">
                                                        <td className="px-6 py-4 whitespace-nowrap flex items-center">
                                                            <img className="h-8 w-8 rounded-full object-cover mr-3" src={student.profilePictureUrl} alt="" />
                                                            <div className="text-sm font-medium text-gray-900">{student.name}</div>
                                                        </td>
                                                        <td className="px-4 py-2 text-center text-sm text-gray-600 bg-gray-50">{mediaInterna.toFixed(1)}</td>
                                                        <td className="px-4 py-2">
                                                            <input 
                                                                type="number" 
                                                                min="0" 
                                                                max="20" 
                                                                step="0.1" 
                                                                value={examGrade} 
                                                                onChange={(e) => handleExamChange(student.id, e.target.value)} 
                                                                disabled={!canEditGrades} 
                                                                className={`w-full text-center border-blue-300 rounded-md shadow-sm sm:text-sm font-bold ${!canEditGrades ? 'bg-gray-100 text-gray-500' : 'bg-blue-50'}`}
                                                            />
                                                        </td>
                                                        <td className={`px-6 py-4 text-center text-sm font-bold bg-indigo-50 ${isApproved ? 'text-green-700' : 'text-red-600'}`}>{finalWithExam.toFixed(1)}</td>
                                                        <td className="px-6 py-4 text-center text-sm">
                                                            <span className={`px-2 py-1 rounded-full text-xs font-semibold ${isApproved ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                                                                {isApproved ? 'Aprovado' : 'Reprovado'}
                                                            </span>
                                                        </td>
                                                    </tr>
                                                );
                                            } else {
                                                const isApproved = mediaInterna >= 10;
                                                return (
                                                    <tr key={student.id} className="hover:bg-gray-50">
                                                        <td className="px-6 py-4 whitespace-nowrap flex items-center">
                                                            <img className="h-8 w-8 rounded-full object-cover mr-3" src={student.profilePictureUrl} alt="" />
                                                            <div className="text-sm font-medium text-gray-900">{student.name}</div>
                                                        </td>
                                                        <td className="px-4 py-2 text-center text-sm text-gray-600">{mf1.toFixed(1)}</td>
                                                        <td className="px-4 py-2 text-center text-sm text-gray-600">{mf2.toFixed(1)}</td>
                                                        <td className="px-4 py-2 text-center text-sm text-gray-600">{mf3.toFixed(1)}</td>
                                                        <td className={`px-6 py-4 text-center text-sm font-bold bg-indigo-50 ${isApproved ? 'text-green-700' : 'text-red-600'}`}>{mediaInterna.toFixed(1)}</td>
                                                        <td className="px-6 py-4 text-center text-sm">
                                                            <span className={`px-2 py-1 rounded-full text-xs font-semibold ${isApproved ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                                                                {isApproved ? 'Aprovado' : 'Reprovado'}
                                                            </span>
                                                        </td>
                                                    </tr>
                                                );
                                            }
                                        } else {
                                            const acs1 = getGradeValue(student, 'acs1');
                                            const acs2 = getGradeValue(student, 'acs2');
                                            const at = getGradeValue(student, 'at');
                                            const mediaACS = (acs1 + acs2) / 2;
                                            const finalGrade = calculateFinalGrade(acs1, acs2, at); 
                                            return (
                                                <tr key={student.id} className="hover:bg-gray-50">
                                                    <td className="px-6 py-4 whitespace-nowrap flex items-center">
                                                        <img className="h-8 w-8 rounded-full object-cover mr-3" src={student.profilePictureUrl} alt="" />
                                                        <div className="text-sm font-medium text-gray-900">{student.name}</div>
                                                    </td>
                                                    <td className="px-4 py-2"><input type="number" min="0" max="20" step="0.1" value={acs1} onChange={(e) => handleGradeChange(student.id, 'acs1', e.target.value)} disabled={!canEditGrades} className={`w-full text-center border-gray-300 rounded-md shadow-sm sm:text-sm ${!canEditGrades ? 'bg-gray-100 text-gray-500' : ''}`}/></td>
                                                    <td className="px-4 py-2"><input type="number" min="0" max="20" step="0.1" value={acs2} onChange={(e) => handleGradeChange(student.id, 'acs2', e.target.value)} disabled={!canEditGrades} className={`w-full text-center border-gray-300 rounded-md shadow-sm sm:text-sm ${!canEditGrades ? 'bg-gray-100 text-gray-500' : ''}`}/></td>
                                                    <td className="px-4 py-4 text-center text-sm font-medium text-gray-600 bg-gray-50">{mediaACS.toFixed(1)}</td>
                                                    <td className="px-4 py-2"><input type="number" min="0" max="20" step="0.1" value={at} onChange={(e) => handleGradeChange(student.id, 'at', e.target.value)} disabled={!canEditGrades} className={`w-full text-center border-gray-300 rounded-md shadow-sm sm:text-sm font-bold ${!canEditGrades ? 'bg-gray-100 text-gray-500' : 'bg-gray-50'}`}/></td>
                                                    <td className={`px-6 py-4 text-center text-sm font-bold bg-indigo-50 ${finalGrade >= 10 ? 'text-green-700' : 'text-red-600'}`}>{finalGrade.toFixed(1)}</td>
                                                </tr>
                                            );
                                        }
                                    }) : (
                                        <tr><td colSpan={10} className="text-center py-10 text-gray-500">Nenhum aluno nesta turma.</td></tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </>
                )}

                {activeView === 'attendance' && (
                    <>
                         <div className="flex flex-wrap items-center justify-between mb-6 gap-3">
                            <div className="flex items-center space-x-4">
                                 <div>
                                    <label className="block text-xs font-medium text-gray-500 mb-1">Data da Chamada</label>
                                    <input 
                                        type="date" 
                                        value={attendanceDate}
                                        onChange={(e) => setAttendanceDate(e.target.value)}
                                        className="p-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 text-sm"
                                    />
                                </div>
                                {!canEditAttendance && (
                                    <div className="flex items-end h-full pb-1">
                                        <span className="text-sm text-amber-600 bg-amber-50 px-3 py-1 rounded-full border border-amber-200">
                                            Somente Leitura
                                        </span>
                                    </div>
                                )}
                            </div>
                            {canEditAttendance && (
                                 <div className="flex items-center space-x-2">
                                    {saveStatus === 'saved' && <span className="text-green-600 font-bold animate-pulse text-sm">Presenças Salvas com Sucesso!</span>}
                                    <button 
                                        onClick={handleSaveAttendance}
                                        disabled={Object.keys(attendanceChanges).length === 0 || saveStatus === 'saving'}
                                        className={`px-4 py-2 rounded-lg font-bold shadow-sm transition-all text-sm ${
                                            Object.keys(attendanceChanges).length > 0 
                                            ? 'bg-indigo-600 text-white hover:bg-indigo-700' 
                                            : 'bg-gray-300 text-gray-500 cursor-not-allowed'
                                        }`}
                                    >
                                        {saveStatus === 'saving' ? 'Salvando...' : 'Salvar Presenças'}
                                    </button>
                                 </div>
                            )}
                         </div>

                         <div className="overflow-x-auto border rounded-lg">
                            <table className="min-w-full divide-y divide-gray-200">
                                <thead className="bg-gray-50">
                                    <tr>
                                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider w-1/3">Aluno</th>
                                        <th className="px-6 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">Faltas no Ano</th>
                                        <th className="px-6 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">Status</th>
                                    </tr>
                                </thead>
                                <tbody className="bg-white divide-y divide-gray-200">
                                    {studentsInTurma.length > 0 ? studentsInTurma.map(student => {
                                        const status = getAttendanceStatus(student);
                                        const totalAbsences = getTotalAbsences(student);
                                        return (
                                            <tr key={student.id} className="hover:bg-gray-50">
                                                 <td className="px-6 py-4 whitespace-nowrap flex items-center">
                                                    <img className="h-8 w-8 rounded-full object-cover mr-3" src={student.profilePictureUrl} alt="" />
                                                    <div>
                                                        <div className="text-sm font-medium text-gray-900">{student.name}</div>
                                                        <div className="text-xs text-gray-500">{student.id}</div>
                                                    </div>
                                                </td>
                                                <td className="px-6 py-4 text-center">
                                                    <span className={`px-2.5 py-0.5 rounded-full text-xs font-bold ${totalAbsences > 5 ? 'bg-red-100 text-red-700' : 'bg-gray-100 text-gray-600'}`}>
                                                        {totalAbsences}
                                                    </span>
                                                </td>
                                                <td className="px-6 py-4 text-center">
                                                    <div className="flex items-center justify-center space-x-4">
                                                        {(['Presente', 'Ausente', 'Atrasado'] as const).map(opt => (
                                                            <label key={opt} className={`flex items-center space-x-1 cursor-pointer p-2 rounded-md transition-colors ${status === opt ? 'bg-gray-100 ring-1 ring-gray-300' : ''}`}>
                                                                <input 
                                                                    type="radio" 
                                                                    name={`attendance-${student.id}`}
                                                                    value={opt}
                                                                    checked={status === opt}
                                                                    onChange={() => handleAttendanceChange(student.id, opt)}
                                                                    disabled={!canEditAttendance}
                                                                    className={`h-4 w-4 ${
                                                                        opt === 'Presente' ? 'text-green-600' : 
                                                                        opt === 'Ausente' ? 'text-red-600' : 'text-yellow-500'
                                                                    } focus:ring-indigo-500`}
                                                                />
                                                                <span className={`text-sm font-medium ${
                                                                    opt === 'Presente' ? 'text-green-700' : 
                                                                    opt === 'Ausente' ? 'text-red-700' : 'text-yellow-700'
                                                                }`}>{opt}</span>
                                                            </label>
                                                        ))}
                                                    </div>
                                                </td>
                                            </tr>
                                        )
                                    }) : (
                                        <tr><td colSpan={3} className="text-center py-10 text-gray-500">Nenhum aluno nesta turma.</td></tr>
                                    )}
                                </tbody>
                            </table>
                         </div>
                    </>
                )}

                {activeView === 'behavior' && (
                    <>
                         <div className="flex flex-wrap items-center justify-between mb-6 gap-3">
                            <div>
                                <label className="block text-xs font-medium text-gray-500 mb-1">Período de Avaliação</label>
                                <select 
                                    value={selectedPeriod} 
                                    // @ts-ignore
                                    onChange={(e) => setSelectedPeriod(e.target.value as PeriodOption)}
                                    className="p-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 text-sm"
                                >
                                    {periods.filter(p => p !== 'Situação Anual').map(p => (
                                        <option key={p} value={p}>{p}</option>
                                    ))}
                                </select>
                            </div>
                            {canEditBehavior && selectedPeriod !== 'Situação Anual' && (
                                 <div className="flex items-center space-x-2">
                                    {saveStatus === 'saved' && <span className="text-green-600 font-bold animate-pulse text-sm">Avaliações Salvas!</span>}
                                    <button 
                                        onClick={handleSaveBehavior}
                                        disabled={Object.keys(behaviorChanges).length === 0 || saveStatus === 'saving'}
                                        className={`px-4 py-2 rounded-lg font-bold shadow-sm transition-all text-sm ${
                                            Object.keys(behaviorChanges).length > 0 
                                            ? 'bg-indigo-600 text-white hover:bg-indigo-700' 
                                            : 'bg-gray-300 text-gray-500 cursor-not-allowed'
                                        }`}
                                    >
                                        {saveStatus === 'saving' ? 'Salvando...' : 'Salvar Avaliações'}
                                    </button>
                                 </div>
                            )}
                         </div>

                         <div className="border rounded-lg overflow-hidden">
                            <div className="bg-gray-50 px-6 py-3 border-b grid grid-cols-12 gap-4 text-xs font-medium text-gray-500 uppercase tracking-wider">
                                 <div className="col-span-4">Aluno</div>
                                 <div className="col-span-4 text-center">Status Global</div>
                                 <div className="col-span-4 text-right">Ações</div>
                            </div>
                            <div className="bg-white divide-y divide-gray-200">
                                 {studentsInTurma.length > 0 ? studentsInTurma.map(student => {
                                     const evaluation = getStudentBehaviorEval(student);
                                     const isExpanded = expandedStudentId === student.id;
                                     const statusColor = getBehaviorStatusColor(evaluation.percentage);
                                     const statusText = getBehaviorStatusText(evaluation.percentage);

                                     return (
                                         <React.Fragment key={student.id}>
                                             <div className={`px-6 py-4 grid grid-cols-12 gap-4 items-center hover:bg-gray-50 transition-colors ${isExpanded ? 'bg-gray-50' : ''}`}>
                                                 <div className="col-span-4 flex items-center">
                                                     <img className="h-10 w-10 rounded-full object-cover mr-3" src={student.profilePictureUrl} alt="" />
                                                     <div>
                                                         <div className="text-sm font-medium text-gray-900">{student.name}</div>
                                                         <div className="text-xs text-gray-500">{student.id}</div>
                                                     </div>
                                                 </div>
                                                 <div className="col-span-4 flex flex-col items-center justify-center">
                                                     <div className="w-full max-w-xs bg-gray-200 rounded-full h-2.5 mb-1">
                                                         <div className="bg-indigo-600 h-2.5 rounded-full" style={{ width: `${evaluation.percentage}%` }}></div>
                                                     </div>
                                                     <div className="text-xs flex gap-2">
                                                         <span className="font-bold text-gray-700">{evaluation.percentage}%</span>
                                                         <span className={`px-2 rounded-full font-semibold ${statusColor}`}>
                                                             {statusText}
                                                         </span>
                                                     </div>
                                                 </div>
                                                 <div className="col-span-4 text-right">
                                                     <button 
                                                        onClick={() => setExpandedStudentId(isExpanded ? null : student.id)}
                                                        className="text-indigo-600 hover:text-indigo-900 font-medium text-sm focus:outline-none"
                                                     >
                                                         {isExpanded ? 'Ocultar Avaliação' : 'Avaliar / Ver Detalhes'}
                                                         <ChevronDownIcon className={`w-4 h-4 inline-block ml-1 transition-transform ${isExpanded ? 'rotate-180' : ''}`}/>
                                                     </button>
                                                 </div>
                                             </div>
                                             {isExpanded && (
                                                 <div className="px-6 py-4 bg-gray-50 border-t border-gray-100 shadow-inner">
                                                     <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-4">
                                                         {behaviorCriteriaList.map(criteria => (
                                                             <div key={criteria.key} className="flex items-center justify-between bg-white p-3 rounded-lg border border-gray-200">
                                                                 <span className="text-sm font-medium text-gray-700">{criteria.label}</span>
                                                                 <div className="flex space-x-1">
                                                                     {[1, 2, 3, 4, 5].map(star => (
                                                                         <button
                                                                            key={star}
                                                                            onClick={() => handleStarClick(student.id, criteria.key as keyof BehaviorEvaluation['scores'], star)}
                                                                            disabled={!canEditBehavior || selectedPeriod === 'Situação Anual'}
                                                                            className={`focus:outline-none transition-transform hover:scale-110 ${!canEditBehavior ? 'cursor-default' : ''}`}
                                                                         >
                                                                             <StarIcon 
                                                                                className={`w-6 h-6 ${star <= (evaluation.scores[criteria.key as keyof BehaviorEvaluation['scores']] || 0) ? 'text-yellow-400' : 'text-gray-300'}`} 
                                                                                filled={star <= (evaluation.scores[criteria.key as keyof BehaviorEvaluation['scores']] || 0)}
                                                                             />
                                                                         </button>
                                                                     ))}
                                                                 </div>
                                                             </div>
                                                         ))}
                                                     </div>
                                                 </div>
                                             )}
                                         </React.Fragment>
                                     );
                                 }) : (
                                     <div className="text-center py-10 text-gray-500">Nenhum aluno nesta turma.</div>
                                 )}
                            </div>
                         </div>
                    </>
                )}
            </div>
        </div>
    );
};

export default TurmaDetails;

import React, { useState, useMemo, useEffect } from 'react';
import { User, Student, AcademicYear, SchoolSettings, Turma, FinancialSettings, AppNotification, UserRole, Grade, AttendanceRecord, Subject, PaymentRecord } from '../types';
import { LogoutIcon, GraduationCapIcon, ChevronDownIcon, AcademicCapIcon, CheckCircleIcon, ExclamationTriangleIcon, CloseIcon, CalendarIcon, StarIcon, UsersIcon, CurrencyDollarIcon, ClockIcon, ChartBarIcon, BookOpenIcon, PrinterIcon } from './icons/IconComponents';
import Sidebar from './Sidebar';
import Header from './Header';
import { View } from './Dashboard';

interface GuardianPortalProps {
  user: User;
  onLogout: () => void;
  onUpdateCurrentUser: (data: Partial<User>) => void;
  students: Student[];
  onStudentsChange?: (students: Student[]) => void;
  academicYears: AcademicYear[];
  schoolSettings: SchoolSettings;
  turmas: Turma[];
  financialSettings: FinancialSettings;
  activeView?: View;
  setActiveView?: (view: View) => void;
  onAddNotifications?: (notifications: AppNotification[]) => void;
  users?: User[];
}

const StatementModal: React.FC<{ 
    isOpen: boolean; 
    onClose: () => void; 
    student: Student | null; 
    year: number; 
    financialSettings: FinancialSettings;
}> = ({ isOpen, onClose, student, year, financialSettings }) => {
    if (!isOpen || !student) return null;

    const formatCurrency = (val: number) => {
        return val.toLocaleString('pt-MZ', { style: 'currency', currency: financialSettings.currency || 'MZN' });
    };

    const ledger = useMemo(() => {
        const items: { date: string; desc: string; debit: number; credit: number }[] = [];
        const startMonth = 2;
        const now = new Date();
        const currentMonth = year === now.getFullYear() ? now.getMonth() + 1 : 11;

        let monthlyFee = financialSettings.monthlyFee;
        if (student.desiredClass) {
            const specific = financialSettings.classSpecificFees?.find(c => c.classLevel === student.desiredClass);
            if (specific) monthlyFee = specific.monthlyFee;
        }

        for (let m = startMonth; m <= currentMonth; m++) {
            items.push({ 
                date: `${year}-${m.toString().padStart(2, '0')}-01`, 
                desc: `MENSALIDADE - MÊS ${m}`, 
                debit: monthlyFee, 
                credit: 0 
            });
        }

        (student.payments || []).filter(p => p.academicYear === year).forEach(p => {
            items.push({ 
                date: p.date, 
                desc: `PAGAMENTO: ${p.type} (${p.method || 'Geral'})`, 
                debit: 0, 
                credit: p.amount 
            });
        });

        return items.sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());
    }, [student, year, financialSettings]);

    let runningBalance = 0;

    return (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-3xl overflow-hidden flex flex-col max-h-[90vh]">
                <header className="p-8 border-b bg-slate-50 flex justify-between items-center">
                    <div>
                        <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Extrato de Conta Corrente</h3>
                        <p className="text-sm font-bold text-indigo-500">{student.name} • Ano Letivo {year}</p>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-white rounded-full transition-colors">
                        <CloseIcon className="w-8 h-8 text-slate-400" />
                    </button>
                </header>
                <div className="flex-1 overflow-y-auto p-8">
                    <table className="w-full text-sm">
                        <thead className="text-[10px] font-black uppercase text-slate-400 border-b">
                            <tr>
                                <th className="text-left py-4">Data</th>
                                <th className="text-left py-4">Descrição</th>
                                <th className="text-right py-4">Débito</th>
                                <th className="text-right py-4">Crédito</th>
                                <th className="text-right py-4">Saldo</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {ledger.map((item, i) => {
                                runningBalance += (item.debit - item.credit);
                                return (
                                    <tr key={i} className="hover:bg-slate-50 transition-colors">
                                        <td className="py-4 text-slate-500 whitespace-nowrap">{new Date(item.date).toLocaleDateString()}</td>
                                        <td className="py-4 font-bold text-slate-700">{item.desc}</td>
                                        <td className="py-4 text-right text-rose-600 font-bold">{item.debit > 0 ? formatCurrency(item.debit) : '-'}</td>
                                        <td className="py-4 text-right text-emerald-600 font-bold">{item.credit > 0 ? formatCurrency(item.credit) : '-'}</td>
                                        <td className={`py-4 text-right font-black ${runningBalance > 0 ? 'text-rose-700' : 'text-emerald-700'}`}>
                                            {formatCurrency(runningBalance)}
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
                <footer className="p-8 bg-slate-900 text-white flex justify-between items-center">
                    <div>
                        <p className="text-[10px] font-black uppercase text-indigo-300 mb-1">Saldo Corrente</p>
                        <p className="text-3xl font-black">{formatCurrency(Math.abs(runningBalance))}</p>
                        <p className="text-[10px] uppercase font-bold">{runningBalance > 0 ? 'Dívida a Regularizar' : 'Situação Regularizada'}</p>
                    </div>
                    <button onClick={onClose} className="bg-indigo-600 px-8 py-3 rounded-xl font-black uppercase text-xs tracking-widest hover:bg-indigo-700 transition-all">Fechar Extrato</button>
                </footer>
            </div>
        </div>
    );
};

const StudentInfoCard: React.FC<{ 
    student: Student; 
    selectedYear: number | null; 
    academicYears: AcademicYear[]; 
    schoolSettings: SchoolSettings; 
    turmas: Turma[]; 
    financialSettings: FinancialSettings;
    onOpenStatement: (s: Student) => void;
}> = ({ student, selectedYear, academicYears, schoolSettings, turmas, financialSettings, onOpenStatement }) => {
    const [activeTab, setActiveTab] = useState<'grades' | 'attendance' | 'financial' | 'behavior'>('grades');

    const activeTurma = useMemo(() => {
        if (!selectedYear) return null;
        return turmas.find(t => t.academicYear === selectedYear && t.studentIds.includes(student.id));
    }, [turmas, selectedYear, student.id]);

    const academicYearConfig = useMemo(() => academicYears.find(ay => ay.year === selectedYear), [academicYears, selectedYear]);

    const subjects = useMemo(() => {
        if (!activeTurma || !academicYearConfig) return [];
        return academicYearConfig.subjectsByClass?.find(cs => cs.classLevel === activeTurma.classLevel)?.subjects || [];
    }, [activeTurma, academicYearConfig]);

    const hasExam = useMemo(() => {
        if (!activeTurma || !academicYearConfig) return false;
        return !!academicYearConfig.subjectsByClass?.find(cs => cs.classLevel === activeTurma.classLevel)?.hasExam;
    }, [activeTurma, academicYearConfig]);

    const calcMF = (acs1: number = 0, acs2: number = 0, at: number = 0) => {
        const p1 = schoolSettings.evaluationWeights?.p1 || 40;
        const p2 = schoolSettings.evaluationWeights?.p2 || 60;
        const mediaACS = (acs1 + acs2) / 2;
        const mf = ((mediaACS * p1) + (at * p2)) / (p1 + p2);
        return parseFloat(mf.toFixed(1));
    };

    const academicSummary = useMemo(() => {
        if (!selectedYear || subjects.length === 0) return { globalAvg: 0, passed: false };
        let totalSum = 0; let count = 0;
        subjects.forEach(sub => {
            const t1 = student.grades?.find(g => g.subject === sub.name && g.period === '1º Trimestre' && g.academicYear === selectedYear);
            const t2 = student.grades?.find(g => g.subject === sub.name && g.period === '2º Trimestre' && g.academicYear === selectedYear);
            const t3 = student.grades?.find(g => g.subject === sub.name && g.period === '3º Trimestre' && g.academicYear === selectedYear);

            const mf1 = t1 ? calcMF(t1.acs1, t1.acs2, t1.at) : 0;
            const mf2 = t2 ? calcMF(t2.acs1, t2.acs2, t2.at) : 0;
            const mf3 = t3 ? calcMF(t3.acs1, t3.acs2, t3.at) : 0;

            const valid = [mf1, mf2, mf3].filter(m => m > 0);
            const mediaI = valid.length > 0 ? valid.reduce((a,b) => a+b, 0) / valid.length : 0;

            let final = mediaI;
            if (hasExam) {
                const ex = student.examGrades?.find(e => e.subject === sub.name && e.academicYear === selectedYear);
                if (ex) {
                    const w1 = schoolSettings.examWeights?.internal || 50;
                    const w2 = schoolSettings.examWeights?.exam || 50;
                    final = ((mediaI * w1) + (ex.grade * w2)) / (w1 + w2);
                }
            }
            if (final > 0) { totalSum += final; count++; }
        });
        const avg = count > 0 ? parseFloat((totalSum / count).toFixed(1)) : 0;
        return { globalAvg: avg, passed: avg >= 9.5 };
    }, [student, subjects, selectedYear, hasExam, schoolSettings]);

    const attendanceSummary = useMemo(() => {
        if (!selectedYear) return { total: 0, present: 0, absent: 0, late: 0, history: [] };

        // Robust year extraction
        const getYearFromStr = (d: string) => parseInt(d.split('-')[0]) || 0;

        const records = (student.attendance || []).filter(a => {
            const recordYear = getYearFromStr(a.date);
            return recordYear === Number(selectedYear);
        });

        const present = records.filter(r => r.status === 'Presente').length;
        const absent = records.filter(r => r.status === 'Ausente').length;
        const late = records.filter(r => r.status === 'Atrasado').length;

        return { 
            total: records.length, 
            present, 
            absent, 
            late, 
            history: records.sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()) 
        };
    }, [student.attendance, selectedYear]);

    return (
        <div className="bg-white rounded-[2rem] shadow-2xl border border-gray-100 overflow-hidden mb-10 transition-all hover:shadow-indigo-100">
            <div className="p-8 bg-slate-900 text-white relative">
                <div className="flex flex-col md:flex-row items-center gap-8 relative z-10">
                    <img className="h-24 w-24 rounded-3xl object-cover border-4 border-indigo-500 shadow-xl" src={student.profilePictureUrl || 'https://i.pravatar.cc/150'} alt="" />
                    <div className="flex-1 text-center md:text-left">
                        <h3 className="text-3xl font-black uppercase tracking-tight">{student.name}</h3>
                        <p className="text-indigo-400 text-xs font-black uppercase tracking-widest mt-2">
                             {activeTurma ? `${activeTurma.classLevel} • ${activeTurma.name}` : student.desiredClass}
                        </p>
                    </div>
                    <div className="bg-indigo-600 p-6 rounded-3xl text-center min-w-[160px] border border-indigo-400/30 shadow-2xl">
                        <p className="text-[10px] font-black uppercase text-indigo-100 mb-1 tracking-widest">Média Global Anual</p>
                        <p className="text-5xl font-black">{academicSummary.globalAvg || '--'}</p>
                        <p className={`text-[10px] font-bold mt-1 ${academicSummary.passed ? 'text-emerald-300' : 'text-rose-300'}`}>
                            {academicSummary.passed ? 'APROVADO' : 'PENDENTE'}
                        </p>
                    </div>
                </div>
            </div>

            <div className="flex bg-slate-50 border-b overflow-x-auto no-scrollbar p-2 gap-2">
                {[
                    { id: 'grades', label: 'Pauta de Notas', icon: <ChartBarIcon className="w-4 h-4" /> },
                    { id: 'attendance', label: 'Assiduidade', icon: <CalendarIcon className="w-4 h-4" /> },
                    { id: 'financial', label: 'Financeiro', icon: <CurrencyDollarIcon className="w-4 h-4" /> },
                    { id: 'behavior', label: 'Conduta', icon: <StarIcon className="w-4 h-4" /> }
                ].map(tab => (
                    <button 
                        key={tab.id} 
                        onClick={() => setActiveTab(tab.id as any)} 
                        className={`flex items-center px-6 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all whitespace-nowrap ${
                            activeTab === tab.id 
                            ? 'bg-white text-indigo-600 shadow-md border border-indigo-100' 
                            : 'text-slate-400 hover:text-slate-600'
                        }`}
                    >
                        <span className="mr-2">{tab.icon}</span>{tab.label}
                    </button>
                ))}
            </div>

            <div className="p-4 md:p-10">
                {activeTab === 'grades' && (
                    <div className="overflow-x-auto -mx-4 md:mx-0 rounded-2xl border border-slate-100">
                        <table className="min-w-full text-[10px] border-collapse">
                            <thead>
                                <tr className="bg-slate-900 text-white font-black uppercase tracking-tighter">
                                    <th className="p-4 text-left border-r border-white/10 sticky left-0 bg-slate-900 z-10">Disciplina</th>
                                    <th colSpan={5} className="p-2 text-center border-r border-white/10 bg-indigo-900/50">1º Trimestre</th>
                                    <th colSpan={5} className="p-2 text-center border-r border-white/10 bg-slate-800">2º Trimestre</th>
                                    <th colSpan={5} className="p-2 text-center border-r border-white/10 bg-indigo-900/50">3º Trimestre</th>
                                    {hasExam && <th className="p-4 text-center border-r border-white/10 bg-amber-600">Exame</th>}
                                    <th className="p-4 text-right bg-indigo-600">Média Anual</th>
                                </tr>
                                <tr className="bg-slate-100 text-slate-500 font-bold uppercase text-[8px] border-b">
                                    <th className="p-2 border-r sticky left-0 bg-slate-100 z-10"></th>
                                    {[1,2,3].map(t => (
                                        <React.Fragment key={t}>
                                            <th className="p-1 border-r text-center">ACS1</th>
                                            <th className="p-1 border-r text-center">ACS2</th>
                                            <th className="p-1 border-r text-center bg-gray-50">MAC</th>
                                            <th className="p-1 border-r text-center">AT</th>
                                            <th className="p-1 border-r text-center bg-indigo-50 font-black">MF</th>
                                        </React.Fragment>
                                    ))}
                                    {hasExam && <th className="p-1 border-r text-center bg-amber-50 font-black">Nota</th>}
                                    <th className="p-1 text-right bg-indigo-100 font-black px-4">FINAL</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100 text-[11px]">
                                {subjects.length > 0 ? subjects.map(sub => {
                                    const g1 = student.grades?.find(g => g.subject === sub.name && g.period === '1º Trimestre' && g.academicYear === selectedYear);
                                    const g2 = student.grades?.find(g => g.subject === sub.name && g.period === '2º Trimestre' && g.academicYear === selectedYear);
                                    const g3 = student.grades?.find(g => g.subject === sub.name && g.period === '3º Trimestre' && g.academicYear === selectedYear);
                                    const ex = student.examGrades?.find(e => e.subject === sub.name && e.academicYear === selectedYear);

                                    const getRowData = (g: Grade | undefined) => {
                                        const acs1 = g?.acs1 || 0;
                                        const acs2 = g?.acs2 || 0;
                                        const at = g?.at || 0;
                                        const mac = parseFloat(((acs1 + acs2) / 2).toFixed(1));
                                        const mf = calcMF(acs1, acs2, at);
                                        return { acs1, acs2, mac, at, mf };
                                    };

                                    const r1 = getRowData(g1);
                                    const r2 = getRowData(g2);
                                    const r3 = getRowData(g3);

                                    const valMfs = [r1.mf, r2.mf, r3.mf].filter(m => m > 0);
                                    const medI = valMfs.length > 0 ? valMfs.reduce((a,b)=>a+b,0)/valMfs.length : 0;
                                    let final = medI;
                                    if (hasExam && ex) {
                                        const w1 = schoolSettings.examWeights?.internal || 50;
                                        const w2 = schoolSettings.examWeights?.exam || 50;
                                        final = ((medI * w1) + (ex.grade * w2)) / (w1 + w2);
                                    }

                                    const renderVal = (v: number) => v > 0 ? v : '-';
                                    const renderMF = (v: number) => (
                                        <span className={`font-black ${v >= 9.5 ? 'text-indigo-600' : v > 0 ? 'text-rose-500' : 'text-slate-300'}`}>
                                            {v > 0 ? v.toFixed(1) : '-'}
                                        </span>
                                    );

                                    return (
                                        <tr key={sub.id} className="hover:bg-indigo-50/30 transition-colors">
                                            <td className="p-3 font-bold text-slate-700 border-r sticky left-0 bg-white z-10">{sub.name}</td>
                                            <td className="p-1 text-center border-r">{renderVal(r1.acs1)}</td>
                                            <td className="p-1 text-center border-r">{renderVal(r1.acs2)}</td>
                                            <td className="p-1 text-center border-r bg-gray-50 text-slate-400">{renderVal(r1.mac)}</td>
                                            <td className="p-1 text-center border-r font-bold">{renderVal(r1.at)}</td>
                                            <td className="p-1 text-center bg-indigo-50/50 border-r">{renderMF(r1.mf)}</td>
                                            <td className="p-1 text-center border-r">{renderVal(r2.acs1)}</td>
                                            <td className="p-1 text-center border-r">{renderVal(r2.acs2)}</td>
                                            <td className="p-1 text-center border-r bg-gray-50 text-slate-400">{renderVal(r2.mac)}</td>
                                            <td className="p-1 text-center border-r font-bold">{renderVal(r2.at)}</td>
                                            <td className="p-1 text-center bg-slate-100 border-r">{renderMF(r2.mf)}</td>
                                            <td className="p-1 text-center border-r">{renderVal(r3.acs1)}</td>
                                            <td className="p-1 text-center border-r">{renderVal(r3.acs2)}</td>
                                            <td className="p-1 text-center border-r bg-gray-50 text-slate-400">{renderVal(r3.mac)}</td>
                                            <td className="p-1 text-center border-r font-bold">{renderVal(r3.at)}</td>
                                            <td className="p-1 text-center bg-indigo-50/50 border-r">{renderMF(r3.mf)}</td>
                                            {hasExam && <td className="p-1 text-center bg-amber-50 border-r font-black text-amber-700">{ex?.grade ? ex.grade.toFixed(1) : '-'}</td>}
                                            <td className={`p-3 text-right font-black bg-indigo-100/30 ${final >= 9.5 ? 'text-slate-900' : 'text-rose-600'}`}>
                                                {final > 0 ? final.toFixed(1) : '-'}
                                            </td>
                                        </tr>
                                    );
                                }) : (
                                    <tr><td colSpan={20} className="py-20 text-center text-slate-400 font-black uppercase tracking-widest opacity-50">Sem pauta disponível.</td></tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                )}

                {activeTab === 'attendance' && (
                    <div className="space-y-10 animate-fade-in">
                        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                            <div className="bg-emerald-50 p-6 rounded-3xl border border-emerald-100 flex items-center justify-between shadow-sm">
                                <div>
                                    <p className="text-[10px] font-black text-emerald-600 uppercase mb-1 tracking-widest">Presenças</p>
                                    <p className="text-4xl font-black text-emerald-700">{attendanceSummary.present}</p>
                                </div>
                                <div className="bg-white p-4 rounded-2xl shadow-sm text-emerald-500"><CheckCircleIcon className="w-10 h-10" /></div>
                            </div>
                            <div className="bg-rose-50 p-6 rounded-3xl border border-rose-100 flex items-center justify-between shadow-sm">
                                <div>
                                    <p className="text-[10px] font-black text-rose-600 uppercase mb-1 tracking-widest">Faltas</p>
                                    <p className="text-4xl font-black text-rose-700">{attendanceSummary.absent}</p>
                                </div>
                                <div className="bg-white p-4 rounded-2xl shadow-sm text-rose-500"><CloseIcon className="w-10 h-10" /></div>
                            </div>
                            <div className="bg-amber-50 p-6 rounded-3xl border border-amber-100 flex items-center justify-between shadow-sm">
                                <div>
                                    <p className="text-[10px] font-black text-amber-600 uppercase mb-1 tracking-widest">Atrasos</p>
                                    <p className="text-4xl font-black text-amber-700">{attendanceSummary.late}</p>
                                </div>
                                <div className="bg-white p-4 rounded-2xl shadow-sm text-amber-500"><ClockIcon className="w-10 h-10" /></div>
                            </div>
                            <div className="bg-indigo-50 p-6 rounded-3xl border border-indigo-100 flex items-center justify-between shadow-sm">
                                <div>
                                    <p className="text-[10px] font-black text-indigo-600 uppercase mb-1 tracking-widest">Assiduidade</p>
                                    <p className="text-4xl font-black text-indigo-700">{attendanceSummary.total > 0 ? Math.round((attendanceSummary.present / attendanceSummary.total) * 100) : 100}%</p>
                                </div>
                                <div className="bg-white p-4 rounded-2xl shadow-sm text-indigo-500"><ChartBarIcon className="w-10 h-10" /></div>
                            </div>
                        </div>

                        <div>
                            <h4 className="text-sm font-black text-slate-800 uppercase tracking-widest mb-6 flex items-center">
                                <CalendarIcon className="w-5 h-5 mr-3 text-indigo-600" />
                                Histórico Detalhado de Incidentes
                            </h4>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                {attendanceSummary.history.filter(a => a.status !== 'Presente').length > 0 ? (
                                    attendanceSummary.history.filter(a => a.status !== 'Presente').map((record, i) => (
                                        <div key={i} className="flex items-center justify-between p-5 bg-white rounded-2xl border border-slate-100 shadow-sm transition-transform hover:scale-[1.01]">
                                            <div className="flex items-center">
                                                <div className={`p-3 rounded-xl mr-4 ${record.status === 'Ausente' ? 'bg-rose-100 text-rose-600' : 'bg-amber-100 text-amber-600'}`}>
                                                    {record.status === 'Ausente' ? <CloseIcon className="w-6 h-6" /> : <ClockIcon className="w-6 h-6" />}
                                                </div>
                                                <div>
                                                    <p className="text-md font-black text-slate-800">
                                                        {new Date(record.date).toLocaleDateString('pt-PT', { day: 'numeric', month: 'long', year: 'numeric' })}
                                                    </p>
                                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{record.status}</p>
                                                </div>
                                            </div>
                                            <span className="text-[9px] font-black text-slate-300 uppercase bg-slate-50 px-3 py-1 rounded-full">Automático</span>
                                        </div>
                                    ))
                                ) : (
                                    <div className="col-span-full text-center py-16 bg-emerald-50 rounded-[2.5rem] border border-emerald-100">
                                        <CheckCircleIcon className="w-12 h-12 text-emerald-500 mx-auto mb-4" />
                                        <p className="text-emerald-700 font-black uppercase tracking-widest text-sm">Nenhuma falta ou atraso registado.</p>
                                        <p className="text-emerald-600/60 text-xs mt-1">O aluno possui 100% de assiduidade neste período.</p>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                )}

                {activeTab === 'financial' && (
                    <div className="bg-slate-50 p-10 rounded-[3rem] border border-slate-100 flex flex-col md:flex-row justify-between items-center gap-10">
                        <div className="text-center md:text-left flex-1">
                            <p className="text-xs text-indigo-500 font-black uppercase tracking-widest mb-2">Situação Financeira</p>
                            <h4 className="text-3xl font-black text-slate-800 tracking-tight leading-tight">Extrato de Conta Corrente</h4>
                            <p className="text-sm text-slate-500 mt-2 font-medium max-w-lg">Consulte mensalidades, faturas e todos os pagamentos efetuados no ano letivo corrente de forma detalhada.</p>
                        </div>
                        <button 
                            onClick={() => onOpenStatement(student)}
                            className="w-full md:w-auto bg-slate-900 text-white px-12 py-5 rounded-[2rem] font-black uppercase text-xs tracking-[0.2em] shadow-2xl hover:bg-indigo-600 transition-all transform active:scale-95 flex items-center justify-center"
                        >
                            <PrinterIcon className="w-5 h-5 mr-3" />
                            Ver Extrato Digital
                        </button>
                    </div>
                )}

                {activeTab === 'behavior' && (
                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 animate-fade-in">
                        {['1º Trimestre', '2º Trimestre', '3º Trimestre'].map(p => {
                            const evalObj = student.behaviorEvaluations?.find(b => b.period === p && b.academicYear === selectedYear);
                            const score = evalObj?.percentage || 0;
                            return (
                                <div key={p} className="p-8 bg-white rounded-[2.5rem] text-center border border-slate-100 shadow-sm hover:shadow-md transition-shadow">
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">{p}</p>
                                    <div className={`text-5xl font-black mb-4 ${score >= 80 ? 'text-emerald-600' : score >= 50 ? 'text-indigo-600' : 'text-rose-600'}`}>
                                        {score ? `${score}%` : '--'}
                                    </div>
                                    <div className="flex justify-center gap-1">
                                        {[1,2,3,4,5].map(s => <StarIcon key={s} className={`w-5 h-5 ${s <= Math.round(score/20) ? 'text-amber-400' : 'text-slate-100'}`} filled />)}
                                    </div>
                                    <p className="text-[10px] font-bold text-slate-400 uppercase mt-4">
                                        {score === 0 ? 'Sem Avaliação' : score >= 80 ? 'Excelente' : score >= 50 ? 'Bom' : 'Requer Atenção'}
                                    </p>
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>
        </div>
    );
};

const GuardianPortal: React.FC<GuardianPortalProps> = ({ user, onLogout, onUpdateCurrentUser, students, onStudentsChange, academicYears, schoolSettings, turmas, financialSettings, activeView = 'painel', setActiveView }) => {
    const myStudents = useMemo(() => students.filter(s => s.guardianName === user.name), [students, user.name]);

    // Calculamos os anos disponíveis verificando turmas, notas e registros de assiduidade
    const availableYears = useMemo(() => {
        const years = new Set<number>();
        myStudents.forEach(s => {
            (s.grades || []).forEach(g => years.add(g.academicYear));
            turmas.forEach(t => { if (t.studentIds.includes(s.id)) years.add(t.academicYear); });
            (s.attendance || []).forEach(a => {
                // Regex extrai o ano YYYY do início da string de data
                const match = a.date.match(/^\d{4}/);
                if (match) {
                    const y = parseInt(match[0]);
                    if(!isNaN(y)) years.add(y);
                }
            });
        });

        // Fallback para o ano atual em curso caso não haja dados históricos
        if (years.size === 0) { 
            const active = academicYears.find(ay => ay.status === 'Em Curso'); 
            if(active) years.add(active.year); 
        }

        return Array.from(years).sort((a, b) => b - a);
    }, [myStudents, turmas, academicYears]);

    const [selectedYear, setSelectedYear] = useState<number | null>(null);
    const [statementStudent, setStatementStudent] = useState<Student | null>(null);
    const [isStatementOpen, setIsStatementOpen] = useState(false);

    useEffect(() => { 
        if (availableYears.length > 0 && selectedYear === null) {
            setSelectedYear(availableYears[0]); 
        }
    }, [availableYears, selectedYear]);

    return (
        <div className="flex h-screen bg-[#fcfcfd] font-sans overflow-hidden">
            {setActiveView && <Sidebar user={user} activeView={activeView} setActiveView={setActiveView} />}
            <div className="flex-1 flex flex-col overflow-hidden">
                <Header user={user} onLogout={onLogout} onUpdateProfile={onUpdateCurrentUser} title="Portal do Encarregado" />
                <main className="flex-1 overflow-y-auto p-4 md:p-12">
                    <div className="max-w-6xl mx-auto">
                        <div className="flex flex-col md:flex-row justify-between items-end mb-12 gap-6">
                            <div>
                                <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase">Meus Educandos</h2>
                                <p className="text-slate-500 font-bold mt-2">Acompanhamento Escolar em Tempo Real.</p>
                            </div>
                            {availableYears.length > 0 && (
                                <div className="bg-white p-3 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-3">
                                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Ano Lectivo:</span>
                                    <select 
                                        value={selectedYear || ''} 
                                        onChange={(e) => setSelectedYear(Number(e.target.value))} 
                                        className="border-none rounded-xl text-sm font-black text-indigo-600 focus:ring-0 bg-slate-50 py-2 pr-10"
                                    >
                                        {availableYears.map(year => <option key={year} value={year}>{year}</option>)}
                                    </select>
                                </div>
                            )}
                        </div>

                        {myStudents.length > 0 ? (
                            myStudents.map(student => (
                                <StudentInfoCard 
                                    key={student.id} 
                                    student={student} 
                                    selectedYear={selectedYear} 
                                    academicYears={academicYears}
                                    schoolSettings={schoolSettings}
                                    turmas={turmas}
                                    financialSettings={financialSettings}
                                    onOpenStatement={(s) => { setStatementStudent(s); setIsStatementOpen(true); }}
                                />
                            ))
                        ) : (
                            <div className="bg-white text-center p-24 rounded-[3rem] shadow-xl border border-slate-100">
                                <UsersIcon className="w-20 h-20 text-slate-100 mx-auto mb-6" />
                                <h3 className="text-2xl font-black text-slate-800">Nenhum aluno vinculado</h3>
                                <p className="text-slate-400 mt-2">Por favor, contacte a secretaria para associar os seus educandos à sua conta de acesso.</p>
                            </div>
                        )}
                    </div>
                </main>
            </div>

            <StatementModal 
                isOpen={isStatementOpen} 
                onClose={() => setIsStatementOpen(false)} 
                student={statementStudent} 
                year={selectedYear || 2024} 
                financialSettings={financialSettings}
            />
        </div>
    );
};

export default GuardianPortal;

import React, { useState, useMemo, useEffect } from 'react';
import { User, Student, AcademicYear, SchoolSettings, Turma, FinancialSettings, AppNotification, UserRole, Grade, AttendanceRecord, Subject, PaymentRecord } from '../types';
import { LogoutIcon, GraduationCapIcon, ChevronDownIcon, AcademicCapIcon, CheckCircleIcon, ExclamationTriangleIcon, CloseIcon, CalendarIcon, StarIcon, UsersIcon, CurrencyDollarIcon, ClockIcon, ChartBarIcon, BookOpenIcon, PrinterIcon } from './icons/IconComponents';
import Sidebar from './Sidebar';
import Header from './Header';
import { View } from './Dashboard';

interface GuardianPortalProps {
  user: User;
  onLogout: () => void;
  onUpdateCurrentUser: (data: Partial<User>) => void;
  students: Student[];
  onStudentsChange?: (students: Student[]) => void;
  academicYears: AcademicYear[];
  schoolSettings: SchoolSettings;
  turmas: Turma[];
  financialSettings: FinancialSettings;
  activeView?: View;
  setActiveView?: (view: View) => void;
  onAddNotifications?: (notifications: AppNotification[]) => void;
  users?: User[];
}

const StatementModal: React.FC<{ 
    isOpen: boolean; 
    onClose: () => void; 
    student: Student | null; 
    year: number; 
    financialSettings: FinancialSettings;
}> = ({ isOpen, onClose, student, year, financialSettings }) => {
    if (!isOpen || !student) return null;

    const formatCurrency = (val: number) => {
        return val.toLocaleString('pt-MZ', { style: 'currency', currency: financialSettings.currency || 'MZN' });
    };

    const ledger = useMemo(() => {
        const items: { date: string; desc: string; debit: number; credit: number }[] = [];
        const startMonth = 2;
        const now = new Date();
        const currentMonth = year === now.getFullYear() ? now.getMonth() + 1 : 11;

        let monthlyFee = financialSettings.monthlyFee;
        if (student.desiredClass) {
            const specific = financialSettings.classSpecificFees?.find(c => c.classLevel === student.desiredClass);
            if (specific) monthlyFee = specific.monthlyFee;
        }

        for (let m = startMonth; m <= currentMonth; m++) {
            items.push({ 
                date: `${year}-${m.toString().padStart(2, '0')}-01`, 
                desc: `MENSALIDADE - MÊS ${m}`, 
                debit: monthlyFee, 
                credit: 0 
            });
        }

        (student.payments || []).filter(p => p.academicYear === year).forEach(p => {
            items.push({ 
                date: p.date, 
                desc: `PAGAMENTO: ${p.type} (${p.method || 'Geral'})`, 
                debit: 0, 
                credit: p.amount 
            });
        });

        return items.sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());
    }, [student, year, financialSettings]);

    let runningBalance = 0;

    return (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-3xl overflow-hidden flex flex-col max-h-[90vh]">
                <header className="p-8 border-b bg-slate-50 flex justify-between items-center">
                    <div>
                        <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Extrato de Conta Corrente</h3>
                        <p className="text-sm font-bold text-indigo-500">{student.name} • Ano Letivo {year}</p>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-white rounded-full transition-colors">
                        <CloseIcon className="w-8 h-8 text-slate-400" />
                    </button>
                </header>
                <div className="flex-1 overflow-y-auto p-8">
                    <table className="w-full text-sm">
                        <thead className="text-[10px] font-black uppercase text-slate-400 border-b">
                            <tr>
                                <th className="text-left py-4">Data</th>
                                <th className="text-left py-4">Descrição</th>
                                <th className="text-right py-4">Débito</th>
                                <th className="text-right py-4">Crédito</th>
                                <th className="text-right py-4">Saldo</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {ledger.map((item, i) => {
                                runningBalance += (item.debit - item.credit);
                                return (
                                    <tr key={i} className="hover:bg-slate-50 transition-colors">
                                        <td className="py-4 text-slate-500 whitespace-nowrap">{new Date(item.date).toLocaleDateString()}</td>
                                        <td className="py-4 font-bold text-slate-700">{item.desc}</td>
                                        <td className="py-4 text-right text-rose-600 font-bold">{item.debit > 0 ? formatCurrency(item.debit) : '-'}</td>
                                        <td className="py-4 text-right text-emerald-600 font-bold">{item.credit > 0 ? formatCurrency(item.credit) : '-'}</td>
                                        <td className={`py-4 text-right font-black ${runningBalance > 0 ? 'text-rose-700' : 'text-emerald-700'}`}>
                                            {formatCurrency(runningBalance)}
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
                <footer className="p-8 bg-slate-900 text-white flex justify-between items-center">
                    <div>
                        <p className="text-[10px] font-black uppercase text-indigo-300 mb-1">Saldo Corrente</p>
                        <p className="text-3xl font-black">{formatCurrency(Math.abs(runningBalance))}</p>
                        <p className="text-[10px] uppercase font-bold">{runningBalance > 0 ? 'Dívida a Regularizar' : 'Situação Regularizada'}</p>
                    </div>
                    <button onClick={onClose} className="bg-indigo-600 px-8 py-3 rounded-xl font-black uppercase text-xs tracking-widest hover:bg-indigo-700 transition-all">Fechar Extrato</button>
                </footer>
            </div>
        </div>
    );
};

const StudentInfoCard: React.FC<{ 
    student: Student; 
    selectedYear: number | null; 
    academicYears: AcademicYear[]; 
    schoolSettings: SchoolSettings; 
    turmas: Turma[]; 
    financialSettings: FinancialSettings;
    onOpenStatement: (s: Student) => void;
}> = ({ student, selectedYear, academicYears, schoolSettings, turmas, financialSettings, onOpenStatement }) => {
    const [activeTab, setActiveTab] = useState<'grades' | 'attendance' | 'financial' | 'behavior'>('grades');

    const activeTurma = useMemo(() => {
        if (!selectedYear) return null;
        return turmas.find(t => t.academicYear === selectedYear && t.studentIds.includes(student.id));
    }, [turmas, selectedYear, student.id]);

    const academicYearConfig = useMemo(() => academicYears.find(ay => ay.year === selectedYear), [academicYears, selectedYear]);

    const subjects = useMemo(() => {
        if (!activeTurma || !academicYearConfig) return [];
        return academicYearConfig.subjectsByClass?.find(cs => cs.classLevel === activeTurma.classLevel)?.subjects || [];
    }, [activeTurma, academicYearConfig]);

    const hasExam = useMemo(() => {
        if (!activeTurma || !academicYearConfig) return false;
        return !!academicYearConfig.subjectsByClass?.find(cs => cs.classLevel === activeTurma.classLevel)?.hasExam;
    }, [activeTurma, academicYearConfig]);

    const calcMF = (acs1: number = 0, acs2: number = 0, at: number = 0) => {
        const p1 = schoolSettings.evaluationWeights?.p1 || 40;
        const p2 = schoolSettings.evaluationWeights?.p2 || 60;
        const mediaACS = (acs1 + acs2) / 2;
        const mf = ((mediaACS * p1) + (at * p2)) / (p1 + p2);
        return parseFloat(mf.toFixed(1));
    };

    const academicSummary = useMemo(() => {
        if (!selectedYear || subjects.length === 0) return { globalAvg: 0, passed: false };
        let totalSum = 0; let count = 0;
        subjects.forEach(sub => {
            const t1 = student.grades?.find(g => g.subject === sub.name && g.period === '1º Trimestre' && g.academicYear === selectedYear);
            const t2 = student.grades?.find(g => g.subject === sub.name && g.period === '2º Trimestre' && g.academicYear === selectedYear);
            const t3 = student.grades?.find(g => g.subject === sub.name && g.period === '3º Trimestre' && g.academicYear === selectedYear);

            const mf1 = t1 ? calcMF(t1.acs1, t1.acs2, t1.at) : 0;
            const mf2 = t2 ? calcMF(t2.acs1, t2.acs2, t2.at) : 0;
            const mf3 = t3 ? calcMF(t3.acs1, t3.acs2, t3.at) : 0;

            const valid = [mf1, mf2, mf3].filter(m => m > 0);
            const mediaI = valid.length > 0 ? valid.reduce((a,b) => a+b, 0) / valid.length : 0;

            let final = mediaI;
            if (hasExam) {
                const ex = student.examGrades?.find(e => e.subject === sub.name && e.academicYear === selectedYear);
                if (ex) {
                    const w1 = schoolSettings.examWeights?.internal || 50;
                    const w2 = schoolSettings.examWeights?.exam || 50;
                    final = ((mediaI * w1) + (ex.grade * w2)) / (w1 + w2);
                }
            }
            if (final > 0) { totalSum += final; count++; }
        });
        const avg = count > 0 ? parseFloat((totalSum / count).toFixed(1)) : 0;
        return { globalAvg: avg, passed: avg >= 9.5 };
    }, [student, subjects, selectedYear, hasExam, schoolSettings]);

    const attendanceSummary = useMemo(() => {
        if (!selectedYear) return { total: 0, present: 0, absent: 0, late: 0, history: [] };

        // Função robusta de extração do ano
        const getYearFromStr = (d: string) => {
            if (!d) return 0;
            const match = d.match(/^\d{4}/);
            return match ? parseInt(match[0]) : 0;
        };

        const records = (student.attendance || []).filter(a => {
            const recordYear = getYearFromStr(a.date);
            return recordYear === Number(selectedYear);
        });

        const present = records.filter(r => r.status === 'Presente').length;
        const absent = records.filter(r => r.status === 'Ausente').length;
        const late = records.filter(r => r.status === 'Atrasado').length;

        return { 
            total: records.length, 
            present, 
            absent, 
            late, 
            history: records.sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()) 
        };
    }, [student.attendance, selectedYear]);

    return (
        <div className="bg-white rounded-[2rem] shadow-2xl border border-gray-100 overflow-hidden mb-10 transition-all hover:shadow-indigo-100">
            <div className="p-8 bg-slate-900 text-white relative">
                <div className="flex flex-col md:flex-row items-center gap-6 relative z-10">
                    <img className="h-24 w-24 rounded-3xl object-cover border-4 border-indigo-500 shadow-xl" src={student.profilePictureUrl || 'https://i.pravatar.cc/150'} alt="" />
                    <div className="flex-1 text-center md:text-left">
                        <h3 className="text-3xl font-black uppercase tracking-tight">{student.name}</h3>
                        <p className="text-indigo-400 text-xs font-black uppercase tracking-widest mt-2">
                             {activeTurma ? `${activeTurma.classLevel} • ${activeTurma.name}` : student.desiredClass}
                        </p>
                    </div>

                    <div className="flex gap-4">
                        <div className="bg-indigo-600 p-4 rounded-3xl text-center min-w-[140px] border border-indigo-400/30 shadow-xl">
                            <p className="text-[10px] font-black uppercase text-indigo-100 mb-1 tracking-widest">Média Anual</p>
                            <p className="text-4xl font-black">{academicSummary.globalAvg || '--'}</p>
                            <p className={`text-[10px] font-bold mt-1 ${academicSummary.passed ? 'text-emerald-300' : 'text-rose-300'}`}>
                                {academicSummary.passed ? 'APROVADO' : 'PENDENTE'}
                            </p>
                        </div>

                        <div className={`${attendanceSummary.absent > 0 ? 'bg-rose-600' : 'bg-slate-800'} p-4 rounded-3xl text-center min-w-[140px] border border-white/10 shadow-xl transition-colors`}>
                            <p className="text-[10px] font-black uppercase text-white/60 mb-1 tracking-widest">Faltas no Ano</p>
                            <p className="text-4xl font-black text-white">{attendanceSummary.absent}</p>
                            <p className="text-[10px] font-bold mt-1 text-white/40">ASSIDUIDADE</p>
                        </div>
                    </div>
                </div>
            </div>

            <div className="flex bg-slate-50 border-b overflow-x-auto no-scrollbar p-2 gap-2">
                {[
                    { id: 'grades', label: 'Pauta de Notas', icon: <ChartBarIcon className="w-4 h-4" /> },
                    { id: 'attendance', label: 'Assiduidade', icon: <CalendarIcon className="w-4 h-4" /> },
                    { id: 'financial', label: 'Financeiro', icon: <CurrencyDollarIcon className="w-4 h-4" /> },
                    { id: 'behavior', label: 'Conduta', icon: <StarIcon className="w-4 h-4" /> }
                ].map(tab => (
                    <button 
                        key={tab.id} 
                        onClick={() => setActiveTab(tab.id as any)} 
                        className={`flex items-center px-6 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all whitespace-nowrap ${
                            activeTab === tab.id 
                            ? 'bg-white text-indigo-600 shadow-md border border-indigo-100' 
                            : 'text-slate-400 hover:text-slate-600'
                        }`}
                    >
                        <span className="mr-2">{tab.icon}</span>{tab.label}
                    </button>
                ))}
            </div>

            <div className="p-4 md:p-10">
                {activeTab === 'grades' && (
                    <div className="overflow-x-auto -mx-4 md:mx-0 rounded-2xl border border-slate-100">
                        <table className="min-w-full text-[10px] border-collapse">
                            <thead>
                                <tr className="bg-slate-900 text-white font-black uppercase tracking-tighter">
                                    <th className="p-4 text-left border-r border-white/10 sticky left-0 bg-slate-900 z-10">Disciplina</th>
                                    <th colSpan={5} className="p-2 text-center border-r border-white/10 bg-indigo-900/50">1º Trimestre</th>
                                    <th colSpan={5} className="p-2 text-center border-r border-white/10 bg-slate-800">2º Trimestre</th>
                                    <th colSpan={5} className="p-2 text-center border-r border-white/10 bg-indigo-900/50">3º Trimestre</th>
                                    {hasExam && <th className="p-4 text-center border-r border-white/10 bg-amber-600">Exame</th>}
                                    <th className="p-4 text-right bg-indigo-600">Média Anual</th>
                                </tr>
                                <tr className="bg-slate-100 text-slate-500 font-bold uppercase text-[8px] border-b">
                                    <th className="p-2 border-r sticky left-0 bg-slate-100 z-10"></th>
                                    {[1,2,3].map(t => (
                                        <React.Fragment key={t}>
                                            <th className="p-1 border-r text-center">ACS1</th>
                                            <th className="p-1 border-r text-center">ACS2</th>
                                            <th className="p-1 border-r text-center bg-gray-50">MAC</th>
                                            <th className="p-1 border-r text-center">AT</th>
                                            <th className="p-1 border-r text-center bg-indigo-50 font-black">MF</th>
                                        </React.Fragment>
                                    ))}
                                    {hasExam && <th className="p-1 border-r text-center bg-amber-50 font-black">Nota</th>}
                                    <th className="p-1 text-right bg-indigo-100 font-black px-4">FINAL</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100 text-[11px]">
                                {subjects.length > 0 ? subjects.map(sub => {
                                    const g1 = student.grades?.find(g => g.subject === sub.name && g.period === '1º Trimestre' && g.academicYear === selectedYear);
                                    const g2 = student.grades?.find(g => g.subject === sub.name && g.period === '2º Trimestre' && g.academicYear === selectedYear);
                                    const g3 = student.grades?.find(g => g.subject === sub.name && g.period === '3º Trimestre' && g.academicYear === selectedYear);
                                    const ex = student.examGrades?.find(e => e.subject === sub.name && e.academicYear === selectedYear);

                                    const getRowData = (g: Grade | undefined) => {
                                        const acs1 = g?.acs1 || 0;
                                        const acs2 = g?.acs2 || 0;
                                        const at = g?.at || 0;
                                        const mac = parseFloat(((acs1 + acs2) / 2).toFixed(1));
                                        const mf = calcMF(acs1, acs2, at);
                                        return { acs1, acs2, mac, at, mf };
                                    };

                                    const r1 = getRowData(g1);
                                    const r2 = getRowData(g2);
                                    const r3 = getRowData(g3);

                                    const valMfs = [r1.mf, r2.mf, r3.mf].filter(m => m > 0);
                                    const medI = valMfs.length > 0 ? valMfs.reduce((a,b)=>a+b,0)/valMfs.length : 0;
                                    let final = medI;
                                    if (hasExam && ex) {
                                        const w1 = schoolSettings.examWeights?.internal || 50;
                                        const w2 = schoolSettings.examWeights?.exam || 50;
                                        final = ((medI * w1) + (ex.grade * w2)) / (w1 + w2);
                                    }

                                    const renderVal = (v: number) => v > 0 ? v : '-';
                                    const renderMF = (v: number) => (
                                        <span className={`font-black ${v >= 9.5 ? 'text-indigo-600' : v > 0 ? 'text-rose-500' : 'text-slate-300'}`}>
                                            {v > 0 ? v.toFixed(1) : '-'}
                                        </span>
                                    );

                                    return (
                                        <tr key={sub.id} className="hover:bg-indigo-50/30 transition-colors">
                                            <td className="p-3 font-bold text-slate-700 border-r sticky left-0 bg-white z-10">{sub.name}</td>
                                            <td className="p-1 text-center border-r">{renderVal(r1.acs1)}</td>
                                            <td className="p-1 text-center border-r">{renderVal(r1.acs2)}</td>
                                            <td className="p-1 text-center border-r bg-gray-50 text-slate-400">{renderVal(r1.mac)}</td>
                                            <td className="p-1 text-center border-r font-bold">{renderVal(r1.at)}</td>
                                            <td className="p-1 text-center bg-indigo-50/50 border-r">{renderMF(r1.mf)}</td>
