                                    <th className="p-1 text-right bg-indigo-100 font-black px-4">FINAL</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100 text-[11px]">
                                {subjects.length > 0 ? subjects.map(sub => {
                                    const g1 = student.grades?.find(g => g.subject === sub.name && g.period === '1º Trimestre' && g.academicYear === selectedYear);
                                    const g2 = student.grades?.find(g => g.subject === sub.name && g.period === '2º Trimestre' && g.academicYear === selectedYear);
                                    const g3 = student.grades?.find(g => g.subject === sub.name && g.period === '3º Trimestre' && g.academicYear === selectedYear);
                                    const ex = student.examGrades?.find(e => e.subject === sub.name && e.academicYear === selectedYear);

                                    const getRowData = (g: Grade | undefined) => {
                                        const acs1 = g?.acs1 || 0;
