interface GuardianPortalProps {
  user: User;
  onLogout: () => void;
  onUpdateCurrentUser: (data: Partial<User>) => void;
  students: Student[];
  onStudentsChange?: (students: Student[]) => void;
  academicYears: AcademicYear[];
  schoolSettings: SchoolSettings;
