        if (currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SECRETARIA) {
             allTabs.splice(4, 0, { id: 'staff', label: 'Pessoal', icon: <UserAddIcon className="w-4 h-4"/> });
