                            </div>
                            <div className="bg-amber-50 p-4 rounded-2xl border border-amber-100 flex items-center justify-between shadow-sm">
                                <div>
                                    <p className="text-[8px] font-black text-amber-600 uppercase mb-0.5 tracking-widest">Atrasos</p>
