        <svg viewBox="0 0 100 100" className={className} fill="currentColor">
            <circle cx="50" cy="50" r="45" fill="#E11A22"/>
            <path d="M30 35 L70 35 L70 45 L55 45 L55 65 L45 65 L45 45 L30 45 Z" fill="white"/>
