        <svg viewBox="0 0 100 100" className={className} fill="currentColor">
            <rect width="90" height="90" x="5" y="5" rx="20" fill="#FF8C00"/>
            <text x="50" y="65" fontSize="40" fontWeight="black" fill="white" textAnchor="middle">e-M</text>
        </svg>
    );
    return (
        <svg viewBox="0 0 100 100" className={className} fill="currentColor">
            <circle cx="50" cy="50" r="45" fill="#FFD700"/>
            <text x="50" y="65" fontSize="40" fontWeight="black" fill="black" textAnchor="middle">mK</text>
