import React, { useState, useMemo, useEffect } from 'react';
import { Student, FinancialSettings, AcademicYear, PaymentRecord, SchoolSettings, PaymentItem, PaymentMethod, User, AppNotification, UserRole, PaymentType } from '../types';
import { CheckCircleIcon, ExclamationTriangleIcon, MobilePaymentIcon } from './icons/IconComponents';
import { printReceipt } from './ReceiptUtils';

interface EnrollmentPaymentProps {
    students: Student[];
    onStudentsChange: (students: Student[]) => void;
    financialSettings: FinancialSettings;
    academicYears: AcademicYear[];
    currentUser: User;
    users: User[];
    onAddNotifications: (notifications: AppNotification[]) => void;
}

type PaymentTypeOption = 'new' | 'renewal';

const months = [
    { val: 1, name: 'Janeiro' }, { val: 2, name: 'Fevereiro' }, { val: 3, name: 'Março' },
    { val: 4, name: 'Abril' }, { val: 5, name: 'Maio' }, { val: 6, name: 'Junho' },
    { val: 7, name: 'Julho' }, { val: 8, name: 'Agosto' }, { val: 9, name: 'Setembro' },
    { val: 10, name: 'Outubro' }, { val: 11, name: 'Novembro' }, { val: 12, name: 'Dezembro' }
];

const paymentMethods: PaymentMethod[] = ['Numerário', 'Transferência Bancária', 'MPesa', 'e-Mola', 'mKesh', 'POS'];

const EnrollmentPayment: React.FC<EnrollmentPaymentProps> = ({ students, onStudentsChange, financialSettings, academicYears, currentUser, users, onAddNotifications }) => {
    const [selectedStudentId, setSelectedStudentId] = useState('');
    const [selectedYear, setSelectedYear] = useState<number | ''>('');
    const [paymentType, setPaymentType] = useState<PaymentTypeOption>('new');
    const [selectedMethod, setSelectedMethod] = useState<PaymentMethod>('Numerário');
    const [transactionId, setTransactionId] = useState(''); // Novo: ID da transação mobile
    const [selectedUniforms, setSelectedUniforms] = useState<Record<string, boolean>>({});
    const [selectedBooks, setSelectedBooks] = useState<Record<string, boolean>>({});

    const [payFirstMonth, setPayFirstMonth] = useState(true);
    const [isSuccess, setIsSuccess] = useState(false);
    const [lastPayment, setLastPayment] = useState<PaymentRecord | null>(null);

    useEffect(() => {
        const activeYear = academicYears.find(y => y.status === 'Em Curso' || y.status === 'Planeado');
        if (activeYear) setSelectedYear(activeYear.year);
    }, [academicYears]);

    const eligibleStudents = useMemo(() => {
        if (!selectedYear) return [];
        return students.filter(student => {
            const hasPaid = student.payments?.some(p => 
                p.academicYear === Number(selectedYear) && 
                (p.type === 'Matrícula' || p.type === 'Renovação')
            );
            return !hasPaid;
        });
    }, [students, selectedYear]);

    useEffect(() => {
        if (selectedStudentId && !eligibleStudents.find(s => s.id === selectedStudentId)) {
            setSelectedStudentId('');
            setSelectedUniforms({});
            setSelectedBooks({});
        }
    }, [eligibleStudents, selectedStudentId]);

    const selectedStudent = useMemo(() => students.find(s => s.id === selectedStudentId), [students, selectedStudentId]);

    const isReturningStudent = useMemo(() => {
        if (!selectedStudent || !selectedYear) return false;
        return selectedStudent.payments?.some(p => 
            p.academicYear < Number(selectedYear) && 
            (p.type === 'Matrícula' || p.type === 'Renovação')
        ) || false;
    }, [selectedStudent, selectedYear]);

    const pastDebts = useMemo(() => {
        if (!selectedStudent || !selectedYear || !isReturningStudent) return null;
        const profile = selectedStudent.financialProfile || { status: 'Normal' };
        if (profile.status === 'Isento Total') return null;
        const debts: number[] = [];
        const matriculationYear = new Date(selectedStudent.matriculationDate).getFullYear();
        academicYears.forEach(ay => {
            if (ay.year < Number(selectedYear) && ay.year >= matriculationYear) {
                let yearObligation = 0;
                let renewalFee = financialSettings.renewalFee;
                let monthlyFee = financialSettings.monthlyFee;
                if (profile.status === 'Desconto Parcial') {
                    if (profile.affectedTypes?.includes('Renovação')) renewalFee *= (1 - (profile.discountPercentage || 0)/100);
                    if (profile.affectedTypes?.includes('Mensalidade')) monthlyFee *= (1 - (profile.discountPercentage || 0)/100);
                }
                yearObligation += renewalFee;
                let monthsInYear = (ay.endMonth || 11) - (ay.startMonth || 2) + 1;
                if (selectedStudent.status === 'Suspenso' && selectedStudent.suspensionDate) {
                    const suspDate = new Date(selectedStudent.suspensionDate);
                    if (suspDate.getFullYear() === ay.year) {
                        const activeMonthsCount = Math.max(0, (suspDate.getMonth() + 1) - (ay.startMonth || 2) + 1);
                        monthsInYear = Math.min(monthsInYear, activeMonthsCount);
                    } else if (suspDate.getFullYear() < ay.year) {
                        monthsInYear = 0;
                        yearObligation = 0;
                    }
                }
                yearObligation += (monthlyFee * monthsInYear);
                const totalPaidInYear = selectedStudent.payments
                    ?.filter(p => p.academicYear === ay.year && (p.type === 'Matrícula' || p.type === 'Renovação' || p.type === 'Mensalidade'))
                    .reduce((acc, curr) => acc + curr.amount, 0) || 0;
                if (yearObligation > 0 && (yearObligation - totalPaidInYear) > 500) {
                    debts.push(ay.year);
                }
            }
        });
        return debts.length > 0 ? debts : null;
    }, [selectedStudent, selectedYear, isReturningStudent, academicYears, financialSettings]);

    useEffect(() => {
        if (selectedStudent) {
            setPaymentType(isReturningStudent ? 'renewal' : 'new');
        }
    }, [selectedStudent, isReturningStudent]);

    const relevantBooks = useMemo(() => {
        if (!selectedStudent) return [];
        return financialSettings.books.filter(b => b.classLevel === selectedStudent.desiredClass);
    }, [selectedStudent, financialSettings]);

    const calculateDiscountedFee = (baseValue: number, type: PaymentType): number => {
        if (!selectedStudent) return baseValue;
        const profile = selectedStudent.financialProfile || { status: 'Normal' };
        if (profile.status === 'Isento Total') return 0;
        if (profile.status === 'Desconto Parcial' && profile.affectedTypes?.includes(type)) {
            return baseValue * (1 - (profile.discountPercentage || 0) / 100);
        }
        return baseValue;
    };

    const baseFee = useMemo(() => {
        const specificFee = selectedStudent?.desiredClass 
            ? financialSettings.classSpecificFees?.find(c => c.classLevel === selectedStudent.desiredClass)
            : undefined;
        let rawFee = paymentType === 'renewal' 
            ? (specificFee ? specificFee.renewalFee : financialSettings.renewalFee)
            : (specificFee ? specificFee.enrollmentFee : financialSettings.enrollmentFee);
        return calculateDiscountedFee(rawFee, paymentType === 'new' ? 'Matrícula' : 'Renovação');
    }, [paymentType, selectedStudent, financialSettings]);

    const currentMonthlyFee = useMemo(() => {
        const specificFee = selectedStudent?.desiredClass 
            ? financialSettings.classSpecificFees?.find(c => c.classLevel === selectedStudent.desiredClass)
            : undefined;
        const rawFee = specificFee ? specificFee.monthlyFee : financialSettings.monthlyFee;
        return calculateDiscountedFee(rawFee, 'Mensalidade');
    }, [selectedStudent, financialSettings]);

    const handleStudentChange = (id: string) => {
        setSelectedStudentId(id);
        setSelectedUniforms({});
        setSelectedBooks({});
        setSelectedMethod('Numerário');
        setTransactionId('');
        setPayFirstMonth(true);
        setIsSuccess(false);
        setLastPayment(null);
    };

    const toggleUniform = (id: string) => setSelectedUniforms(prev => ({ ...prev, [id]: !prev[id] }));
    const toggleBook = (id: string) => setSelectedBooks(prev => ({ ...prev, [id]: !prev[id] }));

    const calculateTotal = () => {
        let total = baseFee + calculateDiscountedFee(financialSettings.annualExamFee, 'Taxa de Exames');
        if (payFirstMonth) total += currentMonthlyFee;
        Object.keys(selectedUniforms).forEach(id => {
            if (selectedUniforms[id]) {
                const item = financialSettings.uniforms.find(u => u.id === id);
                if (item) total += calculateDiscountedFee(item.price, 'Uniforme');
            }
        });
        Object.keys(selectedBooks).forEach(id => {
            if (selectedBooks[id]) {
                const item = financialSettings.books.find(b => b.id === id);
                if (item) total += calculateDiscountedFee(item.price, 'Material');
            }
        });
        return total;
    };

    const formatCurrency = (val: number) => {
        return val.toLocaleString('pt-MZ', { style: 'currency', currency: financialSettings.currency || 'MZN' });
    };

    const handleProcessPayment = () => {
        if (!selectedStudent || !selectedYear) return;
        if (pastDebts) {
            alert('Não é possível prosseguir. O aluno possui dívidas de anos anteriores.');
            return;
        }

        const paymentTypeLabel = paymentType === 'new' ? 'Matrícula' : 'Renovação';
        const items: PaymentItem[] = [];
        let totalPaid = 0;

        items.push({ item: `${paymentTypeLabel} (${selectedStudent.desiredClass})`, value: baseFee });
        totalPaid += baseFee;

        const examFee = calculateDiscountedFee(financialSettings.annualExamFee, 'Taxa de Exames');
        items.push({ item: 'Taxas de Testes/Exames', value: examFee });
        totalPaid += examFee;

        let firstMonthlyFeeReference: number | undefined = undefined;
        if (payFirstMonth) { 
            const acYear = academicYears.find(y => y.year === Number(selectedYear));
            const startMonth = acYear ? (acYear.startMonth || 2) : 2;
            const now = new Date();
            const currentMonth = now.getMonth() + 1;
            firstMonthlyFeeReference = Number(selectedYear) > now.getFullYear() ? startMonth : Math.max(startMonth, currentMonth);
            const monthName = months.find(m => m.val === firstMonthlyFeeReference)?.name || 'Mês Referência';
            items.push({ item: `1ª Mensalidade (${monthName})`, value: currentMonthlyFee });
            totalPaid += currentMonthlyFee;
        }

        Object.keys(selectedUniforms).forEach(id => {
            if (selectedUniforms[id]) {
                const item = financialSettings.uniforms.find(u => u.id === id);
                if (item) {
                    const p = calculateDiscountedFee(item.price, 'Uniforme');
                    items.push({ item: item.name, value: p });
                    totalPaid += p;
                }
            }
        });

        Object.keys(selectedBooks).forEach(id => {
            if (selectedBooks[id]) {
                const item = financialSettings.books.find(b => b.id === id);
                if (item) {
                    const p = calculateDiscountedFee(item.price, 'Material');
                    items.push({ item: item.title, value: p });
                    totalPaid += p;
                }
            }
        });

        const newPayment: PaymentRecord = {
            id: `pay_${Date.now()}`,
            date: new Date().toISOString().split('T')[0],
            amount: totalPaid,
            type: paymentTypeLabel,
            method: selectedMethod,
            academicYear: Number(selectedYear),
            description: `${paymentTypeLabel} ${selectedYear}${transactionId ? ' (Ref: ' + transactionId + ')' : ''}`,
            items: items,
            operatorName: currentUser.name
        };
        if (firstMonthlyFeeReference) newPayment.referenceMonth = firstMonthlyFeeReference;

        const updatedStudents: Student[] = students.map(s => {
            if (s.id === selectedStudentId) {
                return {
                    ...s,
                    status: 'Ativo',
                    suspensionDate: undefined,
                    payments: [...(s.payments || []), newPayment],
                    matriculationDate: paymentType === 'new' ? new Date().toISOString().split('T')[0] : s.matriculationDate 
                } as Student;
            }
            return s;
        });

        onStudentsChange(updatedStudents);
        setLastPayment(newPayment);
        onAddNotifications(users.filter(u => u.role === UserRole.ADMIN).map(admin => ({
            id: `notif_pay_${Date.now()}_${admin.id}`,
            userId: admin.id, type: 'admin_alert', title: 'Recebimento Confirmado',
            message: `Pagamento de ${formatCurrency(totalPaid)} de ${selectedStudent.name} (${paymentTypeLabel}).`,
            read: false, timestamp: new Date().toISOString()
        })));
        setIsSuccess(true);
    };

    const handlePrintReceipt = () => {
        if (lastPayment && selectedStudent) {
            const operatorToPrint = lastPayment.operatorName || currentUser.name;
            printReceipt(lastPayment, selectedStudent, schoolSettings, financialSettings.currency, operatorToPrint);
        }
    };

    const isMobileMethod = ['MPesa', 'e-Mola', 'mKesh'].includes(selectedMethod);

    return (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-6">
                <div className="bg-white p-6 rounded-2xl shadow-lg">
                    <h3 className="text-lg font-bold text-gray-800 mb-4">1. Selecionar Aluno e Ano</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                         <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Ano Letivo Referente</label>
                            <select value={selectedYear} onChange={e => setSelectedYear(Number(e.target.value))} className="w-full p-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500">
                                <option value="">Selecione...</option>
                                {academicYears.map(y => <option key={y.id} value={y.year}>{y.year} ({y.status})</option>)}
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Nome do Aluno</label>
                            <select value={selectedStudentId} onChange={e => handleStudentChange(e.target.value)} className="w-full p-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500" disabled={!selectedYear}>
                                <option value="">{selectedYear ? 'Selecione...' : 'Selecione o ano primeiro'}</option>
                                {eligibleStudents.map(s => <option key={s.id} value={s.id}>{s.name} (ID: {s.id})</option>)}
                            </select>
                        </div>
                    </div>
                    {selectedStudent && (
                        <div className="bg-indigo-50 p-3 rounded-lg border border-indigo-100 text-sm text-indigo-800 flex justify-between items-center">
                            <span><strong>Classe Pretendida:</strong> {selectedStudent.desiredClass}</span>
                            {selectedStudent.financialProfile && selectedStudent.financialProfile.status !== 'Normal' && (
                                <span className="bg-white px-2 py-1 rounded text-xs font-bold text-green-600 border border-green-200">{selectedStudent.financialProfile.status}</span>
                            )}
                        </div>
                    )}
                </div>

                {selectedStudent && selectedYear && (
                    <>
                        {pastDebts && (
                            <div className="bg-red-50 border-l-4 border-red-500 p-4 rounded-md shadow-md animate-pulse">
                                <div className="flex">
                                    <div className="flex-shrink-0"><ExclamationTriangleIcon className="h-5 w-5 text-red-600" /></div>
                                    <div className="ml-3">
                                        <h3 className="text-sm font-bold text-red-800">Bloqueio Financeiro</h3>
                                        <div className="mt-2 text-sm text-red-700">
                                            <p>Dívidas pendentes: <strong>{pastDebts.join(', ')}</strong>. Regularize para prosseguir.</p>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}

                        <div className={`bg-white p-6 rounded-2xl shadow-lg transition-opacity ${pastDebts ? 'opacity-50 pointer-events-none' : 'opacity-100'}`}>
                            <h3 className="text-lg font-bold text-gray-800 mb-4">2. Método de Pagamento</h3>
                            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-6 gap-3">
                                {paymentMethods.map(method => {
                                    const isMpesa = method === 'MPesa';
                                    const isEmola = method === 'e-Mola';
                                    const isMkesh = method === 'mKesh';
                                    const isActive = selectedMethod === method;

                                    return (
                                        <button
                                            key={method}
                                            onClick={() => setSelectedMethod(method)}
                                            className={`flex flex-col items-center justify-center p-3 rounded-xl border-2 transition-all group ${
                                                isActive 
                                                ? (isMpesa ? 'border-red-500 bg-red-50' : isEmola ? 'border-orange-500 bg-orange-50' : isMkesh ? 'border-yellow-500 bg-yellow-50' : 'border-indigo-600 bg-indigo-50') 
                                                : 'border-gray-100 hover:border-gray-200 bg-white'
                                            }`}
                                        >
                                            {isMpesa || isEmola || isMkesh ? (
                                                <MobilePaymentIcon type={isMpesa ? 'mpesa' : isEmola ? 'emola' : 'mkesh'} className="w-8 h-8 mb-2" />
                                            ) : (
                                                <div className={`w-8 h-8 rounded-full flex items-center justify-center mb-2 ${isActive ? 'bg-indigo-600 text-white' : 'bg-gray-100 text-gray-400'}`}>
                                                    {method === 'Numerário' ? '$' : method === 'POS' ? '💳' : '🏦'}
                                                </div>
                                            )}
                                            <span className={`text-[10px] font-black uppercase text-center ${isActive ? 'text-gray-900' : 'text-gray-500'}`}>{method}</span>
                                        </button>
                                    );
                                })}
                            </div>

                            {/* Mobile Payment Instructions & Code Field */}
                            {isMobileMethod && financialSettings.enableMobilePayments && (
                                <div className="mt-6 p-4 rounded-xl border-2 border-dashed border-indigo-200 bg-indigo-50/30 animate-fade-in">
                                    <div className="flex flex-col md:flex-row gap-6">
                                        <div className="flex-1">
                                            <h4 className="text-xs font-black text-indigo-900 uppercase mb-3 flex items-center">
                                                <CheckCircleIcon className="w-4 h-4 mr-2" />
                                                Instruções para o Cliente
                                            </h4>
                                            <div className="space-y-2 text-sm text-gray-700">
                                                {selectedMethod === 'MPesa' && (
                                                    <p>Pagar via <strong>M-Pesa</strong> no código: <span className="bg-red-600 text-white px-2 py-0.5 rounded font-bold">{financialSettings.mobilePaymentConfig?.mpesaCode || '---'}</span></p>
                                                )}
                                                {selectedMethod === 'e-Mola' && (
                                                    <p>Pagar via <strong>e-Mola</strong> para o número: <span className="bg-orange-500 text-white px-2 py-0.5 rounded font-bold">{financialSettings.mobilePaymentConfig?.emolaCode || '---'}</span></p>
                                                )}
                                                {selectedMethod === 'mKesh' && (
                                                    <p>Pagar via <strong>mKesh</strong> no código: <span className="bg-yellow-400 text-black px-2 py-0.5 rounded font-bold">{financialSettings.mobilePaymentConfig?.mkeshCode || '---'}</span></p>
                                                )}
                                                <p className="text-[11px] text-gray-500 italic">Solicite ao cliente o ID/Referência da transação para confirmar.</p>
                                            </div>
                                        </div>
                                        <div className="flex-1">
                                            <label className="block text-xs font-black text-gray-500 uppercase mb-1">ID da Transação / Referência*</label>
                                            <input 
                                                type="text" 
                                                value={transactionId}
                                                onChange={e => setTransactionId(e.target.value)}
                                                placeholder="Ex: 8G457788A"
                                                className="w-full p-3 border-2 border-indigo-200 rounded-xl focus:ring-4 focus:ring-indigo-500/10 font-mono font-bold uppercase"
                                            />
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>

                         <div className={`bg-white p-6 rounded-2xl shadow-lg transition-opacity ${pastDebts ? 'opacity-50 pointer-events-none' : 'opacity-100'}`}>
                            <h3 className="text-lg font-bold text-gray-800 mb-4">3. Outros Itens (Opcional)</h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-3 mb-4">
                                {financialSettings.uniforms.map(item => (
                                    <label key={item.id} className={`flex justify-between items-center p-3 rounded-lg border cursor-pointer transition-colors ${selectedUniforms[item.id] ? 'bg-blue-50 border-blue-300' : 'hover:bg-gray-50 border-gray-200'}`}>
                                        <div className="flex items-center">
                                            <input type="checkbox" checked={!!selectedUniforms[item.id]} onChange={() => toggleUniform(item.id)} className="h-4 w-4 text-indigo-600 rounded focus:ring-indigo-500" />
                                            <span className="ml-2 text-sm font-medium text-gray-700">{item.name}</span>
                                        </div>
                                        <span className="text-sm font-bold text-gray-600">{formatCurrency(calculateDiscountedFee(item.price, 'Uniforme'))}</span>
                                    </label>
                                ))}
                            </div>
                            {relevantBooks.length > 0 && (
                                <div className="grid grid-cols-1 gap-3">
                                    {relevantBooks.map(item => (
                                        <label key={item.id} className={`flex justify-between items-center p-3 rounded-lg border cursor-pointer transition-colors ${selectedBooks[item.id] ? 'bg-blue-50 border-blue-300' : 'hover:bg-gray-50 border-gray-200'}`}>
                                            <div className="flex items-center">
                                                <input type="checkbox" checked={!!selectedBooks[item.id]} onChange={() => toggleBook(item.id)} className="h-4 w-4 text-indigo-600 rounded focus:ring-indigo-500" />
                                                <span className="ml-2 text-sm font-medium text-gray-700">{item.title}</span>
                                            </div>
                                            <span className="text-sm font-bold text-gray-600">{formatCurrency(calculateDiscountedFee(item.price, 'Material'))}</span>
                                        </label>
                                    ))}
                                </div>
                            )}
                        </div>
                    </>
                )}
            </div>

            <div className="lg:col-span-1">
                <div className="bg-white p-6 rounded-2xl shadow-lg sticky top-6">
                    <h3 className="text-xl font-bold text-gray-800 mb-6 pb-2 border-b">Resumo do Pagamento</h3>
                    {selectedStudent && selectedYear ? (
                        <div className={`space-y-4 ${pastDebts ? 'opacity-50 pointer-events-none' : 'opacity-100'}`}>
                            <div className="flex justify-between text-sm">
                                <span className="text-gray-600">{paymentType === 'new' ? 'Matrícula' : 'Inscrição'} ({selectedYear})</span>
                                <span className="font-medium">{formatCurrency(baseFee)}</span>
                            </div>
                            <div className="flex justify-between text-sm">
                                <span className="text-gray-600">Testes Anuais</span>
                                <span className="font-medium">{formatCurrency(calculateDiscountedFee(financialSettings.annualExamFee, 'Taxa de Exames'))}</span>
                            </div>
                            <div className="flex justify-between text-sm items-center py-2 border-t border-b border-gray-100 bg-gray-50 -mx-6 px-6">
                                <label className="flex items-center cursor-pointer text-gray-600 select-none">
                                    <input type="checkbox" checked={payFirstMonth} onChange={(e) => setPayFirstMonth(e.target.checked)} className="mr-2 rounded text-indigo-600 focus:ring-indigo-500 h-4 w-4" />
                                    Incluir 1ª Mensalidade
                                </label>
                                <span className={`font-medium ${payFirstMonth ? 'text-gray-800' : 'text-gray-400 line-through'}`}>{formatCurrency(currentMonthlyFee)}</span>
                            </div>
                            <div className="border-t border-gray-300 pt-4 mt-4">
                                <div className="flex justify-between items-center">
                                    <span className="text-lg font-bold text-gray-800">Total a Pagar</span>
                                    <span className="text-2xl font-bold text-green-600">{formatCurrency(calculateTotal())}</span>
                                </div>
                            </div>
                            <button 
                                onClick={handleProcessPayment}
                                disabled={!!pastDebts || (isMobileMethod && !transactionId)}
                                className={`w-full text-white font-black py-4 px-4 rounded-xl shadow-xl transform transition mt-4 uppercase tracking-widest ${
                                    (pastDebts || (isMobileMethod && !transactionId)) 
                                    ? 'bg-gray-400 cursor-not-allowed' 
                                    : 'bg-indigo-600 hover:bg-indigo-700 hover:scale-[1.02]'
                                }`}
                            >
                                {pastDebts ? 'Bloqueado' : isMobileMethod && !transactionId ? 'Insira Referência' : 'Confirmar e Receber'}
                            </button>
                        </div>
                    ) : (
                        <p className="text-center text-gray-500 italic">Selecione um aluno e o ano letivo para ver o resumo.</p>
                    )}
                </div>
            </div>
        </div>
    );
};

export default EnrollmentPayment;

import React, { useState, useMemo, useEffect } from 'react';
import { Student, FinancialSettings, AcademicYear, PaymentRecord, SchoolSettings, User, UserRole, PaymentItem, PaymentMethod, AppNotification, PaymentType } from '../types';
import { CheckCircleIcon, CloseIcon, CalendarIcon, TrashIcon, ClockIcon, ExclamationTriangleIcon, EditIcon, PrinterIcon, MobilePaymentIcon } from './icons/IconComponents';
import { printReceipt, printStudentStatement } from './ReceiptUtils';
import EditPaymentModal from './EditPaymentModal';

interface FinancialRecordsProps {
    students: Student[];
    onStudentsChange: (students: Student[]) => void;
    financialSettings: FinancialSettings;
    academicYears: AcademicYear[];
    currentUser: User;
    users: User[];
    onAddNotifications: (notifications: AppNotification[]) => void;
    schoolSettings: SchoolSettings;
}

const months = [
    { val: 1, name: 'Janeiro' }, { val: 2, name: 'Fevereiro' }, { val: 3, name: 'Março' },
    { val: 4, name: 'Abril' }, { val: 5, name: 'Maio' }, { val: 6, name: 'Junho' },
    { val: 7, name: 'Julho' }, { val: 8, name: 'Agosto' }, { val: 9, name: 'Setembro' },
    { val: 10, name: 'Outubro' }, { val: 11, name: 'Novembro' }, { val: 12, name: 'Dezembro' }
];

const paymentMethods: PaymentMethod[] = ['Numerário', 'Transferência Bancária', 'MPesa', 'e-Mola', 'mKesh', 'POS'];

const FinancialRecords: React.FC<FinancialRecordsProps> = ({ students, onStudentsChange, financialSettings, academicYears, currentUser, users, onAddNotifications, schoolSettings }) => {
    const [activeYear, setActiveYear] = useState<number | ''>('');
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);

    const [isTransactionModalOpen, setIsTransactionModalOpen] = useState(false);
    const [transactionType, setTransactionType] = useState<'Mensalidade' | 'Uniforme' | 'Material' | 'Multa/Danos'>('Mensalidade');
    const [selectedMethod, setSelectedMethod] = useState<PaymentMethod>('Numerário');
    const [transactionId, setTransactionId] = useState('');
    const [selectedMonth, setSelectedMonth] = useState<number>(new Date().getMonth() + 1);
    const [selectedUniforms, setSelectedUniforms] = useState<Record<string, boolean>>({});
    const [selectedBooks, setSelectedBooks] = useState<Record<string, boolean>>({});
    const [selectedCharges, setSelectedCharges] = useState<Record<string, boolean>>({});

    const [isSuccess, setIsSuccess] = useState(false);
    const [lastPaymentId, setLastPaymentId] = useState<string | null>(null);

    const [isEditModalOpen, setIsEditModalOpen] = useState(false);
    const [editingPayment, setEditingPayment] = useState<PaymentRecord | null>(null);

    useEffect(() => {
        const current = academicYears.find(y => y.status === 'Em Curso' || y.status === 'Planeado');
        if (current) setActiveYear(current.year);
    }, [academicYears]);

    const enrolledStudents = useMemo(() => {
        if (!activeYear) return [];
        return students.filter(s => {
            const hasPayments = s.payments?.some(p => p.academicYear === activeYear);
            const nameMatches = s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.id.toLowerCase().includes(searchTerm.toLowerCase());
            return hasPayments && nameMatches && s.status !== 'Inativo';
        });
    }, [students, activeYear, searchTerm]);

    const getStudentTotalPaid = (student: Student) => {
        if (!activeYear || !student.payments) return 0;
        return student.payments.filter(p => p.academicYear === activeYear).reduce((acc, curr) => acc + curr.amount, 0);
    };

    const formatPrice = (price: number) => {
        return price.toLocaleString('pt-MZ', { style: 'currency', currency: financialSettings.currency || 'MZN' });
    };

    const handleOpenStudentDetails = (student: Student) => {
        setSelectedStudent(student);
        setTransactionType('Mensalidade');
        setSelectedMonth(new Date().getMonth() + 1);
        setSelectedMethod('Numerário');
        setTransactionId('');
        setSelectedUniforms({});
        setSelectedBooks({});
        setSelectedCharges({});
        setIsSuccess(false);
        setLastPaymentId(null);
    };

    const handleCloseDetails = () => {
        setSelectedStudent(null);
        setIsTransactionModalOpen(false);
    };

    const handlePrintReceipt = (payment: PaymentRecord) => {
        if (!selectedStudent) return;
        const operatorToPrint = payment.operatorName || currentUser.name;
        printReceipt(payment, selectedStudent, schoolSettings, financialSettings.currency, operatorToPrint);
    };

    const handlePrintStatement = () => {
        if (!selectedStudent || !activeYear) return;
        printStudentStatement(selectedStudent, Number(activeYear), financialSettings, schoolSettings);
    };

    const handleUpdatePayment = (updatedPayment: PaymentRecord) => {
        if (!selectedStudent) return;
        const updatedStudent = { ...selectedStudent, payments: selectedStudent.payments?.map(p => p.id === updatedPayment.id ? updatedPayment : p) || [] };
        onStudentsChange(students.map(s => s.id === selectedStudent.id ? updatedStudent : s));
        setSelectedStudent(updatedStudent);
    };

    const handleDeletePayment = (paymentId: string) => {
        if (!selectedStudent) return;
        if (window.confirm('Apagar este registro permanentemente?')) {
            const updatedStudent = { ...selectedStudent, payments: selectedStudent.payments?.filter(p => p.id !== paymentId) };
            onStudentsChange(students.map(s => s.id === selectedStudent.id ? updatedStudent : s));
            setSelectedStudent(updatedStudent);
        }
    };

    const isPaymentLate = (targetMonth: number, academicYear: number, student: Student): boolean => {
        const profile = student.financialProfile;
        if (profile?.status === 'Sem Multa' || profile?.status === 'Isento Total') return false;
        if (!activeYear) return false;
        const now = new Date();
        if (academicYear < now.getFullYear()) return true;
        if (academicYear > now.getFullYear()) return false;
        if (targetMonth < now.getMonth() + 1) return true;
        if (targetMonth === now.getMonth() + 1) return now.getDate() > (financialSettings.monthlyPaymentLimitDay || 10);
        return false;
    };

    const getMonthlyFeeForStudent = (student: Student | null) => {
        if (!student) return financialSettings.monthlyFee;
        const specificFee = financialSettings.classSpecificFees?.find(c => c.classLevel === student.desiredClass);
        const baseFee = specificFee ? specificFee.monthlyFee : financialSettings.monthlyFee;
        const profile = student.financialProfile || { status: 'Normal' };
        if (profile.status === 'Isento Total') return 0;
        if (profile.status === 'Desconto Parcial' && profile.affectedTypes?.includes('Mensalidade')) return baseFee * (1 - (profile.discountPercentage || 0) / 100);
        return baseFee;
    };

    const getMonthlyFinancialStatus = (student: Student, year: number, month: number) => {
        const totalPaid = (student.payments || []).filter(p => p.academicYear === year && (p.type === 'Mensalidade' || p.type === 'Matrícula' || p.type === 'Renovação') && p.referenceMonth === month).reduce((acc, curr) => acc + curr.amount, 0);
        const baseFee = getMonthlyFeeForStudent(student);
        const penalty = isPaymentLate(month, year, student) ? (baseFee * (financialSettings.latePaymentPenaltyPercent / 100)) : 0;
        const totalRequired = baseFee + penalty;
        return { totalPaid, totalRequired, remaining: Math.max(0, totalRequired - totalPaid), isFullyPaid: totalPaid >= totalRequired - 1, isPartiallyPaid: totalPaid > 0 && totalPaid < totalRequired - 1 };
    };

    const calculateTransactionTotal = () => {
        let total = 0;
        if (transactionType === 'Mensalidade' && selectedStudent) total = getMonthlyFinancialStatus(selectedStudent, Number(activeYear), selectedMonth).remaining;
        else if (transactionType === 'Uniforme') {
            Object.keys(selectedUniforms).forEach(id => {
                if (selectedUniforms[id]) {
                    const item = financialSettings.uniforms.find(u => u.id === id);
                    if (item) total += item.price; // Simplified for demo
                }
            });
        } else if (transactionType === 'Material') {
            Object.keys(selectedBooks).forEach(id => {
                if (selectedBooks[id]) {
                    const item = financialSettings.books.find(b => b.id === id);
                    if (item) total += item.price;
                }
            });
        } else if (transactionType === 'Multa/Danos' && selectedStudent) {
            Object.keys(selectedCharges).forEach(id => {
                if (selectedCharges[id]) {
                    const charge = selectedStudent.extraCharges?.find(c => c.id === id);
                    if (charge) total += charge.amount;
                }
            });
        }
        return total;
    };

    const handleProcessTransaction = () => {
        if (!selectedStudent || !activeYear) return;
        const total = calculateTransactionTotal();
        const items: PaymentItem[] = [];
        let refMonth = undefined;
        if (transactionType === 'Mensalidade') {
            items.push({ item: `Mensalidade (${months.find(m => m.val === selectedMonth)?.name})`, value: total });
            refMonth = selectedMonth;
        } else if (transactionType === 'Uniforme') {
             Object.keys(selectedUniforms).forEach(id => {
                if (selectedUniforms[id]) {
                    const item = financialSettings.uniforms.find(u => u.id === id);
                    if (item) items.push({ item: item.name, value: item.price });
                }
            });
        } else if (transactionType === 'Multa/Danos') {
             Object.keys(selectedCharges).forEach(id => {
                if (selectedCharges[id]) {
                    const charge = selectedStudent.extraCharges?.find(c => c.id === id);
                    if (charge) items.push({ item: charge.description, value: charge.amount });
                }
            });
        }

        const newPayment: PaymentRecord = {
            id: `pay_${Date.now()}`, date: new Date().toISOString().split('T')[0], amount: total, type: transactionType, method: selectedMethod, academicYear: Number(activeYear), referenceMonth: refMonth,
            description: `${transactionType}${transactionId ? ' (Ref: ' + transactionId + ')' : ''}`, items: items, operatorName: currentUser.name
        };

        const updatedStudents = students.map(s => s.id === selectedStudent.id ? { ...s, payments: [...(s.payments || []), newPayment], extraCharges: transactionType === 'Multa/Danos' ? (s.extraCharges || []).map(c => selectedCharges[c.id] ? { ...c, isPaid: true } : c) : s.extraCharges } : s);
        onStudentsChange(updatedStudents);
        setLastPaymentId(newPayment.id);
        setIsSuccess(true);
        setSelectedStudent(updatedStudents.find(s => s.id === selectedStudent.id) || null);
    };

    const isMobileMethod = ['MPesa', 'e-Mola', 'mKesh'].includes(selectedMethod);

    const monthlyStatus = useMemo(() => {
        if (!selectedStudent || !activeYear) return [];
        const acYear = academicYears.find(y => y.year === activeYear);
        const startMonth = acYear ? (acYear.startMonth || 2) : 2;
        const endMonth = acYear ? (acYear.endMonth || 11) : 11;
        const matMonth = new Date(selectedStudent.matriculationDate).getMonth() + 1;
        const matYear = new Date(selectedStudent.matriculationDate).getFullYear();
        const effStart = matYear === activeYear ? Math.max(startMonth, matMonth) : startMonth;
        const statusList = [];
        const now = new Date();
        for (let m = startMonth; m <= endMonth; m++) {
            if (m < effStart) { statusList.push({ month: m, status: 'Isento' }); continue; }
            const status = getMonthlyFinancialStatus(selectedStudent, Number(activeYear), m);
            if (status.isFullyPaid) statusList.push({ month: m, status: 'Pago', details: status });
            else if (status.isPartiallyPaid) statusList.push({ month: m, status: 'Parcial', details: status });
            else {
                if (activeYear < now.getFullYear() || (activeYear === now.getFullYear() && m < now.getMonth() + 1)) statusList.push({ month: m, status: 'Atrasado', details: status });
                else if (activeYear === now.getFullYear() && m === now.getMonth() + 1) statusList.push({ month: m, status: now.getDate() > (financialSettings.monthlyPaymentLimitDay || 10) ? 'Atrasado' : 'Pendente', details: status });
                else statusList.push({ month: m, status: 'Futuro', details: status });
            }
        }
        return statusList;
    }, [selectedStudent, activeYear, academicYears, financialSettings]);

    return (
        <div className="space-y-6">
            <div className="bg-white p-6 rounded-2xl shadow-lg flex flex-col md:flex-row justify-between items-center gap-4">
                <div><h3 className="text-xl font-bold text-gray-800">Histórico Financeiro</h3><p className="text-sm text-gray-500">Visualize mensalidades e registe novos pagamentos.</p></div>
                <div className="flex gap-4 w-full md:w-auto">
                    <select value={activeYear} onChange={e => setActiveYear(Number(e.target.value))} className="p-2 border rounded-lg bg-gray-50">
                        <option value="">Ano Letivo</option>
                        {academicYears.map(y => <option key={y.id} value={y.year}>{y.year}</option>)}
                    </select>
                    <input type="text" placeholder="Buscar aluno..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="p-2 border rounded-lg w-full md:w-64" />
                </div>
            </div>

            <div className="bg-white rounded-2xl shadow-lg overflow-hidden">
                <table className="min-w-full divide-y divide-gray-200">
                    <thead className="bg-gray-50">
                        <tr><th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Nome</th><th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Classe</th><th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">Total Pago</th><th className="px-6 py-3 text-center text-xs font-medium text-gray-500 uppercase">Ações</th></tr>
                    </thead>
                    <tbody className="bg-white divide-y divide-gray-200">
                        {enrolledStudents.map(student => (
                            <tr key={student.id} className="hover:bg-gray-50">
                                <td className="px-6 py-4 flex items-center"><img className="h-8 w-8 rounded-full object-cover mr-3" src={student.profilePictureUrl} alt="" /><span className="text-sm font-medium">{student.name}</span></td>
                                <td className="px-6 py-4 text-sm text-gray-500">{student.desiredClass}</td>
                                <td className="px-6 py-4 text-right text-sm font-bold text-green-600">{formatPrice(getStudentTotalPaid(student))}</td>
                                <td className="px-6 py-4 text-center"><button onClick={() => handleOpenStudentDetails(student)} className="text-indigo-600 font-bold text-sm">Ver Extrato</button></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {selectedStudent && (
                <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex justify-center items-center p-4">
                    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-5xl max-h-[95vh] flex flex-col animate-fade-in">
                        <header className="flex items-center justify-between p-4 border-b">
                            <div><h2 className="text-xl font-bold text-gray-800">{selectedStudent.name}</h2><p className="text-sm text-gray-500">Gestão de Mensalidades {activeYear}</p></div>
                            <div className="flex gap-2"><button onClick={handlePrintStatement} className="p-2 bg-gray-100 rounded-lg"><PrinterIcon className="w-5 h-5"/></button><button onClick={handleCloseDetails} className="p-2 hover:bg-red-50 text-red-500 rounded-lg"><CloseIcon className="w-6 h-6"/></button></div>
                        </header>
                        <div className="flex-1 overflow-y-auto p-6 grid grid-cols-1 lg:grid-cols-3 gap-6">
                            <div className="lg:col-span-2 space-y-6">
                                <div className="bg-indigo-50 p-4 rounded-xl border border-indigo-100">
                                    <h3 className="font-black text-indigo-900 text-xs uppercase mb-4 flex items-center"><CalendarIcon className="w-4 h-4 mr-2" />Carnê de Mensalidades</h3>
                                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3">
                                        {monthlyStatus.map(ms => (
                                            <div key={ms.month} className={`p-3 rounded-xl border flex flex-col items-center justify-center text-center relative transition-all ${
                                                ms.status === 'Pago' ? 'bg-green-100 border-green-200 text-green-700' :
                                                ms.status === 'Parcial' ? 'bg-blue-100 border-blue-200 text-blue-700' :
                                                ms.status === 'Atrasado' ? 'bg-red-100 border-red-200 text-red-700' :
                                                ms.status === 'Pendente' ? 'bg-yellow-100 border-yellow-200 text-yellow-700' : 'bg-gray-50 border-gray-100 opacity-50'
                                            }`}>
                                                <span className="text-[10px] font-black uppercase mb-1">{months.find(m => m.val === ms.month)?.name}</span>
                                                <span className="text-xs font-bold">{ms.status}</span>
                                                {ms.status !== 'Pago' && ms.status !== 'Isento' && ms.status !== 'Futuro' && (
                                                    <button onClick={() => { setTransactionType('Mensalidade'); setSelectedMonth(ms.month); setIsTransactionModalOpen(true); setIsSuccess(false); }} className="mt-2 text-[10px] bg-white px-3 py-1 rounded-full shadow-sm hover:scale-105 transition-transform font-black uppercase">Pagar</button>
                                                )}
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            </div>

                            <div className="lg:col-span-1">
                                {isTransactionModalOpen ? (
                                    <div className="bg-gray-50 p-6 rounded-2xl border-2 border-indigo-100 shadow-xl space-y-4 animate-slide-up">
                                        <h4 className="font-black text-gray-800 uppercase text-sm border-b pb-2">Novo Pagamento</h4>
                                        <div className="space-y-4">
                                            <div>
                                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-2">Método de Pagamento</label>
                                                <div className="grid grid-cols-3 gap-2">
                                                    {['Numerário', 'MPesa', 'e-Mola', 'mKesh'].map(m => (
                                                        <button 
                                                            key={m} 
                                                            onClick={() => { setSelectedMethod(m as PaymentMethod); setTransactionId(''); }}
                                                            className={`p-2 rounded-xl border-2 text-[9px] font-black uppercase flex flex-col items-center gap-1 transition-all ${
                                                                selectedMethod === m ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'bg-white border-gray-100 text-gray-500'
                                                            }`}
                                                        >
                                                            {['MPesa','e-Mola','mKesh'].includes(m) && <MobilePaymentIcon type={m === 'MPesa' ? 'mpesa' : m === 'e-Mola' ? 'emola' : 'mkesh'} className="w-5 h-5"/>}
                                                            {m}
                                                        </button>
                                                    ))}
                                                </div>
                                            </div>

                                            {isMobileMethod && (
                                                <div className="bg-white p-3 rounded-xl border border-indigo-100 space-y-3">
                                                    <p className="text-[10px] font-bold text-indigo-600">Instruções: {
                                                        selectedMethod === 'MPesa' ? `Código M-Pesa: ${financialSettings.mobilePaymentConfig?.mpesaCode || '---'}` :
                                                        selectedMethod === 'e-Mola' ? `Número e-Mola: ${financialSettings.mobilePaymentConfig?.emolaCode || '---'}` :
                                                        `Código mKesh: ${financialSettings.mobilePaymentConfig?.mkeshCode || '---'}`
                                                    }</p>
                                                    <input 
                                                        type="text" 
                                                        value={transactionId} 
                                                        onChange={e => setTransactionId(e.target.value)} 
                                                        placeholder="Referência da Transação"
                                                        className="w-full p-2 border-2 border-indigo-50 rounded-lg text-xs font-mono uppercase font-bold"
                                                    />
                                                </div>
                                            )}

                                            <div className="pt-4 border-t flex justify-between items-center">
                                                <span className="text-xs font-bold text-gray-500">Valor Total:</span>
                                                <span className="text-xl font-black text-green-600">{formatPrice(calculateTransactionTotal())}</span>
                                            </div>

                                            {isSuccess ? (
                                                <div className="space-y-2">
                                                    <div className="bg-green-500 text-white p-2 rounded-lg text-center font-black text-xs uppercase">Sucesso!</div>
                                                    <button onClick={() => { const p = selectedStudent.payments?.find(pay => pay.id === lastPaymentId); if(p) handlePrintReceipt(p); }} className="w-full py-2 bg-indigo-600 text-white rounded-lg font-bold text-xs uppercase">Imprimir Recibo</button>
                                                </div>
                                            ) : (
                                                <button 
                                                    onClick={handleProcessTransaction}
                                                    disabled={calculateTransactionTotal() <= 0 || (isMobileMethod && !transactionId)}
                                                    className="w-full py-3 bg-indigo-600 text-white rounded-xl font-black uppercase tracking-widest text-xs shadow-lg hover:bg-indigo-700 disabled:bg-gray-300 transition-all"
                                                >
                                                    Confirmar Recebimento
                                                </button>
                                            )}
                                        </div>
                                    </div>
                                ) : (
                                    <div className="text-center py-10 text-gray-400"><ClockIcon className="w-10 h-10 mx-auto mb-2 opacity-20"/><p className="text-xs font-bold uppercase">Selecione um mês para pagar</p></div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            )}
            <EditPaymentModal isOpen={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} payment={editingPayment} onUpdatePayment={handleUpdatePayment} />
        </div>
    );
};

export default FinancialRecords;

import React, { useState, useMemo, useEffect } from 'react';
import { Student, FinancialSettings, AcademicYear, PaymentRecord, SchoolSettings, PaymentItem, PaymentMethod, User, AppNotification, UserRole, PaymentType } from '../types';
import { CheckCircleIcon, ExclamationTriangleIcon, MobilePaymentIcon } from './icons/IconComponents';
import { printReceipt } from './ReceiptUtils';

interface EnrollmentPaymentProps {
    students: Student[];
    onStudentsChange: (students: Student[]) => void;
    financialSettings: FinancialSettings;
    academicYears: AcademicYear[];
    currentUser: User;
    users: User[];
    onAddNotifications: (notifications: AppNotification[]) => void;
    // Added schoolSettings to props
    schoolSettings: SchoolSettings;
}

const EnrollmentPayment: React.FC<EnrollmentPaymentProps> = ({ students, onStudentsChange, financialSettings, academicYears, currentUser, users, onAddNotifications, schoolSettings }) => {
    const [selectedStudentId, setSelectedStudentId] = useState('');
    const [selectedYear, setSelectedYear] = useState<number | ''>('');
    const [paymentType, setPaymentType] = useState<PaymentTypeOption>('new');
    const [selectedMethod, setSelectedMethod] = useState<PaymentMethod>('Numerário');
    const [transactionId, setTransactionId] = useState(''); // Novo: ID da transação mobile
    const [selectedUniforms, setSelectedUniforms] = useState<Record<string, boolean>>({});
    const [selectedBooks, setSelectedBooks] = useState<Record<string, boolean>>({});

    const [payFirstMonth, setPayFirstMonth] = useState(true);
    const [isSuccess, setIsSuccess] = useState(false);
    const [lastPayment, setLastPayment] = useState<PaymentRecord | null>(null);

    useEffect(() => {
        const activeYear = academicYears.find(y => y.status === 'Em Curso' || y.status === 'Planeado');
        if (activeYear) setSelectedYear(activeYear.year);
    }, [academicYears]);

    const eligibleStudents = useMemo(() => {
        if (!selectedYear) return [];
        return students.filter(student => {
            const hasPaid = student.payments?.some(p => 
                p.academicYear === Number(selectedYear) && 
                (p.type === 'Matrícula' || p.type === 'Renovação')
            );
            return !hasPaid;
        });
    }, [students, selectedYear]);

    useEffect(() => {
        if (selectedStudentId && !eligibleStudents.find(s => s.id === selectedStudentId)) {
            setSelectedStudentId('');
            setSelectedUniforms({});
            setSelectedBooks({});
        }
    }, [eligibleStudents, selectedStudentId]);

    const selectedStudent = useMemo(() => students.find(s => s.id === selectedStudentId), [students, selectedStudentId]);

    const isReturningStudent = useMemo(() => {
        if (!selectedStudent || !selectedYear) return false;
        return selectedStudent.payments?.some(p => 
            p.academicYear < Number(selectedYear) && 
            (p.type === 'Matrícula' || p.type === 'Renovação')
        ) || false;
    }, [selectedStudent, selectedYear]);

    const pastDebts = useMemo(() => {
        if (!selectedStudent || !selectedYear || !isReturningStudent) return null;
        const profile = selectedStudent.financialProfile || { status: 'Normal' };
        if (profile.status === 'Isento Total') return null;
        const debts: number[] = [];
        const matriculationYear = new Date(selectedStudent.matriculationDate).getFullYear();
        academicYears.forEach(ay => {
            if (ay.year < Number(selectedYear) && ay.year >= matriculationYear) {
                let yearObligation = 0;
                let renewalFee = financialSettings.renewalFee;
                let monthlyFee = financialSettings.monthlyFee;
                if (profile.status === 'Desconto Parcial') {
                    if (profile.affectedTypes?.includes('Renovação')) renewalFee *= (1 - (profile.discountPercentage || 0)/100);
                    if (profile.affectedTypes?.includes('Mensalidade')) monthlyFee *= (1 - (profile.discountPercentage || 0)/100);
                }
                yearObligation += renewalFee;
                let monthsInYear = (ay.endMonth || 11) - (ay.startMonth || 2) + 1;
                if (selectedStudent.status === 'Suspenso' && selectedStudent.suspensionDate) {
                    const suspDate = new Date(selectedStudent.suspensionDate);
                    if (suspDate.getFullYear() === ay.year) {
                        const activeMonthsCount = Math.max(0, (suspDate.getMonth() + 1) - (ay.startMonth || 2) + 1);
                        monthsInYear = Math.min(monthsInYear, activeMonthsCount);
                    } else if (suspDate.getFullYear() < ay.year) {
                        monthsInYear = 0;
                        yearObligation = 0;
                    }
                }
                yearObligation += (monthlyFee * monthsInYear);
                const totalPaidInYear = selectedStudent.payments
                    ?.filter(p => p.academicYear === ay.year && (p.type === 'Matrícula' || p.type === 'Renovação' || p.type === 'Mensalidade'))
                    .reduce((acc, curr) => acc + curr.amount, 0) || 0;
                if (yearObligation > 0 && (yearObligation - totalPaidInYear) > 500) {
                    debts.push(ay.year);
                }
            }
        });
        return debts.length > 0 ? debts : null;
    }, [selectedStudent, selectedYear, isReturningStudent, academicYears, financialSettings]);

    useEffect(() => {
        if (selectedStudent) {
            setPaymentType(isReturningStudent ? 'renewal' : 'new');
        }
    }, [selectedStudent, isReturningStudent]);

    const relevantBooks = useMemo(() => {
        if (!selectedStudent) return [];
        return financialSettings.books.filter(b => b.classLevel === selectedStudent.desiredClass);
    }, [selectedStudent, financialSettings]);

    const calculateDiscountedFee = (baseValue: number, type: PaymentType): number => {
        if (!selectedStudent) return baseValue;
        const profile = selectedStudent.financialProfile || { status: 'Normal' };
        if (profile.status === 'Isento Total') return 0;
        if (profile.status === 'Desconto Parcial' && profile.affectedTypes?.includes(type)) {
            return baseValue * (1 - (profile.discountPercentage || 0) / 100);
        }
        return baseValue;
    };

    const baseFee = useMemo(() => {
        const specificFee = selectedStudent?.desiredClass 
            ? financialSettings.classSpecificFees?.find(c => c.classLevel === selectedStudent.desiredClass)
            : undefined;
        let rawFee = paymentType === 'renewal' 
            ? (specificFee ? specificFee.renewalFee : financialSettings.renewalFee)
            : (specificFee ? specificFee.enrollmentFee : financialSettings.enrollmentFee);
        return calculateDiscountedFee(rawFee, paymentType === 'new' ? 'Matrícula' : 'Renovação');
    }, [paymentType, selectedStudent, financialSettings]);

    const currentMonthlyFee = useMemo(() => {
        const specificFee = selectedStudent?.desiredClass 
            ? financialSettings.classSpecificFees?.find(c => c.classLevel === selectedStudent.desiredClass)
            : undefined;
        const rawFee = specificFee ? specificFee.monthlyFee : financialSettings.monthlyFee;
        return calculateDiscountedFee(rawFee, 'Mensalidade');
    }, [selectedStudent, financialSettings]);

    const handleStudentChange = (id: string) => {
        setSelectedStudentId(id);
        setSelectedUniforms({});
        setSelectedBooks({});
        setSelectedMethod('Numerário');
        setTransactionId('');
        setPayFirstMonth(true);
        setIsSuccess(false);
        setLastPayment(null);
    };

    const toggleUniform = (id: string) => setSelectedUniforms(prev => ({ ...prev, [id]: !prev[id] }));
    const toggleBook = (id: string) => setSelectedBooks(prev => ({ ...prev, [id]: !prev[id] }));

    const calculateTotal = () => {
        let total = baseFee + calculateDiscountedFee(financialSettings.annualExamFee, 'Taxa de Exames');
        if (payFirstMonth) total += currentMonthlyFee;
        Object.keys(selectedUniforms).forEach(id => {
            if (selectedUniforms[id]) {
                const item = financialSettings.uniforms.find(u => u.id === id);
                if (item) total += calculateDiscountedFee(item.price, 'Uniforme');
            }
        });
        Object.keys(selectedBooks).forEach(id => {
            if (selectedBooks[id]) {
                const item = financialSettings.books.find(b => b.id === id);
                if (item) total += calculateDiscountedFee(item.price, 'Material');
            }
        });
        return total;
    };

    const formatCurrency = (val: number) => {
        return val.toLocaleString('pt-MZ', { style: 'currency', currency: financialSettings.currency || 'MZN' });
    };

    const handleProcessPayment = () => {
        if (!selectedStudent || !selectedYear) return;
        if (pastDebts) {
            alert('Não é possível prosseguir. O aluno possui dívidas de anos anteriores.');
            return;
        }

        const paymentTypeLabel = paymentType === 'new' ? 'Matrícula' : 'Renovação';
        const items: PaymentItem[] = [];
        let totalPaid = 0;

        items.push({ item: `${paymentTypeLabel} (${selectedStudent.desiredClass})`, value: baseFee });
        totalPaid += baseFee;

        const examFee = calculateDiscountedFee(financialSettings.annualExamFee, 'Taxa de Exames');
        items.push({ item: 'Taxas de Testes/Exames', value: examFee });
        totalPaid += examFee;

        let firstMonthlyFeeReference: number | undefined = undefined;
        if (payFirstMonth) { 
            const acYear = academicYears.find(y => y.year === Number(selectedYear));
            const startMonth = acYear ? (acYear.startMonth || 2) : 2;
            const now = new Date();
            const currentMonth = now.getMonth() + 1;
            firstMonthlyFeeReference = Number(selectedYear) > now.getFullYear() ? startMonth : Math.max(startMonth, currentMonth);
            const monthName = months.find(m => m.val === firstMonthlyFeeReference)?.name || 'Mês Referência';
            items.push({ item: `1ª Mensalidade (${monthName})`, value: currentMonthlyFee });
            totalPaid += currentMonthlyFee;
        }

        Object.keys(selectedUniforms).forEach(id => {
            if (selectedUniforms[id]) {
                const item = financialSettings.uniforms.find(u => u.id === id);
                if (item) {
                    const p = calculateDiscountedFee(item.price, 'Uniforme');
                    items.push({ item: item.name, value: p });
                    totalPaid += p;
                }
            }
        });

        Object.keys(selectedBooks).forEach(id => {
            if (selectedBooks[id]) {
                const item = financialSettings.books.find(b => b.id === id);
                if (item) {
                    const p = calculateDiscountedFee(item.price, 'Material');
                    items.push({ item: item.title, value: p });
                    totalPaid += p;
                }
            }
        });

        const newPayment: PaymentRecord = {
            id: `pay_${Date.now()}`,
            date: new Date().toISOString().split('T')[0],
            amount: totalPaid,
            type: paymentTypeLabel,
            method: selectedMethod,
            academicYear: Number(selectedYear),
            description: `${paymentTypeLabel} ${selectedYear}${transactionId ? ' (Ref: ' + transactionId + ')' : ''}`,
            items: items,
            operatorName: currentUser.name
        };
        if (firstMonthlyFeeReference) newPayment.referenceMonth = firstMonthlyFeeReference;

        const updatedStudents: Student[] = students.map(s => {
            if (s.id === selectedStudentId) {
                return {
                    ...s,
                    status: 'Ativo',
                    suspensionDate: undefined,
                    payments: [...(s.payments || []), newPayment],
                    matriculationDate: paymentType === 'new' ? new Date().toISOString().split('T')[0] : s.matriculationDate 
                } as Student;
            }
            return s;
        });

        onStudentsChange(updatedStudents);
        setLastPayment(newPayment);
        onAddNotifications(users.filter(u => u.role === UserRole.ADMIN).map(admin => ({
            id: `notif_pay_${Date.now()}_${admin.id}`,
            userId: admin.id, type: 'admin_alert', title: 'Recebimento Confirmado',
            message: `Pagamento de ${formatCurrency(totalPaid)} de ${selectedStudent.name} (${paymentTypeLabel}).`,
            read: false, timestamp: new Date().toISOString()
        })));
        setIsSuccess(true);
    };

    const handlePrintReceipt = () => {
        if (lastPayment && selectedStudent) {
            const operatorToPrint = lastPayment.operatorName || currentUser.name;
            // Fixed missing schoolSettings reference
            printReceipt(lastPayment, selectedStudent, schoolSettings, financialSettings.currency, operatorToPrint);
        }
    };

    const isMobileMethod = ['MPesa', 'e-Mola', 'mKesh'].includes(selectedMethod);

    return (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-6">
                <div className="bg-white p-6 rounded-2xl shadow-lg">
                    <h3 className="text-lg font-bold text-gray-800 mb-4">1. Selecionar Aluno e Ano</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                         <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Ano Letivo Referente</label>
                            <select value={selectedYear} onChange={e => setSelectedYear(Number(e.target.value))} className="w-full p-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500">
                                <option value="">Selecione...</option>
                                {academicYears.map(y => <option key={y.id} value={y.year}>{y.year} ({y.status})</option>)}
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Nome do Aluno</label>
                            <select value={selectedStudentId} onChange={e => handleStudentChange(e.target.value)} className="w-full p-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500" disabled={!selectedYear}>
                                <option value="">{selectedYear ? 'Selecione...' : 'Selecione o ano primeiro'}</option>
                                {eligibleStudents.map(s => <option key={s.id} value={s.id}>{s.name} (ID: {s.id})</option>)}
                            </select>
                        </div>
                    </div>
                    {selectedStudent && (
                        <div className="bg-indigo-50 p-3 rounded-lg border border-indigo-100 text-sm text-indigo-800 flex justify-between items-center">
                            <span><strong>Classe Pretendida:</strong> {selectedStudent.desiredClass}</span>
                            {selectedStudent.financialProfile && selectedStudent.financialProfile.status !== 'Normal' && (
                                <span className="bg-white px-2 py-1 rounded text-xs font-bold text-green-600 border border-green-200">{selectedStudent.financialProfile.status}</span>
                            )}
                        </div>
                    )}
                </div>

                {selectedStudent && selectedYear && (
                    <>
                        {pastDebts && (
                            <div className="bg-red-50 border-l-4 border-red-500 p-4 rounded-md shadow-md animate-pulse">
                                <div className="flex">
                                    <div className="flex-shrink-0"><ExclamationTriangleIcon className="h-5 w-5 text-red-600" /></div>
                                    <div className="ml-3">
                                        <h3 className="text-sm font-bold text-red-800">Bloqueio Financeiro</h3>
                                        <div className="mt-2 text-sm text-red-700">
                                            <p>Dívidas pendentes: <strong>{pastDebts.join(', ')}</strong>. Regularize para prosseguir.</p>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}

                        <div className={`bg-white p-6 rounded-2xl shadow-lg transition-opacity ${pastDebts ? 'opacity-50 pointer-events-none' : 'opacity-100'}`}>
                            <h3 className="text-lg font-bold text-gray-800 mb-4">2. Método de Pagamento</h3>
                            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-6 gap-3">
                                {paymentMethods.map(method => {
                                    const isMpesa = method === 'MPesa';
                                    const isEmola = method === 'e-Mola';
                                    const isMkesh = method === 'mKesh';
                                    const isActive = selectedMethod === method;

                                    return (
                                        <button
                                            key={method}
                                            onClick={() => setSelectedMethod(method)}
                                            className={`flex flex-col items-center justify-center p-3 rounded-xl border-2 transition-all group ${
                                                isActive 
                                                ? (isMpesa ? 'border-red-500 bg-red-50' : isEmola ? 'border-orange-500 bg-orange-50' : isMkesh ? 'border-yellow-500 bg-yellow-50' : 'border-indigo-600 bg-indigo-50') 
                                                : 'border-gray-100 hover:border-gray-200 bg-white'
                                            }`}
                                        >
                                            {isMpesa || isEmola || isMkesh ? (
                                                <MobilePaymentIcon type={isMpesa ? 'mpesa' : isEmola ? 'emola' : 'mkesh'} className="w-8 h-8 mb-2" />
                                            ) : (
                                                <div className={`w-8 h-8 rounded-full flex items-center justify-center mb-2 ${isActive ? 'bg-indigo-600 text-white' : 'bg-gray-100 text-gray-400'}`}>
                                                    {method === 'Numerário' ? '$' : method === 'POS' ? '💳' : '🏦'}
                                                </div>
                                            )}
                                            <span className={`text-[10px] font-black uppercase text-center ${isActive ? 'text-gray-900' : 'text-gray-500'}`}>{method}</span>
                                        </button>
                                    );
                                })}
                            </div>

                            {/* Mobile Payment Instructions & Code Field */}
                            {isMobileMethod && financialSettings.enableMobilePayments && (
                                <div className="mt-6 p-4 rounded-xl border-2 border-dashed border-indigo-200 bg-indigo-50/30 animate-fade-in">
                                    <div className="flex flex-col md:flex-row gap-6">
                                        <div className="flex-1">
                                            <h4 className="text-xs font-black text-indigo-900 uppercase mb-3 flex items-center">
                                                <CheckCircleIcon className="w-4 h-4 mr-2" />
                                                Instruções para o Cliente
                                            </h4>
                                            <div className="space-y-2 text-sm text-gray-700">
                                                {selectedMethod === 'MPesa' && (
                                                    <p>Pagar via <strong>M-Pesa</strong> no código: <span className="bg-red-600 text-white px-2 py-0.5 rounded font-bold">{financialSettings.mobilePaymentConfig?.mpesaCode || '---'}</span></p>
                                                )}
                                                {selectedMethod === 'e-Mola' && (
                                                    <p>Pagar via <strong>e-Mola</strong> para o número: <span className="bg-orange-500 text-white px-2 py-0.5 rounded font-bold">{financialSettings.mobilePaymentConfig?.emolaCode || '---'}</span></p>
                                                )}
                                                {selectedMethod === 'mKesh' && (
                                                    <p>Pagar via <strong>mKesh</strong> no código: <span className="bg-yellow-400 text-black px-2 py-0.5 rounded font-bold">{financialSettings.mobilePaymentConfig?.mkeshCode || '---'}</span></p>
                                                )}
                                                <p className="text-[11px] text-gray-500 italic">Solicite ao cliente o ID/Referência da transação para confirmar.</p>
                                            </div>
                                        </div>
                                        <div className="flex-1">
                                            <label className="block text-xs font-black text-gray-500 uppercase mb-1">ID da Transação / Referência*</label>
                                            <input 
                                                type="text" 
                                                value={transactionId} 
                                                onChange={e => setTransactionId(e.target.value)} 
                                                placeholder="Ex: 8G457788A"
                                                className="w-full p-3 border-2 border-indigo-200 rounded-xl focus:ring-4 focus:ring-indigo-500/10 font-mono font-bold uppercase"
                                            />
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>

                         <div className={`bg-white p-6 rounded-2xl shadow-lg transition-opacity ${pastDebts ? 'opacity-50 pointer-events-none' : 'opacity-100'}`}>
                            <h3 className="text-lg font-bold text-gray-800 mb-4">3. Outros Itens (Opcional)</h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-3 mb-4">
                                {financialSettings.uniforms.map(item => (
                                    <label key={item.id} className={`flex justify-between items-center p-3 rounded-lg border cursor-pointer transition-colors ${selectedUniforms[item.id] ? 'bg-blue-50 border-blue-300' : 'hover:bg-gray-50 border-gray-200'}`}>
                                        <div className="flex items-center">
                                            <input type="checkbox" checked={!!selectedUniforms[item.id]} onChange={() => toggleUniform(item.id)} className="h-4 w-4 text-indigo-600 rounded focus:ring-indigo-500" />
                                            <span className="ml-2 text-sm font-medium text-gray-700">{item.name}</span>
                                        </div>
                                        <span className="text-sm font-bold text-gray-600">{formatCurrency(calculateDiscountedFee(item.price, 'Uniforme'))}</span>
                                    </label>
                                ))}
                            </div>
                            {relevantBooks.length > 0 && (
                                <div className="grid grid-cols-1 gap-3">
                                    {relevantBooks.map(item => (
                                        <label key={item.id} className={`flex justify-between items-center p-3 rounded-lg border cursor-pointer transition-colors ${selectedBooks[item.id] ? 'bg-blue-50 border-blue-300' : 'hover:bg-gray-50 border-gray-200'}`}>
                                            <div className="flex items-center">
                                                <input type="checkbox" checked={!!selectedBooks[item.id]} onChange={() => toggleBook(item.id)} className="h-4 w-4 text-indigo-600 rounded focus:ring-indigo-500" />
                                                <span className="ml-2 text-sm font-medium text-gray-700">{item.title}</span>
                                            </div>
                                            <span className="text-sm font-bold text-gray-600">{formatCurrency(calculateDiscountedFee(item.price, 'Material'))}</span>
                                        </label>
                                    ))}
                                </div>
                            )}
                        </div>
                    </>
                )}
            </div>

            <div className="lg:col-span-1">
                <div className="bg-white p-6 rounded-2xl shadow-lg sticky top-6">
                    <h3 className="text-xl font-bold text-gray-800 mb-6 pb-2 border-b">Resumo do Pagamento</h3>
                    {selectedStudent && selectedYear ? (
                        <div className={`space-y-4 ${pastDebts ? 'opacity-50 pointer-events-none' : 'opacity-100'}`}>
                            <div className="flex justify-between text-sm">
                                <span className="text-gray-600">{paymentType === 'new' ? 'Matrícula' : 'Inscrição'} ({selectedYear})</span>
                                <span className="font-medium">{formatCurrency(baseFee)}</span>
                            </div>
                            <div className="flex justify-between text-sm">
                                <span className="text-gray-600">Testes Anuais</span>
                                <span className="font-medium">{formatCurrency(calculateDiscountedFee(financialSettings.annualExamFee, 'Taxa de Exames'))}</span>
                            </div>
                            <div className="flex justify-between text-sm items-center py-2 border-t border-b border-gray-100 bg-gray-50 -mx-6 px-6">
                                <label className="flex items-center cursor-pointer text-gray-600 select-none">
                                    <input type="checkbox" checked={payFirstMonth} onChange={(e) => setPayFirstMonth(e.target.checked)} className="mr-2 rounded text-indigo-600 focus:ring-indigo-500 h-4 w-4" />
                                    Incluir 1ª Mensalidade
                                </label>
                                <span className={`font-medium ${payFirstMonth ? 'text-gray-800' : 'text-gray-400 line-through'}`}>{formatCurrency(currentMonthlyFee)}</span>
                            </div>
                            <div className="border-t border-gray-300 pt-4 mt-4">
                                <div className="flex justify-between items-center">
                                    <span className="text-lg font-bold text-gray-800">Total a Pagar</span>
                                    <span className="text-2xl font-bold text-green-600">{formatCurrency(calculateTotal())}</span>
                                </div>
                            </div>
                            <button 
                                onClick={handleProcessPayment}
                                disabled={!!pastDebts || (isMobileMethod && !transactionId)}
                                className={`w-full text-white font-black py-4 px-4 rounded-xl shadow-xl transform transition mt-4 uppercase tracking-widest ${
                                    (pastDebts || (isMobileMethod && !transactionId)) 
                                    ? 'bg-gray-400 cursor-not-allowed' 
                                    : 'bg-indigo-600 hover:bg-indigo-700 hover:scale-[1.02]'
                                }`}
                            >
                                {pastDebts ? 'Bloqueado' : isMobileMethod && !transactionId ? 'Insira Referência' : 'Confirmar e Receber'}
                            </button>
                        </div>
                    ) : (
                        <p className="text-center text-gray-500 italic">Selecione um aluno e o ano letivo para ver o resumo.</p>
                    )}
                </div>
            </div>
        </div>
    );
};

export default EnrollmentPayment;

import React, { useState, useMemo } from 'react';
import { User, UserRole, Student, AcademicYear, SchoolSettings, Turma, FinancialSettings, ExpenseRecord, DiscussionTopic, DiscussionMessage, AppNotification, SchoolRequest } from '../types';
import Sidebar from './Sidebar';
import Header from './Header';
import StudentList from './StudentList';
import UserManagement from './UserManagement';
import GuardianManagement from './GuardianManagement';
import GuardianPortal from './GuardianPortal';
import AcademicYearManagement from './AcademicYearManagement';
import SchoolCapacitySettings from './SchoolCapacitySettings';
import VacancyOverview from './VacancyOverview';
import TurmaManagement from './TurmaManagement';
import TeacherManagement from './TeacherManagement';
import FinancialSetup from './FinancialSetup';
import EnrollmentPayment from './EnrollmentPayment';
import FinancialRecords from './FinancialRecords';
import ReportsView from './ReportsView';
import DailyClosingSheet from './DailyClosingSheet';
import ExpenseManagement from './ExpenseManagement';
import InternalChat from './InternalChat';
import ClassManagement from './ClassManagement';
import RequestManagement from './RequestManagement';
import TransferManagement from './TransferManagement';
import DataManagement from './DataManagement';
import { ClipboardListIcon, CurrencyDollarIcon, CalendarIcon, TrendingDownIcon } from './icons/IconComponents';

interface DashboardProps {
  user: User;
  onLogout: () => void;
  onUpdateCurrentUser: (data: Partial<User>) => void;
  users: User[];
  onUsersChange: (users: User[]) => void;
  students: Student[];
  onStudentsChange: (students: Student[]) => void;
  onResetApp: () => void;
  onClearStudents: () => void;
  academicYears: AcademicYear[];
  onAcademicYearsChange: (years: AcademicYear[]) => void;
  schoolSettings: SchoolSettings;
  onSchoolSettingsChange: (settings: SchoolSettings) => void;
  financialSettings: FinancialSettings;
  onFinancialSettingsChange: (settings: FinancialSettings) => void;
  turmas: Turma[];
  onTurmasChange: (turmas: Turma[]) => void;
  expenses: ExpenseRecord[];
  onExpensesChange: (expenses: ExpenseRecord[]) => void;
  topics: DiscussionTopic[];
  onTopicsChange: (topics: DiscussionTopic[]) => void;
  messages: DiscussionMessage[];
  onMessagesChange: (messages: DiscussionMessage[]) => void;
  notifications: AppNotification[];
  onAddNotifications: (notifications: AppNotification[]) => void;
  onMarkNotificationAsRead: (id: string) => void;
  requests: SchoolRequest[];
  onRequestsChange: (requests: SchoolRequest[]) => void;
}

export type View = 'painel' | 'alunos' | 'turmas' | 'reuniao' | 'encarregados' | 'professores' | 'classes' | 'relatorios' | 'configuracoes' | 'gerenciar-usuarios' | 'financeiro' | 'solicitacoes' | 'transferencias';

const viewTitles: Record<View, string> = {
    'painel': 'Painel Principal',
    'alunos': 'Alunos',
    'turmas': 'Turmas',
    'reuniao': 'Comunicação',
    'encarregados': 'Encarregados',
    'professores': 'Professores',
    'classes': 'Relatório de Classes',
    'relatorios': 'Relatórios',
    'configuracoes': 'Configurações',
    'gerenciar-usuarios': 'Usuários',
    'financeiro': 'Finanças',
    'solicitacoes': 'Solicitações',
    'transferencias': 'Transferências'
};

const Dashboard: React.FC<DashboardProps> = (props) => {
  const { user, onLogout, onUpdateCurrentUser, users, onUsersChange, students, onStudentsChange, onResetApp, onClearStudents, academicYears, onAcademicYearsChange, schoolSettings, onSchoolSettingsChange, financialSettings, onFinancialSettingsChange, turmas, onTurmasChange, expenses, onExpensesChange, topics, onTopicsChange, messages, onMessagesChange, notifications, onAddNotifications, onMarkNotificationAsRead, requests, onRequestsChange } = props;

  const [activeView, setActiveView] = useState<View>('painel');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [financialTab, setFinancialTab] = useState<'payment' | 'setup' | 'records' | 'daily' | 'expenses'>('payment');

  const visibleStudents = useMemo(() => {
      if (user.role === UserRole.PROFESSOR) {
          const myTurmas = turmas.filter(t =>
              t.teachers?.some(teach => teach.teacherId === user.id) ||
              // @ts-ignore legacy
              t.teacherIds?.includes(user.id) || t.teacherId === user.id
          );
          const myStudentIds = new Set(myTurmas.flatMap(t => t.studentIds));
          return students.filter(s => myStudentIds.has(s.id));
      }
      return students;
  }, [user, turmas, students]);

  const visibleUsers = useMemo(() => {
      if (user.role === UserRole.PROFESSOR) {
          const guardianNames = new Set(visibleStudents.map(s => s.guardianName));
          return users.filter(u => {
              if (u.role !== UserRole.ENCARREGADO) return true; 
              return guardianNames.has(u.name);
          });
      }
      return users;
  }, [user, visibleStudents, users]);

  if (user.role === UserRole.ENCARREGADO) {
    if (activeView === 'reuniao') {
        return (
            <div className="flex h-screen bg-gray-50 font-sans overflow-hidden">
                <Sidebar user={user} activeView={activeView} setActiveView={setActiveView} isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} />
                <div className="flex-1 flex flex-col overflow-hidden">
                    <Header 
                        user={user} 
                        onLogout={onLogout} 
                        onUpdateProfile={onUpdateCurrentUser}
                        title={viewTitles[activeView]} 
                        notifications={notifications} 
                        onMarkNotificationAsRead={onMarkNotificationAsRead}
                        onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
                    />
                    <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-50 p-3 md:p-8">
                        <InternalChat 
                            currentUser={user}
                            users={users}
                            topics={topics}
                            onTopicsChange={onTopicsChange}
                            messages={messages}
                            onMessagesChange={onMessagesChange}
                            onAddNotifications={onAddNotifications}
                        />
                    </main>
                </div>
            </div>
        );
    }

    return <GuardianPortal 
              user={user} 
              onLogout={onLogout} 
              onUpdateCurrentUser={onUpdateCurrentUser}
              students={students}
              onStudentsChange={onStudentsChange}
              academicYears={academicYears}
              schoolSettings={schoolSettings}
              turmas={turmas}
              financialSettings={financialSettings}
              activeView={activeView}
              setActiveView={setActiveView}
              onAddNotifications={onAddNotifications}
              users={users}
            />;
  }

  const renderContent = () => {
    switch (activeView) {
        case 'painel':
            return <VacancyOverview turmas={turmas} schoolSettings={schoolSettings} students={students} academicYears={academicYears} />;
        case 'reuniao':
            return <InternalChat currentUser={user} users={users} topics={topics} onTopicsChange={onTopicsChange} messages={messages} onMessagesChange={onMessagesChange} onAddNotifications={onAddNotifications} />;
        case 'solicitacoes':
            return <RequestManagement currentUser={user} users={users} requests={requests} onRequestsChange={onRequestsChange} onAddNotifications={onAddNotifications} />;
        case 'transferencias':
            return <TransferManagement students={students} onStudentsChange={onStudentsChange} academicYears={academicYears} turmas={turmas} schoolSettings={schoolSettings} financialSettings={financialSettings} requests={requests} onRequestsChange={onRequestsChange} currentUser={user} />;
        case 'financeiro':
             if (user.role === UserRole.ADMIN || user.role === UserRole.SECRETARIA) {
                 return (
                     <div className="space-y-6">
                         <div className="flex space-x-1 p-1 bg-white border border-gray-100 rounded-xl shadow-sm w-full overflow-x-auto no-scrollbar">
                             <button 
                                onClick={() => setFinancialTab('payment')}
                                className={`px-4 py-2 rounded-lg text-xs font-black uppercase tracking-tight transition-all flex items-center whitespace-nowrap ${financialTab === 'payment' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-400 hover:bg-gray-50'}`}
                             >
                                 <CurrencyDollarIcon className="w-4 h-4 mr-2" />
                                 Matrículas
                             </button>
                             <button 
                                onClick={() => setFinancialTab('records')}
                                className={`px-4 py-2 rounded-lg text-xs font-black uppercase tracking-tight transition-all flex items-center whitespace-nowrap ${financialTab === 'records' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-400 hover:bg-gray-50'}`}
                             >
                                 <ClipboardListIcon className="w-4 h-4 mr-2" />
                                 Registos
                             </button>
                             <button 
                                onClick={() => setFinancialTab('expenses')}
                                className={`px-4 py-2 rounded-lg text-xs font-black uppercase tracking-tight transition-all flex items-center whitespace-nowrap ${financialTab === 'expenses' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-400 hover:bg-gray-50'}`}
                             >
                                 <TrendingDownIcon className="w-4 h-4 mr-2" />
                                 Despesas
                             </button>
                             <button 
                                onClick={() => setFinancialTab('daily')}
                                className={`px-4 py-2 rounded-lg text-xs font-black uppercase tracking-tight transition-all flex items-center whitespace-nowrap ${financialTab === 'daily' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-400 hover:bg-gray-50'}`}
                             >
                                 <CalendarIcon className="w-4 h-4 mr-2" />
                                 Fecho
                             </button>
                             {user.role === UserRole.ADMIN && (
                                <button 
                                    onClick={() => setFinancialTab('setup')}
                                    className={`px-4 py-2 rounded-lg text-xs font-black uppercase tracking-tight transition-all flex items-center whitespace-nowrap ${financialTab === 'setup' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-400 hover:bg-gray-50'}`}
                                >
                                    Setup
                                </button>
                             )}
                         </div>

                         {financialTab === 'payment' ? (
                             // Fixed missing schoolSettings prop
                             <EnrollmentPayment students={students} onStudentsChange={onStudentsChange} financialSettings={financialSettings} academicYears={academicYears} currentUser={user} users={users} onAddNotifications={onAddNotifications} schoolSettings={schoolSettings} />
                         ) : financialTab === 'records' ? (
                             <FinancialRecords students={students} onStudentsChange={onStudentsChange} financialSettings={financialSettings} academicYears={academicYears} currentUser={user} users={users} onAddNotifications={onAddNotifications} schoolSettings={schoolSettings} />
                         ) : financialTab === 'expenses' ? (
                             <ExpenseManagement expenses={expenses} onExpensesChange={onExpensesChange} currentUser={user} financialSettings={financialSettings} users={users} onAddNotifications={onAddNotifications} students={students} onStudentsChange={onStudentsChange} />
                         ) : financialTab === 'daily' ? (
                             <DailyClosingSheet students={students} financialSettings={financialSettings} schoolSettings={schoolSettings} currentUser={user} users={users} onAddNotifications={onAddNotifications} />
                         ) : (
                             <FinancialSetup settings={financialSettings} onSettingsChange={onFinancialSettingsChange} />
                         )}
                     </div>
                 );
             }
             return <div className="p-4 text-center text-gray-500 font-bold">Acesso negado.</div>;
        case 'alunos':
            return <StudentList user={user} users={visibleUsers} onUsersChange={onUsersChange} students={visibleStudents} onStudentsChange={onStudentsChange} onAddNotifications={onAddNotifications} financialSettings={financialSettings} academicYears={academicYears} />;
        case 'turmas':
             return <TurmaManagement turmas={turmas} onTurmasChange={onTurmasChange} students={students} academicYears={academicYears} schoolSettings={schoolSettings} users={users} currentUser={user} onStudentsChange={onStudentsChange} onAddNotifications={onAddNotifications} />;
        case 'professores':
            return <TeacherManagement users={users} onUsersChange={onUsersChange} currentUser={user} />;
        case 'encarregados':
            return <GuardianManagement users={visibleUsers} onUsersChange={onUsersChange} currentUser={user} students={visibleStudents} />;
        case 'gerenciar-usuarios':
            return <UserManagement users={users} onUsersChange={onUsersChange} currentUser={user} />;
        case 'classes':
            return <ClassManagement academicYears={academicYears} turmas={turmas} students={students} schoolSettings={schoolSettings} financialSettings={financialSettings} expenses={expenses} users={users} currentUser={user} />;
        case 'relatorios':
            return <ReportsView currentUser={user} students={students} academicYears={academicYears} turmas={turmas} schoolSettings={schoolSettings} users={users} financialSettings={financialSettings} expenses={expenses} />;
        case 'configuracoes':
            return (
                <div className="space-y-8 pb-10">
                    {user.role === UserRole.ADMIN && (
                      <>
                        <SchoolCapacitySettings settings={schoolSettings} onSettingsChange={onSchoolSettingsChange} />
                        <AcademicYearManagement academicYears={academicYears} onAcademicYearsChange={onAcademicYearsChange} students={students} onStudentsChange={onStudentsChange} turmas={turmas} schoolSettings={schoolSettings} />
                        <DataManagement schoolId={user.schoolId} />
                      </>
                    )}
                    <div className="p-6 bg-white rounded-2xl shadow-lg border border-gray-100">
                        <h3 className="text-xl font-bold text-gray-800 tracking-tight">Preferências Pessoais</h3>
                        <p className="mt-2 text-sm text-gray-500">Mais opções de personalização em breve.</p>
                    </div>

                    {user.role === UserRole.ADMIN && (
                        <div className="p-6 bg-white rounded-2xl shadow-lg border-2 border-red-100">
                            <h4 className="text-lg font-black text-red-700 flex items-center uppercase tracking-tighter">
                                <svg className="w-6 h-6 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                                Administração Crítica
                            </h4>
                            <div className="mt-4 grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div className="p-4 border border-red-50 rounded-xl bg-red-50/30">
                                    <p className="font-bold text-gray-800 text-sm">Limpar Todos Alunos</p>
                                    <p className="text-[10px] text-gray-500 mt-1 uppercase">Remove apenas os cadastros de estudantes.</p>
                                    <button onClick={onClearStudents} className="mt-3 w-full bg-white text-red-600 border border-red-200 text-xs font-black py-2 rounded-lg hover:bg-red-600 hover:text-white transition-all">LIMPAR AGORA</button>
                                </div>
                                <div className="p-4 border border-red-100 rounded-xl bg-red-50/50">
                                    <p className="font-bold text-gray-800 text-sm">Reset do Sistema</p>
                                    <p className="text-[10px] text-gray-500 mt-1 uppercase">Apaga absolutamente tudo (SaaS Reset).</p>
                                    <button onClick={onResetApp} className="mt-3 w-full bg-red-700 text-white text-xs font-black py-2 rounded-lg hover:bg-red-900 transition-all shadow-lg shadow-red-200">RESET TOTAL</button>
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            );
        default:
            return <div className="p-6 bg-white rounded-2xl shadow-md text-center py-20">
                <h3 className="text-xl font-bold text-gray-800">Bem-vindo(a)</h3>
                <p className="mt-2 text-gray-500">Selecione uma opção no menu para começar.</p>
            </div>;
    }
  }

  return (
    <div className="flex h-screen bg-gray-50 font-sans overflow-hidden">
      <Sidebar user={user} activeView={activeView} setActiveView={setActiveView} isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} />
      <div className="flex-1 flex flex-col overflow-hidden relative">
        <Header 
            user={user} 
            onLogout={onLogout} 
            onUpdateProfile={onUpdateCurrentUser}
            title={viewTitles[activeView]} 
            notifications={notifications}
            onMarkNotificationAsRead={onMarkNotificationAsRead}
            onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
        />
        <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-50 p-4 md:p-8">
          <div className="max-w-[1600px] mx-auto">
             {renderContent()}
          </div>
        </main>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { Student, FinancialSettings, AcademicYear, PaymentRecord, SchoolSettings, PaymentItem, PaymentMethod, User, AppNotification, UserRole, PaymentType } from '../types';
import { CheckCircleIcon, ExclamationTriangleIcon } from './icons/IconComponents';
import { printReceipt } from './ReceiptUtils';

interface EnrollmentPaymentProps {
    students: Student[];
    onStudentsChange: (students: Student[]) => void;
    financialSettings: FinancialSettings;
    academicYears: AcademicYear[];
    currentUser: User;
    users: User[];
    onAddNotifications: (notifications: AppNotification[]) => void;
    schoolSettings: SchoolSettings;
}

type PaymentTypeOption = 'new' | 'renewal';

const months = [
    { val: 1, name: 'Janeiro' }, { val: 2, name: 'Fevereiro' }, { val: 3, name: 'Março' },
    { val: 4, name: 'Abril' }, { val: 5, name: 'Maio' }, { val: 6, name: 'Junho' },
    { val: 7, name: 'Julho' }, { val: 8, name: 'Agosto' }, { val: 9, name: 'Setembro' },
    { val: 10, name: 'Outubro' }, { val: 11, name: 'Novembro' }, { val: 12, name: 'Dezembro' }
];

const paymentMethods: PaymentMethod[] = ['Numerário', 'Transferência Bancária', 'MPesa', 'e-Mola', 'mKesh', 'POS'];

const EnrollmentPayment: React.FC<EnrollmentPaymentProps> = ({ students, onStudentsChange, financialSettings, academicYears, currentUser, users, onAddNotifications, schoolSettings }) => {
    const [selectedStudentId, setSelectedStudentId] = useState('');
    const [selectedYear, setSelectedYear] = useState<number | ''>('');
    const [paymentType, setPaymentType] = useState<PaymentTypeOption>('new');
    const [selectedMethod, setSelectedMethod] = useState<PaymentMethod>('Numerário');
    const [transactionId, setTransactionId] = useState('');
    const [selectedUniforms, setSelectedUniforms] = useState<Record<string, boolean>>({});
    const [selectedBooks, setSelectedBooks] = useState<Record<string, boolean>>({});

    const [payFirstMonth, setPayFirstMonth] = useState(true);
    const [isSuccess, setIsSuccess] = useState(false);
    const [lastPayment, setLastPayment] = useState<PaymentRecord | null>(null);

    useEffect(() => {
        const activeYear = academicYears.find(y => y.status === 'Em Curso' || y.status === 'Planeado');
        if (activeYear) setSelectedYear(activeYear.year);
    }, [academicYears]);

    const eligibleStudents = useMemo(() => {
        if (!selectedYear) return [];
        return students.filter(student => {
            const hasPaid = student.payments?.some(p => 
                p.academicYear === Number(selectedYear) && 
                (p.type === 'Matrícula' || p.type === 'Renovação')
            );
            return !hasPaid;
        });
    }, [students, selectedYear]);

    const selectedStudent = useMemo(() => students.find(s => s.id === selectedStudentId), [students, selectedStudentId]);

    const isReturningStudent = useMemo(() => {
        if (!selectedStudent || !selectedYear) return false;
        return selectedStudent.payments?.some(p => 
            p.academicYear < Number(selectedYear) && 
            (p.type === 'Matrícula' || p.type === 'Renovação')
        ) || false;
    }, [selectedStudent, selectedYear]);

    useEffect(() => {
        if (selectedStudent) {
            setPaymentType(isReturningStudent ? 'renewal' : 'new');
        }
    }, [selectedStudent, isReturningStudent]);

    const calculateDiscountedFee = (baseValue: number, type: PaymentType): number => {
        if (!selectedStudent) return baseValue;
        const profile = selectedStudent.financialProfile || { status: 'Normal' };
        if (profile.status === 'Isento Total') return 0;
        if (profile.status === 'Desconto Parcial' && profile.affectedTypes?.includes(type)) {
            return baseValue * (1 - (profile.discountPercentage || 0) / 100);
        }
        return baseValue;
    };

    const baseFee = useMemo(() => {
        const specificFee = selectedStudent?.desiredClass 
            ? financialSettings.classSpecificFees?.find(c => c.classLevel === selectedStudent.desiredClass)
            : undefined;
        let rawFee = paymentType === 'renewal' 
            ? (specificFee ? specificFee.renewalFee : financialSettings.renewalFee)
            : (specificFee ? specificFee.enrollmentFee : financialSettings.enrollmentFee);
        return calculateDiscountedFee(rawFee, paymentType === 'new' ? 'Matrícula' : 'Renovação');
    }, [paymentType, selectedStudent, financialSettings]);

    const currentMonthlyFee = useMemo(() => {
        const specificFee = selectedStudent?.desiredClass 
            ? financialSettings.classSpecificFees?.find(c => c.classLevel === selectedStudent.desiredClass)
            : undefined;
        const rawFee = specificFee ? specificFee.monthlyFee : financialSettings.monthlyFee;
        return calculateDiscountedFee(rawFee, 'Mensalidade');
    }, [selectedStudent, financialSettings]);

    const calculateTotal = () => {
        let total = baseFee + calculateDiscountedFee(financialSettings.annualExamFee, 'Taxa de Exames');
        if (payFirstMonth) total += currentMonthlyFee;
        Object.keys(selectedUniforms).forEach(id => {
            if (selectedUniforms[id]) {
                const item = financialSettings.uniforms.find(u => u.id === id);
                if (item) total += calculateDiscountedFee(item.price, 'Uniforme');
            }
        });
        Object.keys(selectedBooks).forEach(id => {
            if (selectedBooks[id]) {
                const item = financialSettings.books.find(b => b.id === id);
                if (item) total += calculateDiscountedFee(item.price, 'Material');
            }
        });
        return total;
    };

    const handleProcessPayment = () => {
        if (!selectedStudent || !selectedYear) return;

        const paymentTypeLabel = paymentType === 'new' ? 'Matrícula' : 'Renovação';
        const items: PaymentItem[] = [];
        let totalPaid = 0;

        items.push({ item: `${paymentTypeLabel} (${selectedStudent.desiredClass})`, value: baseFee });
        totalPaid += baseFee;

        const examFee = calculateDiscountedFee(financialSettings.annualExamFee, 'Taxa de Exames');
        items.push({ item: 'Taxas de Testes/Exames', value: examFee });
        totalPaid += examFee;

        let firstMonthlyFeeReference: number | undefined = undefined;
        if (payFirstMonth) { 
            const acYear = academicYears.find(y => y.year === Number(selectedYear));
            const startMonth = acYear ? (acYear.startMonth || 2) : 2;
            const now = new Date();
            firstMonthlyFeeReference = Number(selectedYear) > now.getFullYear() ? startMonth : Math.max(startMonth, now.getMonth() + 1);
            items.push({ item: `1ª Mensalidade`, value: currentMonthlyFee });
            totalPaid += currentMonthlyFee;
        }

        Object.keys(selectedUniforms).forEach(id => {
            if (selectedUniforms[id]) {
                const item = financialSettings.uniforms.find(u => u.id === id);
                if (item) {
                    const p = calculateDiscountedFee(item.price, 'Uniforme');
                    items.push({ item: item.name, value: p });
                    totalPaid += p;
                }
            }
        });

        Object.keys(selectedBooks).forEach(id => {
            if (selectedBooks[id]) {
                const item = financialSettings.books.find(b => b.id === id);
                if (item) {
                    const p = calculateDiscountedFee(item.price, 'Material');
                    items.push({ item: item.title, value: p });
                    totalPaid += p;
                }
            }
        });

        const newPayment: PaymentRecord = {
            id: `pay_${Date.now()}`,
            date: new Date().toISOString().split('T')[0],
            amount: totalPaid,
            type: paymentTypeLabel,
            method: selectedMethod,
            academicYear: Number(selectedYear),
            description: `${paymentTypeLabel} ${selectedYear}${transactionId ? ' (Ref: ' + transactionId + ')' : ''}`,
            items: items,
            operatorName: currentUser.name
        };
        if (firstMonthlyFeeReference) newPayment.referenceMonth = firstMonthlyFeeReference;

        const updatedStudents: Student[] = students.map(s => {
            if (s.id === selectedStudentId) {
                return {
                    ...s,
                    status: 'Ativo',
                    payments: [...(s.payments || []), newPayment],
                } as Student;
            }
            return s;
        });

        onStudentsChange(updatedStudents);
        setLastPayment(newPayment);
        setIsSuccess(true);
    };

    const handlePrintReceipt = () => {
        if (lastPayment && selectedStudent) {
            printReceipt(lastPayment, selectedStudent, schoolSettings, financialSettings.currency, lastPayment.operatorName || currentUser.name);
        }
    };

    const isMobileMethod = ['MPesa', 'e-Mola', 'mKesh'].includes(selectedMethod);

    return (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-6">
                <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-100">
                    <h3 className="text-lg font-bold text-gray-800 mb-4">Dados da Matrícula</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                         <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Ano Letivo</label>
                            <select value={selectedYear} onChange={e => setSelectedYear(Number(e.target.value))} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-indigo-500">
                                <option value="">Selecione...</option>
                                {academicYears.map(y => <option key={y.id} value={y.year}>{y.year}</option>)}
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Aluno</label>
                            <select value={selectedStudentId} onChange={e => {setSelectedStudentId(e.target.value); setIsSuccess(false);}} className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-indigo-500" disabled={!selectedYear}>
                                <option value="">Selecione...</option>
                                {eligibleStudents.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
