import React, { useState, useMemo, useEffect } from 'react';
import { Student, FinancialSettings, AcademicYear, PaymentRecord, SchoolSettings, User, UserRole, PaymentItem, PaymentMethod, AppNotification, PaymentType } from '../types';
import { CheckCircleIcon, CloseIcon, CalendarIcon, TrashIcon, ClockIcon, ExclamationTriangleIcon, EditIcon, PrinterIcon } from './icons/IconComponents';
import { printReceipt, printStudentStatement } from './ReceiptUtils';
import EditPaymentModal from './EditPaymentModal';

interface FinancialRecordsProps {
    students: Student[];
    onStudentsChange: (students: Student[]) => void;
    financialSettings: FinancialSettings;
    academicYears: AcademicYear[];
    currentUser: User;
    users: User[];
    onAddNotifications: (notifications: AppNotification[]) => void;
    schoolSettings: SchoolSettings;
}

const months = [
    { val: 1, name: 'Janeiro' }, { val: 2, name: 'Fevereiro' }, { val: 3, name: 'Março' },
    { val: 4, name: 'Abril' }, { val: 5, name: 'Maio' }, { val: 6, name: 'Junho' },
    { val: 7, name: 'Julho' }, { val: 8, name: 'Agosto' }, { val: 9, name: 'Setembro' },
    { val: 10, name: 'Outubro' }, { val: 11, name: 'Novembro' }, { val: 12, name: 'Dezembro' }
];

const paymentMethods: PaymentMethod[] = ['Numerário', 'Transferência Bancária', 'MPesa', 'e-Mola', 'mKesh', 'POS'];

const FinancialRecords: React.FC<FinancialRecordsProps> = ({ students, onStudentsChange, financialSettings, academicYears, currentUser, users, onAddNotifications, schoolSettings }) => {
    const [activeYear, setActiveYear] = useState<number | ''>('');
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);

    const [isTransactionModalOpen, setIsTransactionModalOpen] = useState(false);
    const [transactionType, setTransactionType] = useState<'Mensalidade' | 'Uniforme' | 'Material' | 'Multa/Danos'>('Mensalidade');
    const [selectedMethod, setSelectedMethod] = useState<PaymentMethod>('Numerário');
    const [transactionId, setTransactionId] = useState('');
    const [selectedMonth, setSelectedMonth] = useState<number>(new Date().getMonth() + 1);

    const [isSuccess, setIsSuccess] = useState(false);
    const [lastPaymentId, setLastPaymentId] = useState<string | null>(null);

    useEffect(() => {
        const current = academicYears.find(y => y.status === 'Em Curso' || y.status === 'Planeado');
        if (current) setActiveYear(current.year);
    }, [academicYears]);

    const enrolledStudents = useMemo(() => {
        if (!activeYear) return [];
        return students.filter(s => {
            const hasPayments = s.payments?.some(p => p.academicYear === activeYear);
            const nameMatches = s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.id.toLowerCase().includes(searchTerm.toLowerCase());
            return hasPayments && nameMatches && s.status !== 'Inativo';
        });
    }, [students, activeYear, searchTerm]);

    const handleOpenStudentDetails = (student: Student) => {
        setSelectedStudent(student);
        setIsTransactionModalOpen(false);
        setIsSuccess(false);
    };

    const handlePrintReceipt = (payment: PaymentRecord) => {
        if (!selectedStudent) return;
        printReceipt(payment, selectedStudent, schoolSettings, financialSettings.currency, payment.operatorName || currentUser.name);
    };

    const getMonthlyFinancialStatus = (student: Student, year: number, month: number) => {
        const totalPaid = (student.payments || []).filter(p => p.academicYear === year && (p.type === 'Mensalidade' || p.type === 'Matrícula' || p.type === 'Renovação') && p.referenceMonth === month).reduce((acc, curr) => acc + curr.amount, 0);
        const specificFee = financialSettings.classSpecificFees?.find(c => c.classLevel === student.desiredClass);
        const baseFee = specificFee ? specificFee.monthlyFee : financialSettings.monthlyFee;
        return { totalPaid, baseFee, isFullyPaid: totalPaid >= baseFee - 1 };
    };

    const handleProcessTransaction = () => {
        if (!selectedStudent || !activeYear) return;
        const status = getMonthlyFinancialStatus(selectedStudent, Number(activeYear), selectedMonth);
        const amount = Math.max(0, status.baseFee - status.totalPaid);

        const newPayment: PaymentRecord = {
            id: `pay_${Date.now()}`,
            date: new Date().toISOString().split('T')[0],
            amount: amount,
            type: 'Mensalidade',
            method: selectedMethod,
            academicYear: Number(activeYear),
            referenceMonth: selectedMonth,
            description: `Mensalidade ${months.find(m => m.val === selectedMonth)?.name}${transactionId ? ' (Ref: ' + transactionId + ')' : ''}`,
            operatorName: currentUser.name
        };

        const updatedStudents = students.map(s => s.id === selectedStudent.id ? { ...s, payments: [...(s.payments || []), newPayment] } : s);
        onStudentsChange(updatedStudents);
        setLastPaymentId(newPayment.id);
        setIsSuccess(true);
        setSelectedStudent(updatedStudents.find(s => s.id === selectedStudent.id) || null);
    };

    const monthlyStatus = useMemo(() => {
        if (!selectedStudent || !activeYear) return [];
        const statusList = [];
        for (let m = 2; m <= 11; m++) {
            const status = getMonthlyFinancialStatus(selectedStudent, Number(activeYear), m);
            statusList.push({ month: m, ...status });
        }
        return statusList;
    }, [selectedStudent, activeYear, financialSettings]);

    return (
        <div className="space-y-6">
            <div className="bg-white p-6 rounded-2xl shadow-lg flex flex-col md:flex-row justify-between items-center gap-4 border border-gray-100">
                <div><h3 className="text-xl font-bold text-gray-800">Registos Financeiros</h3><p className="text-sm text-gray-500">Gestão individual de pagamentos.</p></div>
                <div className="flex gap-4 w-full md:w-auto">
                    <select value={activeYear} onChange={e => setActiveYear(Number(e.target.value))} className="p-2 border rounded-lg bg-gray-50">
                        {academicYears.map(y => <option key={y.id} value={y.year}>{y.year}</option>)}
                    </select>
                    <input type="text" placeholder="Buscar aluno..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="p-2 border rounded-lg w-full md:w-64" />
                </div>
            </div>

            <div className="bg-white rounded-2xl shadow-lg overflow-hidden border border-gray-100">
                <table className="min-w-full divide-y divide-gray-200">
                    <thead className="bg-gray-50">
                        <tr><th className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase">Aluno</th><th className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase">Classe</th><th className="px-6 py-3 text-right text-xs font-bold text-gray-500 uppercase">Ações</th></tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {enrolledStudents.map(student => (
                            <tr key={student.id} className="hover:bg-gray-50 transition-colors">
                                <td className="px-6 py-4 flex items-center font-medium text-gray-900">{student.name}</td>
                                <td className="px-6 py-4 text-sm text-gray-500">{student.desiredClass}</td>
                                <td className="px-6 py-4 text-right"><button onClick={() => handleOpenStudentDetails(student)} className="text-indigo-600 font-bold hover:underline">Ver Carnê</button></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {selectedStudent && (
                <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex justify-center items-center p-4">
                    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col animate-fade-in">
                        <header className="flex items-center justify-between p-6 border-b">
                            <div><h2 className="text-xl font-bold text-gray-800">{selectedStudent.name}</h2><p className="text-sm text-gray-500">Ano Letivo {activeYear}</p></div>
                            <button onClick={() => setSelectedStudent(null)} className="p-2 hover:bg-gray-100 rounded-full"><CloseIcon className="w-6 h-6"/></button>
                        </header>
                        <div className="flex-1 overflow-y-auto p-6 grid grid-cols-1 lg:grid-cols-2 gap-8">
                            <div className="space-y-4">
                                <h3 className="font-bold text-gray-700 flex items-center"><CalendarIcon className="w-5 h-5 mr-2" />Situação das Mensalidades</h3>
                                <div className="grid grid-cols-2 gap-3">
                                    {monthlyStatus.map(ms => (
                                        <div key={ms.month} className={`p-4 rounded-xl border flex flex-col items-center justify-center text-center ${ms.isFullyPaid ? 'bg-green-50 border-green-100 text-green-700' : 'bg-gray-50 border-gray-100 text-gray-500'}`}>
                                            <span className="text-[10px] font-black uppercase mb-1">{months.find(m => m.val === ms.month)?.name}</span>
                                            <span className="text-sm font-bold">{ms.isFullyPaid ? 'Pago' : 'Pendente'}</span>
                                            {!ms.isFullyPaid && (
                                                <button onClick={() => {setSelectedMonth(ms.month); setIsTransactionModalOpen(true); setIsSuccess(false);}} className="mt-2 text-[10px] bg-white px-4 py-1.5 rounded-lg shadow-sm border border-gray-200 font-bold text-indigo-600 uppercase hover:bg-indigo-600 hover:text-white transition-all">Pagar</button>
                                            )}
                                        </div>
                                    ))}
                                </div>
                            </div>

                            <div className="space-y-6">
                                {isTransactionModalOpen ? (
                                    <div className="bg-indigo-50 p-6 rounded-2xl border border-indigo-100 space-y-4 animate-slide-up">
                                        <h4 className="font-bold text-indigo-900">Novo Recebimento: {months.find(m => m.val === selectedMonth)?.name}</h4>
                                        <div className="space-y-3">
                                            <label className="block text-xs font-bold text-indigo-400 uppercase">Método</label>
                                            <select value={selectedMethod} onChange={e => setSelectedMethod(e.target.value as PaymentMethod)} className="w-full p-2 border rounded-lg bg-white">
                                                {paymentMethods.map(m => <option key={m} value={m}>{m}</option>)}
                                            </select>
                                            {['MPesa', 'e-Mola', 'mKesh'].includes(selectedMethod) && (
                                                <input type="text" value={transactionId} onChange={e => setTransactionId(e.target.value)} placeholder="Referência da Transação" className="w-full p-2 border rounded-lg font-mono uppercase" />
                                            )}
                                            <div className="pt-4 flex justify-between items-center border-t border-indigo-200">
                                                <span className="font-bold text-indigo-900">Total a Receber:</span>
                                                <span className="text-2xl font-black text-indigo-900">{(getMonthlyFinancialStatus(selectedStudent, Number(activeYear), selectedMonth).baseFee).toLocaleString()} MT</span>
                                            </div>
                                            {isSuccess ? (
                                                <div className="flex gap-2">
                                                    <div className="flex-1 bg-green-500 text-white p-2 rounded-lg text-center font-bold text-sm">Sucesso!</div>
                                                    <button onClick={() => {const p = selectedStudent.payments?.find(py => py.id === lastPaymentId); if(p) handlePrintReceipt(p);}} className="bg-indigo-600 text-white px-4 py-2 rounded-lg font-bold"><PrinterIcon className="w-5 h-5"/></button>
                                                </div>
                                            ) : (
                                                <button onClick={handleProcessTransaction} disabled={['MPesa', 'e-Mola', 'mKesh'].includes(selectedMethod) && !transactionId} className="w-full py-3 bg-indigo-600 text-white rounded-xl font-bold uppercase disabled:opacity-50">Confirmar</button>
                                            )}
                                        </div>
                                    </div>
                                ) : (
                                    <div className="bg-gray-50 p-10 rounded-2xl border border-dashed border-gray-300 text-center text-gray-400">
                                        <ClockIcon className="w-12 h-12 mx-auto mb-2 opacity-20"/>
                                        <p className="text-sm font-medium">Selecione um mês pendente para registar o pagamento.</p>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

