export const MobilePaymentIcon: React.FC<{ type: 'mpesa' | 'e-mola' | 'mkesh'; className?: string }> = ({ type, className }) => {
  const config: Record<string, { color: string; label: string }> = {
    'mpesa': { color: 'bg-red-600', label: 'M' },
    'e-mola': { color: 'bg-orange-500', label: 'E' },
    'mkesh': { color: 'bg-yellow-400', label: 'K' },
  };
  const active = config[type] || { color: 'bg-gray-400', label: '?' };
  return (
    <div className={`${className} ${active.color} text-white flex items-center justify-center rounded-lg font-black text-center shadow-sm`}>
      {active.label}
    </div>
  );
};

