                        </div>
                    </div>
                )}

                {activeTab === 'financial' && (
                    <div className="flex flex-col gap-6 animate-fade-in">
                        {/* NOVO CARD DE AUTO-PAGAMENTO */}
                        <div className="bg-slate-50 p-10 rounded-[3rem] border border-slate-100 flex flex-col md:flex-row justify-between items-center gap-10">
                            <div className="text-center md:text-left flex-1">
                                <p className="text-xs text-indigo-500 font-black uppercase tracking-widest mb-2">Autosserviço Digital</p>
                                <h4 className="text-3xl font-black text-slate-800 tracking-tight leading-tight">Pagamento via Mobile Money</h4>
                                <p className="text-sm text-slate-500 mt-2 font-medium max-w-lg">Pague mensalidades via M-Pesa, e-Mola ou mKesh sem sair de casa. O comprovativo será validado pela secretaria automaticamente.</p>
                            </div>
                            <button 
                                onClick={() => onOpenPayment(student)}
                                className="w-full md:w-auto bg-indigo-600 text-white px-10 py-5 rounded-[2rem] font-black uppercase text-xs tracking-widest shadow-2xl shadow-indigo-200 hover:scale-105 transition-all flex items-center justify-center"
                            >
                                <DevicePhoneMobileIcon className="w-5 h-5 mr-3" />
                                Pagar Mensalidade
                            </button>
                        </div>

                        <div className="bg-white p-10 rounded-[3rem] border border-slate-100 flex flex-col md:flex-row justify-between items-center gap-10">
                            <div className="text-center md:text-left flex-1">
                                <h4 className="text-2xl font-black text-slate-800 tracking-tight leading-tight">Extrato de Conta Corrente</h4>
                                <p className="text-sm text-slate-500 mt-2 font-medium">Histórico completo de faturas, créditos e saldos devedores.</p>
                            </div>
                            <button 
                                onClick={() => onOpenStatement(student)}
                                className="w-full md:w-auto bg-slate-900 text-white px-10 py-5 rounded-[2rem] font-black uppercase text-xs tracking-widest hover:bg-slate-800 transition-all flex items-center justify-center"
                            >
                                <PrinterIcon className="w-5 h-5 mr-3" />
                                Ver Extrato
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

const GuardianPortal: React.FC<GuardianPortalProps> = ({ user, onLogout, onUpdateCurrentUser, students, onStudentsChange, academicYears, schoolSettings, turmas, financialSettings, activeView = 'painel', setActiveView, onAddNotifications, users }) => {
    const myStudents = useMemo(() => students.filter(s => String(s.guardianName).trim().toLowerCase() === String(user.name).trim().toLowerCase()), [students, user.name]);
    const [selectedYear, setSelectedYear] = useState<number | null>(null);
    const [statementStudent, setStatementStudent] = useState<Student | null>(null);
    const [isStatementOpen, setIsStatementOpen] = useState(false);
    const [isPaymentOpen, setIsPaymentOpen] = useState(false);

    useEffect(() => { 
        if (selectedYear === null) {
            const activeYear = academicYears.find(ay => ay.status === 'Em Curso')?.year || new Date().getFullYear();
            setSelectedYear(Number(activeYear)); 
        }
    }, [selectedYear, academicYears]);

    const handleConfirmPayment = (newPayment: PaymentRecord) => {
        if (!onStudentsChange || !onAddNotifications || !statementStudent) return;

        // 1. Atualizar Aluno com o novo pagamento
        const updatedStudents = students.map(s => {
            if (s.id === statementStudent.id) {
                return { ...s, payments: [...(s.payments || []), newPayment] };
            }
            return s;
        });
        onStudentsChange(updatedStudents);

        // 2. Notificar Admins para Validação
        const admins = (users || []).filter(u => u.role === UserRole.ADMIN);
        const notifications: AppNotification[] = admins.map(admin => ({
            id: `notif_portal_pay_${Date.now()}_${admin.id}`,
            userId: admin.id,
            type: 'admin_alert',
            title: 'Novo Auto-Pagamento Portal',
            message: `O encarregado ${user.name} submeteu um pagamento de ${newPayment.amount} MT (Ref: ${newPayment.id}) para o aluno ${statementStudent.name}.`,
            read: false,
            timestamp: new Date().toISOString(),
            relatedId: statementStudent.id
        }));
        onAddNotifications(notifications);
        alert("Comprovativo enviado com sucesso! O seu saldo será atualizado após a validação pela secretaria.");
    };

    return (
        <div className="flex h-screen bg-[#fcfcfd] font-sans overflow-hidden">
            {setActiveView && <Sidebar user={user} activeView={activeView} setActiveView={setActiveView} />}
            <div className="flex-1 flex flex-col overflow-hidden">
                <Header user={user} onLogout={onLogout} onUpdateProfile={onUpdateCurrentUser} title="Portal do Encarregado" />
                <main className="flex-1 overflow-y-auto p-4 md:p-12">
                    <div className="max-w-6xl mx-auto">
                        <div className="flex flex-col md:flex-row justify-between items-end mb-12 gap-6">
                            <div><h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase">Meus Educandos</h2><p className="text-slate-500 font-bold mt-2">Gestão de aproveitamento e pagamentos digitais.</p></div>
                            <div className="bg-white p-3 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-3">
                                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Filtrar Ano:</span>
                                <select value={selectedYear || ''} onChange={(e) => setSelectedYear(Number(e.target.value))} className="border-none rounded-xl text-sm font-black text-indigo-600 focus:ring-0 bg-slate-50 py-2 pr-10">
                                    {academicYears.map(ay => <option key={ay.id} value={ay.year}>{ay.year}</option>)}
                                </select>
                            </div>
                        </div>

                        {myStudents.length > 0 ? myStudents.map(student => (
                            <StudentInfoCard 
                                key={student.id} 
                                student={student} 
                                selectedYear={selectedYear} 
                                academicYears={academicYears}
                                schoolSettings={schoolSettings}
                                turmas={turmas}
                                financialSettings={financialSettings}
                                onOpenStatement={(s) => { setStatementStudent(s); setIsStatementOpen(true); }}
                                onOpenPayment={(s) => { setStatementStudent(s); setIsPaymentOpen(true); }}
                            />
                        )) : <div className="bg-white text-center p-24 rounded-[3rem] shadow-xl border border-slate-100"><UsersIcon className="w-20 h-20 text-slate-100 mx-auto mb-6" /><h3 className="text-2xl font-black text-slate-800">Nenhum aluno vinculado</h3></div>}
                    </div>
                </main>
            </div>

            <StatementModal isOpen={isStatementOpen} onClose={() => setIsStatementOpen(false)} student={statementStudent} year={selectedYear || 2024} financialSettings={financialSettings} />
            <GuardianPaymentModal isOpen={isPaymentOpen} onClose={() => setIsPaymentOpen(false)} student={statementStudent} year={selectedYear || 2024} financialSettings={financialSettings} onConfirm={handleConfirmPayment} />
        </div>
    );
};

export default GuardianPortal;

