  const config = {
    mpesa: { color: 'bg-red-600', label: 'M' },
    emola: { color: 'bg-orange-500', label: 'E' },
    mkesh: { color: 'bg-yellow-400', label: 'K' }
  };
  const active = config[type] || config.mpesa;
  return (
    <div className={`${className} ${active.color} text-white flex items-center justify-center rounded-lg font-black shadow-sm`}>
      {active.label}
    </div>
  );
};

