                                                <div>
                                                    <h5 className={`text-sm font-black uppercase tracking-tight ${
                                                        occ.type === 'Negativo' 
                                                            ? (occ.severity === 'Grave' ? 'text-rose-900' : 'text-orange-900') 
                                                            : 'text-emerald-900'
                                                    }`}>
