import React, { useState, useMemo, useEffect } from 'react';
import { User, Student, AcademicYear, SchoolSettings, Turma, FinancialSettings, AppNotification, UserRole, Grade, AttendanceRecord, Subject, PaymentRecord, PaymentMethod } from '../types';
import { LogoutIcon, GraduationCapIcon, ChevronDownIcon, AcademicCapIcon, CheckCircleIcon, ExclamationTriangleIcon, CloseIcon, CalendarIcon, StarIcon, UsersIcon, CurrencyDollarIcon, ClockIcon, ChartBarIcon, BookOpenIcon, PrinterIcon, FilterIcon, DevicePhoneMobileIcon, MobilePaymentIcon } from './icons/IconComponents';
import Sidebar from './Sidebar';
import Header from './Header';
import { View } from './Dashboard';

interface GuardianPortalProps {
  user: User;
  onLogout: () => void;
  onUpdateCurrentUser: (data: Partial<User>) => void;
  students: Student[];
  onStudentsChange?: (students: Student[]) => void;
  academicYears: AcademicYear[];
  schoolSettings: SchoolSettings;
  turmas: Turma[];
  financialSettings: FinancialSettings;
  activeView?: View;
  setActiveView?: (view: View) => void;
  onAddNotifications?: (notifications: AppNotification[]) => void;
  users?: User[];
}

// FUNÇÃO DE EXTRAÇÃO DE ANO ULTRA ROBUSTA
const safeExtractYear = (dateInput: any): number => {
    if (!dateInput) return 0;
    const str = String(dateInput);
    const match = str.match(/\d{4}/);
    if (match) return parseInt(match[0], 10);
    const d = new Date(dateInput);
    if (!isNaN(d.getFullYear())) return d.getFullYear();
    return 0;
};

const ensureArray = (data: any): any[] => {
    if (!data) return [];
    if (Array.isArray(data)) return data;
    try {
        const parsed = typeof data === 'string' ? JSON.parse(data) : data;
        return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
        return [];
    }
};

const monthsList = [
    { val: 1, name: 'Janeiro' }, { val: 2, name: 'Fevereiro' }, { val: 3, name: 'Março' },
    { val: 4, name: 'Abril' }, { val: 5, name: 'Maio' }, { val: 6, name: 'Junho' },
    { val: 7, name: 'Julho' }, { val: 8, name: 'Agosto' }, { val: 9, name: 'Setembro' },
    { val: 10, name: 'Outubro' }, { val: 11, name: 'Novembro' }, { val: 12, name: 'Dezembro' }
];

const GuardianPaymentModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    student: Student | null;
    year: number;
    financialSettings: FinancialSettings;
    onConfirm: (payment: PaymentRecord) => void;
}> = ({ isOpen, onClose, student, year, financialSettings, onConfirm }) => {
    const [selectedMonth, setSelectedMonth] = useState<number>(new Date().getMonth() + 1);
    const [method, setMethod] = useState<PaymentMethod>('MPesa');
    const [refId, setRefId] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);

    if (!isOpen || !student) return null;

    const currentFee = (() => {
        let base = financialSettings.monthlyFee;
        if (student.desiredClass) {
            const spec = financialSettings.classSpecificFees?.find(c => c.classLevel === student.desiredClass);
            if (spec) base = spec.monthlyFee;
        }
        const profile = student.financialProfile || { status: 'Normal' };
        if (profile.status === 'Isento Total') return 0;
        if (profile.status === 'Desconto Parcial' && profile.affectedTypes?.includes('Mensalidade')) {
            base = base * (1 - (profile.discountPercentage || 0) / 100);
        }
        return base;
    })();

    const formatCurrency = (val: number) => {
        return val.toLocaleString('pt-MZ', { style: 'currency', currency: financialSettings.currency || 'MZN' });
    };

    const handleConfirm = () => {
        if (!refId.trim()) return alert("Por favor, insira a Referência (ID) da transação para validação.");
        setIsSubmitting(true);

        const newPayment: PaymentRecord = {
            id: `pay_g_${Date.now()}`,
            date: new Date().toISOString().split('T')[0],
            amount: currentFee,
            type: 'Mensalidade',
            method: method,
            academicYear: year,
            referenceMonth: selectedMonth,
            description: `Auto-Pagamento Mobile: Mês ${selectedMonth} (ID: ${refId})`,
            operatorName: 'Portal do Encarregado',
            items: [{ item: `Mensalidade ${monthsList.find(m => m.val === selectedMonth)?.name}`, value: currentFee }]
        };

        onConfirm(newPayment);
        setIsSubmitting(false);
        setRefId('');
        onClose();
    };

    return (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-md z-[110] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden animate-fade-in">
                <header className="p-6 border-b bg-slate-50 flex justify-between items-center">
                    <div>
                        <h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">Pagamento Digital</h3>
                        <p className="text-xs font-bold text-indigo-500 uppercase">{student.name}</p>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-white rounded-full transition-colors">
                        <CloseIcon className="w-6 h-6 text-slate-400" />
                    </button>
                </header>

                <div className="p-6 space-y-5">
                    <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">1. Escolher Mês</label>
                        <select 
                            value={selectedMonth} 
                            onChange={e => setSelectedMonth(Number(e.target.value))}
                            className="w-full p-3 bg-slate-100 border-none rounded-xl font-black text-slate-700 focus:ring-4 focus:ring-indigo-500/10"
                        >
                            {monthsList.map(m => <option key={m.val} value={m.val}>{m.name}</option>)}
                        </select>
                    </div>

                    <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">2. Selecionar Carteira</label>
                        <div className="grid grid-cols-3 gap-3">
                            {(['MPesa', 'e-Mola', 'mKesh'] as const).map(m => (
                                <button 
                                    key={m} 
                                    type="button"
                                    onClick={() => setMethod(m)}
                                    className={`p-3 rounded-2xl border-2 flex flex-col items-center gap-2 transition-all ${method === m ? 'border-indigo-600 bg-indigo-50' : 'border-slate-100 bg-white'}`}
                                >
                                    <MobilePaymentIcon type={m === 'MPesa' ? 'mpesa' : m === 'e-Mola' ? 'emola' : 'mkesh'} className="w-8 h-8" />
                                    <span className="text-[10px] font-black uppercase">{m}</span>
                                </button>
                            ))}
                        </div>
                    </div>

                    <div className="bg-indigo-600 p-5 rounded-3xl text-white shadow-xl shadow-indigo-100">
                        <p className="text-[10px] font-black uppercase opacity-60 mb-2">Instruções da Escola</p>
                        <div className="text-sm font-bold leading-relaxed">
                            {method === 'MPesa' && (
                                <p>Transferir para Código de Negócio: <span className="bg-white/20 px-2 py-0.5 rounded">{financialSettings.mobilePaymentConfig?.mpesaCode || 'Não definido'}</span></p>
                            )}
                            {method === 'e-Mola' && (
                                <p>Transferir para o Número: <span className="bg-white/20 px-2 py-0.5 rounded">{financialSettings.mobilePaymentConfig?.emolaCode || 'Não definido'}</span></p>
                            )}
                            {method === 'mKesh' && (
                                <p>Transferir para Código/Número: <span className="bg-white/20 px-2 py-0.5 rounded">{financialSettings.mobilePaymentConfig?.mkeshCode || 'Não definido'}</span></p>
                            )}
                        </div>
                        <p className="text-[18px] font-black mt-3">Valor: {formatCurrency(currentFee)}</p>
                    </div>

                    <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">3. Inserir Referência (ID)</label>
                        <input 
                            type="text" 
                            value={refId}
                            onChange={e => setRefId(e.target.value.toUpperCase())}
                            placeholder="Ex: 8G457788A"
                            className="w-full p-4 border-2 border-slate-100 rounded-2xl focus:border-indigo-600 focus:ring-0 font-mono font-bold uppercase transition-all"
                        />
                    </div>
                </div>

                <footer className="p-6 bg-slate-50 flex gap-3 border-t">
                    <button onClick={onClose} className="flex-1 py-3 font-black text-xs uppercase text-slate-400 hover:text-slate-600">Cancelar</button>
                    <button 
                        onClick={handleConfirm}
                        disabled={isSubmitting || !refId}
                        className="flex-[2] bg-slate-900 text-white py-3 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-indigo-600 shadow-xl shadow-indigo-100 disabled:opacity-50 transition-all"
                    >
                        {isSubmitting ? 'Enviando...' : 'Enviar Pagamento'}
                    </button>
                </footer>
            </div>
        </div>
    );
};

const StatementModal: React.FC<{ 
    isOpen: boolean; 
    onClose: () => void; 
    student: Student | null; 
    year: number; 
    financialSettings: FinancialSettings;
}> = ({ isOpen, onClose, student, year, financialSettings }) => {
    if (!isOpen || !student) return null;

    const formatCurrency = (val: number) => {
        return val.toLocaleString('pt-MZ', { style: 'currency', currency: financialSettings.currency || 'MZN' });
    };

    const ledger = useMemo(() => {
        const items: { date: string; desc: string; debit: number; credit: number }[] = [];
        const startMonth = 2;
        const now = new Date();
        const currentMonth = year === now.getFullYear() ? now.getMonth() + 1 : 11;

        let monthlyFee = financialSettings.monthlyFee;
        if (student.desiredClass) {
            const specific = financialSettings.classSpecificFees?.find(c => c.classLevel === student.desiredClass);
            if (specific) monthlyFee = specific.monthlyFee;
        }

        for (let m = startMonth; m <= currentMonth; m++) {
            items.push({ 
                date: `${year}-${m.toString().padStart(2, '0')}-01`, 
                desc: `MENSALIDADE - MÊS ${m}`, 
                debit: monthlyFee, 
                credit: 0 
            });
        }

        ensureArray(student.payments).filter(p => Number(p.academicYear) === Number(year)).forEach(p => {
            items.push({ 
                date: p.date, 
                desc: `PAGAMENTO: ${p.type} (${p.method || 'Geral'})`, 
                debit: 0, 
                credit: p.amount 
            });
        });

        return items.sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());
    }, [student, year, financialSettings]);

    let runningBalance = 0;

    return (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-3xl overflow-hidden flex flex-col max-h-[90vh]">
                <header className="p-8 border-b bg-slate-50 flex justify-between items-center">
                    <div>
                        <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Extrato de Conta Corrente</h3>
                        <p className="text-sm font-bold text-indigo-500">{student.name} • Ano Letivo {year}</p>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-white rounded-full transition-colors">
                        <CloseIcon className="w-8 h-8 text-slate-400" />
                    </button>
                </header>
                <div className="flex-1 overflow-y-auto p-8">
                    <table className="w-full text-sm">
                        <thead className="text-[10px] font-black uppercase text-slate-400 border-b">
                            <tr>
                                <th className="text-left py-4">Data</th>
                                <th className="text-left py-4">Descrição</th>
                                <th className="text-right py-4">Débito</th>
                                <th className="text-right py-4">Crédito</th>
                                <th className="text-right py-4">Saldo</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {ledger.map((item, i) => {
                                runningBalance += (item.debit - item.credit);
                                return (
                                    <tr key={i} className="hover:bg-slate-50 transition-colors">
                                        <td className="py-4 text-slate-500 whitespace-nowrap">{new Date(item.date).toLocaleDateString()}</td>
                                        <td className="py-4 font-bold text-slate-700">{item.desc}</td>
                                        <td className="py-4 text-right text-rose-600 font-bold">{item.debit > 0 ? formatCurrency(item.debit) : '-'}</td>
                                        <td className="py-4 text-right text-emerald-600 font-bold">{item.credit > 0 ? formatCurrency(item.credit) : '-'}</td>
                                        <td className={`py-4 text-right font-black ${runningBalance > 0 ? 'text-rose-700' : 'text-emerald-700'}`}>
                                            {formatCurrency(runningBalance)}
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
                <footer className="p-8 bg-slate-900 text-white flex justify-between items-center">
                    <div>
                        <p className="text-[10px] font-black uppercase text-indigo-300 mb-1">Saldo Corrente</p>
                        <p className="text-3xl font-black">{formatCurrency(Math.abs(runningBalance))}</p>
                        <p className="text-[10px] uppercase font-bold">{runningBalance > 0 ? 'Dívida a Regularizar' : 'Situação Regularizada'}</p>
                    </div>
                    <button onClick={onClose} className="bg-indigo-600 px-8 py-3 rounded-xl font-black uppercase text-xs tracking-widest hover:bg-indigo-700 transition-all">Fechar Extrato</button>
                </footer>
            </div>
        </div>
    );
};

const StudentInfoCard: React.FC<{ 
    student: Student; 
    selectedYear: number | null; 
    academicYears: AcademicYear[]; 
    schoolSettings: SchoolSettings; 
    turmas: Turma[]; 
    financialSettings: FinancialSettings;
    onOpenStatement: (s: Student) => void;
    onOpenPayment: (s: Student) => void;
}> = ({ student, selectedYear, academicYears, schoolSettings, turmas, financialSettings, onOpenStatement, onOpenPayment }) => {
    const [activeTab, setActiveTab] = useState<'grades' | 'attendance' | 'financial' | 'behavior'>('grades');
    const [attMonthFilter, setAttMonthFilter] = useState<string>('all');
    const [attCategoryFilter, setAttCategoryFilter] = useState<string>('all');

    const activeTurma = useMemo(() => {
        if (!selectedYear) return null;
        return turmas.find(t => Number(t.academicYear) === Number(selectedYear) && ensureArray(t.studentIds).includes(student.id));
    }, [turmas, selectedYear, student.id]);

    const academicYearConfig = useMemo(() => academicYears.find(ay => Number(ay.year) === Number(selectedYear)), [academicYears, selectedYear]);

    const subjects = useMemo(() => {
        if (!activeTurma || !academicYearConfig) return [];
        return ensureArray(academicYearConfig.subjectsByClass).find(cs => cs.classLevel === activeTurma.classLevel)?.subjects || [];
    }, [activeTurma, academicYearConfig]);

    const hasExam = useMemo(() => {
        if (!activeTurma || !academicYearConfig) return false;
        return !!ensureArray(academicYearConfig.subjectsByClass).find(cs => cs.classLevel === activeTurma.classLevel)?.hasExam;
    }, [activeTurma, academicYearConfig]);

    const calcMF = (acs1: number = 0, acs2: number = 0, at: number = 0) => {
        const p1 = schoolSettings.evaluationWeights?.p1 || 40;
        const p2 = schoolSettings.evaluationWeights?.p2 || 60;
        const mediaACS = (acs1 + acs2) / 2;
        const mf = ((mediaACS * p1) + (at * p2)) / (p1 + p2);
        return parseFloat(mf.toFixed(1));
    };

    const academicSummary = useMemo(() => {
        if (!selectedYear || subjects.length === 0) return { globalAvg: 0, passed: false };
        let totalSum = 0; let count = 0;
        subjects.forEach((sub: Subject) => {
            const grades = ensureArray(student.grades);
            const t1 = grades.find(g => g.subject === sub.name && g.period === '1º Trimestre' && Number(g.academicYear) === Number(selectedYear));
            const t2 = grades.find(g => g.subject === sub.name && g.period === '2º Trimestre' && Number(g.academicYear) === Number(selectedYear));
            const t3 = grades.find(g => g.subject === sub.name && g.period === '3º Trimestre' && Number(g.academicYear) === Number(selectedYear));
            const mf1 = t1 ? calcMF(t1.acs1, t1.acs2, t1.at) : 0;
            const mf2 = t2 ? calcMF(t2.acs1, t2.acs2, t2.at) : 0;
            const mf3 = t3 ? calcMF(t3.acs1, t3.acs2, t3.at) : 0;
            const valid = [mf1, mf2, mf3].filter(m => m > 0);
            const mediaI = valid.length > 0 ? valid.reduce((a,b) => a+b, 0) / valid.length : 0;
            let final = mediaI;
            if (hasExam) {
                const ex = ensureArray(student.examGrades).find(e => e.subject === sub.name && Number(e.academicYear) === Number(selectedYear));
                if (ex) {
                    const w1 = schoolSettings.examWeights?.internal || 50;
                    const w2 = schoolSettings.examWeights?.exam || 50;
                    final = ((mediaI * w1) + (ex.grade * w2)) / (w1 + w2);
                }
            }
            if (final > 0) { totalSum += final; count++; }
        });
        const avg = count > 0 ? parseFloat((totalSum / count).toFixed(1)) : 0;
        return { globalAvg: avg, passed: avg >= 9.5 };
    }, [student, subjects, selectedYear, hasExam, schoolSettings]);

    const attendanceSummary = useMemo(() => {
        if (!selectedYear) return { total: 0, present: 0, absent: 0, late: 0, history: [] };
        const recordsInYear = ensureArray(student.attendance).filter(a => safeExtractYear(a.date) === Number(selectedYear));
        const present = recordsInYear.filter(r => r.status === 'Presente').length;
        const absent = recordsInYear.filter(r => r.status === 'Ausente').length;
        const late = recordsInYear.filter(r => r.status === 'Atrasado').length;
        let history = recordsInYear.filter(r => r.status !== 'Presente');
        if (attMonthFilter !== 'all') history = history.filter(r => (new Date(r.date).getMonth() + 1) === Number(attMonthFilter));
        if (attCategoryFilter !== 'all') history = history.filter(r => r.status === attCategoryFilter);
        return { total: recordsInYear.length, present, absent, late, history: [...history].sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()) };
    }, [student.attendance, selectedYear, attMonthFilter, attCategoryFilter]);

    return (
        <div className="bg-white rounded-[2rem] shadow-2xl border border-gray-100 overflow-hidden mb-10 transition-all hover:shadow-indigo-100">
            <div className="p-8 bg-slate-900 text-white relative">
                <div className="flex flex-col md:flex-row items-center gap-8 relative z-10">
                    <img className="h-24 w-24 rounded-3xl object-cover border-4 border-indigo-500 shadow-xl" src={student.profilePictureUrl || 'https://i.pravatar.cc/150'} alt="" />
                    <div className="flex-1 text-center md:text-left">
                        <h3 className="text-3xl font-black uppercase tracking-tight">{student.name}</h3>
                        <p className="text-indigo-400 text-xs font-black uppercase tracking-widest mt-2">
                             {activeTurma ? `${activeTurma.classLevel} • ${activeTurma.name}` : student.desiredClass}
                        </p>
                    </div>
                    <div className="bg-indigo-600 p-6 rounded-3xl text-center min-w-[160px] border border-indigo-400/30 shadow-2xl">
                        <p className="text-[10px] font-black uppercase text-indigo-100 mb-1 tracking-widest">Média Global Anual</p>
                        <p className="text-5xl font-black">{academicSummary.globalAvg || '--'}</p>
                        <p className={`text-[10px] font-bold mt-1 ${academicSummary.passed ? 'text-emerald-300' : 'text-rose-300'}`}>
                            {academicSummary.passed ? 'APROVADO' : 'PENDENTE'}
                        </p>
                    </div>
                </div>
            </div>

            <div className="flex bg-slate-50 border-b overflow-x-auto no-scrollbar p-2 gap-2">
                {[
                    { id: 'grades', label: 'Pauta de Notas', icon: <ChartBarIcon className="w-4 h-4" /> },
                    { id: 'attendance', label: 'Assiduidade', icon: <CalendarIcon className="w-4 h-4" /> },
                    { id: 'financial', label: 'Financeiro', icon: <CurrencyDollarIcon className="w-4 h-4" /> },
                    { id: 'behavior', label: 'Conduta', icon: <StarIcon className="w-4 h-4" /> }
                ].map(tab => (
                    <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex items-center px-6 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-white text-indigo-600 shadow-md border border-indigo-100' : 'text-slate-400 hover:text-slate-600'}`}>
                        <span className="mr-2">{tab.icon}</span>{tab.label}
                    </button>
                ))}
            </div>

            <div className="p-4 md:p-10">
                {activeTab === 'grades' && (
                    <div className="overflow-x-auto -mx-4 md:mx-0 rounded-2xl border border-slate-100">
                        <table className="min-w-full text-[10px] border-collapse">
                            <thead>
                                <tr className="bg-slate-900 text-white font-black uppercase tracking-tighter">
                                    <th className="p-4 text-left border-r border-white/10 sticky left-0 bg-slate-900 z-10">Disciplina</th>
                                    <th colSpan={5} className="p-2 text-center border-r border-white/10 bg-indigo-900/50">1º Trimestre</th>
                                    <th colSpan={5} className="p-2 text-center border-r border-white/10 bg-slate-800">2º Trimestre</th>
                                    <th colSpan={5} className="p-2 text-center border-r border-white/10 bg-indigo-900/50">3º Trimestre</th>
                                    {hasExam && <th className="p-4 text-center border-r border-white/10 bg-amber-600">Exame</th>}
                                    <th className="p-4 text-right bg-indigo-600">Média Anual</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100 text-[11px]">
                                {subjects.length > 0 ? subjects.map((sub: Subject) => {
                                    const grades = ensureArray(student.grades);
                                    const g1 = grades.find(g => g.subject === sub.name && g.period === '1º Trimestre' && Number(g.academicYear) === Number(selectedYear));
                                    const g2 = grades.find(g => g.subject === sub.name && g.period === '2º Trimestre' && Number(g.academicYear) === Number(selectedYear));
                                    const g3 = grades.find(g => g.subject === sub.name && g.period === '3º Trimestre' && Number(g.academicYear) === Number(selectedYear));
                                    const ex = ensureArray(student.examGrades).find(e => e.subject === sub.name && Number(e.academicYear) === Number(selectedYear));
                                    const mf1 = g1 ? calcMF(g1.acs1, g1.acs2, g1.at) : 0;
                                    const mf2 = g2 ? calcMF(g2.acs1, g2.acs2, g2.at) : 0;
                                    const mf3 = g3 ? calcMF(g3.acs1, g3.acs2, g3.at) : 0;
                                    const valMfs = [mf1, mf2, mf3].filter(m => m > 0);
                                    const medI = valMfs.length > 0 ? valMfs.reduce((a,b)=>a+b,0)/valMfs.length : 0;
                                    let final = medI;
                                    if (hasExam && ex) final = ((medI * (schoolSettings.examWeights?.internal || 50)) + (ex.grade * (schoolSettings.examWeights?.exam || 50))) / 100;
                                    return (
                                        <tr key={sub.id} className="hover:bg-indigo-50/30">
                                            <td className="p-3 font-bold text-slate-700 border-r sticky left-0 bg-white z-10">{sub.name}</td>
                                            <td colSpan={5} className="p-1 text-center border-r font-black text-indigo-600">{mf1 > 0 ? mf1.toFixed(1) : '-'}</td>
                                            <td colSpan={5} className="p-1 text-center border-r font-black text-slate-600">{mf2 > 0 ? mf2.toFixed(1) : '-'}</td>
                                            <td colSpan={5} className="p-1 text-center border-r font-black text-indigo-600">{mf3 > 0 ? mf3.toFixed(1) : '-'}</td>
                                            {hasExam && <td className="p-1 text-center bg-amber-50 border-r font-black text-amber-700">{ex?.grade ? ex.grade.toFixed(1) : '-'}</td>}
                                            <td className={`p-3 text-right font-black bg-indigo-100/30 ${final >= 9.5 ? 'text-slate-900' : 'text-rose-600'}`}>{final > 0 ? final.toFixed(1) : '-'}</td>
                                        </tr>
                                    );
                                }) : <tr><td colSpan={20} className="py-20 text-center text-slate-400 font-black uppercase">Sem pauta disponível.</td></tr>}
                            </tbody>
                        </table>
                    </div>
                )}

                {activeTab === 'attendance' && (
                    <div className="space-y-6">
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                            <div className="bg-emerald-50 p-4 rounded-2xl border border-emerald-100 flex items-center justify-between">
                                <div><p className="text-[8px] font-black text-emerald-600 uppercase mb-0.5">Presenças</p><p className="text-2xl font-black text-emerald-700">{attendanceSummary.present}</p></div>
                                <div className="bg-white p-2 rounded-xl text-emerald-500"><CheckCircleIcon className="w-6 h-6" /></div>
                            </div>
                            <div className="bg-rose-50 p-4 rounded-2xl border border-rose-100 flex items-center justify-between">
                                <div><p className="text-[8px] font-black text-rose-600 uppercase mb-0.5">Faltas</p><p className="text-2xl font-black text-rose-700">{attendanceSummary.absent}</p></div>
                                <div className="bg-white p-2 rounded-xl text-rose-500"><CloseIcon className="w-6 h-6" /></div>
                            </div>
                        </div>
                    </div>
                )}

                {activeTab === 'financial' && (
                    <div className="flex flex-col gap-6 animate-fade-in">
                        {/* NOVO CARD DE PAGAMENTO MOBILE */}
                        <div className="bg-slate-50 p-10 rounded-[3rem] border border-slate-100 flex flex-col md:flex-row justify-between items-center gap-10">
                            <div className="text-center md:text-left flex-1">
                                <p className="text-xs text-indigo-500 font-black uppercase tracking-widest mb-2">Autosserviço Digital</p>
                                <h4 className="text-3xl font-black text-slate-800 tracking-tight leading-tight">Pagamento via Mobile Money</h4>
                                <p className="text-sm text-slate-500 mt-2 font-medium max-w-lg">Pague mensalidades via M-Pesa, e-Mola ou mKesh sem sair de casa. O comprovativo será validado pela secretaria após o envio.</p>
                            </div>
                            <button 
                                onClick={() => onOpenPayment(student)}
                                className="w-full md:w-auto bg-indigo-600 text-white px-10 py-5 rounded-[2rem] font-black uppercase text-xs tracking-widest shadow-2xl shadow-indigo-200 hover:scale-105 transition-all flex items-center justify-center"
                            >
                                <DevicePhoneMobileIcon className="w-5 h-5 mr-3" />
                                Pagar Mensalidade
                            </button>
                        </div>

                        <div className="bg-white p-10 rounded-[3rem] border border-slate-100 flex flex-col md:flex-row justify-between items-center gap-10">
                            <div className="text-center md:text-left flex-1">
                                <h4 className="text-2xl font-black text-slate-800 tracking-tight leading-tight">Extrato de Conta Corrente</h4>
                                <p className="text-sm text-slate-500 mt-2 font-medium">Histórico completo de faturas, créditos e saldos devedores.</p>
                            </div>
                            <button 
                                onClick={() => onOpenStatement(student)}
                                className="w-full md:w-auto bg-slate-900 text-white px-10 py-5 rounded-[2rem] font-black uppercase text-xs tracking-widest hover:bg-slate-800 transition-all flex items-center justify-center"
                            >
                                <PrinterIcon className="w-5 h-5 mr-3" />
                                Ver Extrato
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

const GuardianPortal: React.FC<GuardianPortalProps> = ({ user, onLogout, onUpdateCurrentUser, students, onStudentsChange, academicYears, schoolSettings, turmas, financialSettings, activeView = 'painel', setActiveView, onAddNotifications, users }) => {
    const myStudents = useMemo(() => students.filter(s => String(s.guardianName).trim().toLowerCase() === String(user.name).trim().toLowerCase()), [students, user.name]);
    const [selectedYear, setSelectedYear] = useState<number | null>(null);
    const [statementStudent, setStatementStudent] = useState<Student | null>(null);
    const [isStatementOpen, setIsStatementOpen] = useState(false);
    const [isPaymentOpen, setIsPaymentOpen] = useState(false);

    useEffect(() => { 
        if (selectedYear === null) {
            const activeYear = academicYears.find(ay => ay.status === 'Em Curso')?.year || new Date().getFullYear();
            setSelectedYear(Number(activeYear)); 
        }
    }, [selectedYear, academicYears]);

    const handleConfirmPayment = (newPayment: PaymentRecord) => {
        if (!onStudentsChange || !onAddNotifications || !statementStudent) return;

        // 1. Atualizar Aluno com o novo pagamento (Pendente)
        const updatedStudents = students.map(s => {
            if (s.id === statementStudent.id) {
                return { ...s, payments: [...(s.payments || []), newPayment] };
            }
            return s;
        });
        onStudentsChange(updatedStudents);

        // 2. Notificar Admins
        const admins = (users || []).filter(u => u.role === UserRole.ADMIN);
        const notifications: AppNotification[] = admins.map(admin => ({
            id: `notif_gpay_${Date.now()}_${admin.id}`,
            userId: admin.id,
            type: 'admin_alert',
            title: 'Novo Pagamento via Portal',
            message: `O encarregado ${user.name} submeteu um pagamento de ${newPayment.amount} MT (Ref: ${newPayment.id}) para o aluno ${statementStudent.name}.`,
            read: false,
            timestamp: new Date().toISOString(),
            relatedId: statementStudent.id
        }));
        onAddNotifications(notifications);
        alert("Comprovativo enviado com sucesso! O seu saldo será atualizado após a validação pela secretaria.");
    };

    return (
        <div className="flex h-screen bg-[#fcfcfd] font-sans overflow-hidden">
            {setActiveView && <Sidebar user={user} activeView={activeView} setActiveView={setActiveView} />}
            <div className="flex-1 flex flex-col overflow-hidden">
                <Header user={user} onLogout={onLogout} onUpdateProfile={onUpdateCurrentUser} title="Portal do Encarregado" />
                <main className="flex-1 overflow-y-auto p-4 md:p-12">
                    <div className="max-w-6xl mx-auto">
                        <div className="flex flex-col md:flex-row justify-between items-end mb-12 gap-6">
                            <div><h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase">Meus Educandos</h2><p className="text-slate-500 font-bold mt-2">Gestão de aproveitamento e pagamentos digitais.</p></div>
                            <div className="bg-white p-3 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-3">
                                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Ano Lectivo:</span>
                                <select value={selectedYear || ''} onChange={(e) => setSelectedYear(Number(e.target.value))} className="border-none rounded-xl text-sm font-black text-indigo-600 focus:ring-0 bg-slate-50 py-2 pr-10">
                                    {academicYears.map(ay => <option key={ay.id} value={ay.year}>{ay.year}</option>)}
                                </select>
                            </div>
                        </div>

                        {myStudents.length > 0 ? myStudents.map(student => (
                            <StudentInfoCard 
                                key={student.id} 
                                student={student} 
                                selectedYear={selectedYear} 
                                academicYears={academicYears}
                                schoolSettings={schoolSettings}
                                turmas={turmas}
                                financialSettings={financialSettings}
                                onOpenStatement={(s) => { setStatementStudent(s); setIsStatementOpen(true); }}
                                onOpenPayment={(s) => { setStatementStudent(s); setIsPaymentOpen(true); }}
                            />
                        )) : <div className="bg-white text-center p-24 rounded-[3rem] shadow-xl border border-slate-100"><UsersIcon className="w-20 h-20 text-slate-100 mx-auto mb-6" /><h3 className="text-2xl font-black text-slate-800">Nenhum aluno vinculado</h3></div>}
                    </div>
                </main>
            </div>

            <StatementModal isOpen={isStatementOpen} onClose={() => setIsStatementOpen(false)} student={statementStudent} year={selectedYear || 2024} financialSettings={financialSettings} />
            <GuardianPaymentModal isOpen={isPaymentOpen} onClose={() => setIsPaymentOpen(false)} student={statementStudent} year={selectedYear || 2024} financialSettings={financialSettings} onConfirm={handleConfirmPayment} />
        </div>
    );
};

