const MobilePaymentPage: React.FC<{
    user: User;
    students: Student[];
    financialSettings: FinancialSettings;
    academicYears: AcademicYear[];
    onConfirm: (studentId: string, payment: PaymentRecord) => void;
}> = ({ user, students, financialSettings, academicYears, onConfirm }) => {
    const [selectedStudentId, setSelectedStudentId] = useState(students[0]?.id || '');
    const [selectedMonth, setSelectedMonth] = useState<number>(new Date().getMonth() + 1);
    const [method, setMethod] = useState<PaymentMethod>('MPesa');
    const [refId, setRefId] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);

    const student = useMemo(() => students.find(s => s.id === selectedStudentId), [students, selectedStudentId]);
    const activeYear = useMemo(() => academicYears.find(ay => ay.status === 'Em Curso')?.year || new Date().getFullYear(), [academicYears]);

    const currentFee = useMemo(() => {
        if (!student) return 0;
        let base = financialSettings.monthlyFee;
        if (student.desiredClass) {
            const spec = financialSettings.classSpecificFees?.find(c => c.classLevel === student.desiredClass);
            if (spec) base = spec.monthlyFee;
        }
        const profile = student.financialProfile || { status: 'Normal' };
        if (profile.status === 'Isento Total') return 0;
        if (profile.status === 'Desconto Parcial' && profile.affectedTypes?.includes('Mensalidade')) {
            base = base * (1 - (profile.discountPercentage || 0) / 100);
        }
        return base;
    }, [student, financialSettings]);

    const formatCurrency = (val: number) => {
        return val.toLocaleString('pt-MZ', { style: 'currency', currency: financialSettings.currency || 'MZN' });
    };

    const handleConfirm = () => {
        if (!refId.trim()) return alert("Por favor, insira a Referência da transação.");
        setIsSubmitting(true);

        const newPayment: PaymentRecord = {
            id: `pay_g_${Date.now()}`,
            date: new Date().toISOString().split('T')[0],
            amount: currentFee,
            type: 'Mensalidade',
            method: method,
            academicYear: activeYear,
            referenceMonth: selectedMonth,
            description: `Auto-Pagamento Mobile: Mês ${selectedMonth} (Ref: ${refId})`,
            operatorName: 'Portal do Encarregado',
            items: [{ item: `Mensalidade ${monthsList.find(m => m.val === selectedMonth)?.name}`, value: currentFee }]
        };

        onConfirm(selectedStudentId, newPayment);
        setIsSubmitting(false);
        setRefId('');
        alert("Pagamento enviado com sucesso! Aguarde a validação da secretaria.");
    };

    const history = useMemo(() => {
        const h: PaymentRecord[] = [];
        students.forEach(s => {
            ensureArray(s.payments).forEach(p => {
                if (p.operatorName === 'Portal do Encarregado') h.push(p);
            });
        });
        return h.sort((a,b) => b.id.localeCompare(a.id));
    }, [students]);

    return (
        <div className="max-w-4xl mx-auto animate-fade-in">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* Formulario */}
                <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border border-gray-100">
                    <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tight mb-6 flex items-center">
                        <DevicePhoneMobileIcon className="w-6 h-6 mr-2 text-indigo-600" />
                        Novo Pagamento
                    </h3>

                    <div className="space-y-6">
                        <div>
                            <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">1. Selecionar Educando</label>
                            <select 
                                value={selectedStudentId} 
                                onChange={e => setSelectedStudentId(e.target.value)}
                                className="w-full p-4 bg-slate-50 border-none rounded-2xl font-bold text-slate-700 focus:ring-4 focus:ring-indigo-500/10"
                            >
                                {students.map(s => <option key={s.id} value={s.id}>{s.name} ({s.desiredClass})</option>)}
                            </select>
                        </div>

                        <div>
                            <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">2. Mês de Referência</label>
                            <select 
                                value={selectedMonth} 
                                onChange={e => setSelectedMonth(Number(e.target.value))}
                                className="w-full p-4 bg-slate-50 border-none rounded-2xl font-bold text-slate-700 focus:ring-4 focus:ring-indigo-500/10"
                            >
                                {monthsList.map(m => <option key={m.val} value={m.val}>{m.name}</option>)}
                            </select>
                        </div>

                        <div>
                            <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">3. Operadora</label>
                            <div className="grid grid-cols-3 gap-3">
                                {(['MPesa', 'e-Mola', 'mKesh'] as const).map(m => (
                                    <button 
                                        key={m} 
                                        onClick={() => setMethod(m)}
                                        className={`p-4 rounded-2xl border-2 flex flex-col items-center gap-2 transition-all ${method === m ? 'border-indigo-600 bg-indigo-50 shadow-inner' : 'border-slate-100 bg-white'}`}
                                    >
                                        <MobilePaymentIcon type={m === 'MPesa' ? 'mpesa' : m === 'e-Mola' ? 'emola' : 'mkesh'} className="w-10 h-10" />
                                        <span className="text-[10px] font-black uppercase">{m}</span>
                                    </button>
                                ))}
                            </div>
                        </div>

                        <div className="bg-slate-900 p-6 rounded-3xl text-white shadow-2xl">
                            <p className="text-[10px] font-black uppercase text-indigo-400 mb-3">Dados para Transferência</p>
                            <div className="text-sm font-bold space-y-2">
                                {method === 'MPesa' && <p>Código de Negócio: <span className="text-xl font-black block mt-1">{financialSettings.mobilePaymentConfig?.mpesaCode || 'N/D'}</span></p>}
                                {method === 'e-Mola' && <p>Número e-Mola: <span className="text-xl font-black block mt-1">{financialSettings.mobilePaymentConfig?.emolaCode || 'N/D'}</span></p>}
                                {method === 'mKesh' && <p>Número/Código: <span className="text-xl font-black block mt-1">{financialSettings.mobilePaymentConfig?.mkeshCode || 'N/D'}</span></p>}
                                <div className="pt-3 border-t border-white/10 flex justify-between items-end">
                                    <span className="text-xs opacity-60">Valor a Pagar:</span>
                                    <span className="text-2xl font-black text-emerald-400">{formatCurrency(currentFee)}</span>
                                </div>
                            </div>
                        </div>

                        <div>
                            <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">4. Referência da Transação (ID)</label>
                            <input 
                                type="text" 
                                value={refId}
                                onChange={e => setRefId(e.target.value.toUpperCase())}
                                placeholder="Insira o código do SMS..."
                                className="w-full p-4 border-2 border-slate-100 rounded-2xl focus:border-indigo-600 focus:ring-0 font-mono font-bold uppercase transition-all"
                            />
                        </div>

                        <button 
                            onClick={handleConfirm}
                            disabled={isSubmitting || !refId}
                            className="w-full bg-indigo-600 text-white py-5 rounded-2xl font-black uppercase text-xs tracking-[0.2em] shadow-xl shadow-indigo-100 hover:bg-indigo-700 disabled:opacity-50 transform active:scale-95 transition-all"
                        >
                            {isSubmitting ? 'A ENVIAR...' : 'CONFIRMAR PAGAMENTO'}
                        </button>
                    </div>
                </div>

                {/* Historico */}
                <div className="space-y-6">
                    <div className="bg-indigo-600 p-8 rounded-[2.5rem] text-white shadow-xl shadow-indigo-100">
                        <h4 className="text-lg font-black uppercase tracking-tight mb-2">Apoio ao Pagamento</h4>
                        <p className="text-sm opacity-80 leading-relaxed">Os pagamentos realizados pelo portal são processados manualmente pela secretaria. Certifique-se que o ID da transação está correto para evitar atrasos na validação.</p>
                    </div>

                    <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border border-gray-100">
                        <h4 className="text-sm font-black text-slate-400 uppercase tracking-widest mb-6">Submissões Recentes</h4>
                        <div className="space-y-4">
                            {history.length > 0 ? history.map(p => (
                                <div key={p.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                                    <div className="flex items-center gap-3">
                                        <div className="bg-white p-2 rounded-xl shadow-sm"><MobilePaymentIcon type={p.method === 'MPesa' ? 'mpesa' : p.method === 'e-Mola' ? 'emola' : 'mkesh'} className="w-6 h-6" /></div>
                                        <div>
                                            <p className="text-[10px] font-black text-slate-400 uppercase">Mês {p.referenceMonth}</p>
                                            <p className="text-sm font-bold text-slate-700">{formatCurrency(p.amount)}</p>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <span className="text-[10px] px-2 py-1 rounded-full bg-amber-100 text-amber-700 font-black uppercase">Pendente</span>
                                        <p className="text-[9px] text-slate-400 mt-1">{new Date(p.date).toLocaleDateString()}</p>
                                    </div>
                                </div>
                            )) : (
                                <div className="text-center py-10">
                                    <ClockIcon className="w-10 h-10 text-slate-200 mx-auto mb-2" />
                                    <p className="text-xs text-slate-400 font-bold uppercase">Nenhum registo</p>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

const StudentInfoCard: React.FC<{ 
    student: Student; 
    selectedYear: number | null; 
    academicYears: AcademicYear[]; 
    schoolSettings: SchoolSettings; 
    turmas: Turma[]; 
    financialSettings: FinancialSettings;
    onOpenStatement: (s: Student) => void;
}> = ({ student, selectedYear, academicYears, schoolSettings, turmas, financialSettings, onOpenStatement }) => {
    const [activeTab, setActiveTab] = useState<'grades' | 'attendance' | 'financial' | 'behavior' | 'discipline'>('grades');
    const [attMonthFilter, setAttMonthFilter] = useState<string>('all');
    const [attCategoryFilter, setAttCategoryFilter] = useState<string>('all');

    const activeTurma = useMemo(() => {
        if (!selectedYear) return null;
        return turmas.find(t => Number(t.academicYear) === Number(selectedYear) && ensureArray(t.studentIds).includes(student.id));
    }, [turmas, selectedYear, student.id]);

    const academicYearConfig = useMemo(() => academicYears.find(ay => Number(ay.year) === Number(selectedYear)), [academicYears, selectedYear]);
    const subjects = useMemo(() => {
        if (!activeTurma || !academicYearConfig) return [];
        return ensureArray(academicYearConfig.subjectsByClass).find(cs => cs.classLevel === activeTurma.classLevel)?.subjects || [];
    }, [activeTurma, academicYearConfig]);

    const calcMF = (acs1: number = 0, acs2: number = 0, at: number = 0) => {
        const p1 = schoolSettings.evaluationWeights?.p1 || 40;
        const p2 = schoolSettings.evaluationWeights?.p2 || 60;
        const mediaACS = (acs1 + acs2) / 2;
        const mf = ((mediaACS * p1) + (at * p2)) / (p1 + p2);
        return parseFloat(mf.toFixed(1));
    };

    const academicSummary = useMemo(() => {
        if (!selectedYear || subjects.length === 0) return { globalAvg: 0, passed: false };
        let totalSum = 0; let count = 0;
        subjects.forEach((sub: Subject) => {
            const grades = ensureArray(student.grades);
            const t1 = grades.find(g => g.subject === sub.name && g.period === '1º Trimestre' && Number(g.academicYear) === Number(selectedYear));
            const t2 = grades.find(g => g.subject === sub.name && g.period === '2º Trimestre' && Number(g.academicYear) === Number(selectedYear));
            const t3 = grades.find(g => g.subject === sub.name && g.period === '3º Trimestre' && Number(g.academicYear) === Number(selectedYear));
            const mf1 = t1 ? calcMF(t1.acs1, t1.acs2, t1.at) : 0;
            const mf2 = t2 ? calcMF(t2.acs1, t2.acs2, t2.at) : 0;
            const mf3 = t3 ? calcMF(t3.acs1, t3.acs2, t3.at) : 0;
            const valid = [mf1, mf2, mf3].filter(m => m > 0);
            const mediaI = valid.length > 0 ? valid.reduce((a,b) => a+b, 0) / valid.length : 0;
            let final = mediaI;
            const ex = ensureArray(student.examGrades).find(e => e.subject === sub.name && Number(e.academicYear) === Number(selectedYear));
            if (ex) final = ((mediaI * (schoolSettings.examWeights?.internal || 50)) + (ex.grade * (schoolSettings.examWeights?.exam || 50))) / 100;
            if (final > 0) { totalSum += final; count++; }
        });
        const avg = count > 0 ? parseFloat((totalSum / count).toFixed(1)) : 0;
        return { globalAvg: avg, passed: avg >= 9.5 };
    }, [student, subjects, selectedYear, schoolSettings]);

    const attendanceSummary = useMemo(() => {
        if (!selectedYear) return { total: 0, present: 0, absent: 0, late: 0, history: [] };
        const recordsInYear = ensureArray(student.attendance).filter(a => safeExtractYear(a.date) === Number(selectedYear));
        const present = recordsInYear.filter(r => r.status === 'Presente').length;
        const absent = recordsInYear.filter(r => r.status === 'Ausente').length;
        const late = recordsInYear.filter(r => r.status === 'Atrasado').length;
        let history = recordsInYear.filter(r => r.status !== 'Presente');
        if (attMonthFilter !== 'all') history = history.filter(r => (new Date(r.date).getMonth() + 1) === Number(attMonthFilter));
        if (attCategoryFilter !== 'all') history = history.filter(r => r.status === attCategoryFilter);
        return { total: recordsInYear.length, present, absent, late, history: [...history].sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()) };
    }, [student.attendance, selectedYear, attMonthFilter, attCategoryFilter]);

    return (
        <div className="bg-white rounded-[2rem] shadow-2xl border border-gray-100 overflow-hidden mb-10 transition-all hover:shadow-indigo-100">
            <div className="p-8 bg-slate-900 text-white relative">
                <div className="flex flex-col md:flex-row items-center gap-8 relative z-10">
                    <img className="h-24 w-24 rounded-3xl object-cover border-4 border-indigo-500 shadow-xl" src={student.profilePictureUrl || 'https://i.pravatar.cc/150'} alt="" />
                    <div className="flex-1 text-center md:text-left">
                        <h3 className="text-3xl font-black uppercase tracking-tight">{student.name}</h3>
                        <p className="text-indigo-400 text-xs font-black uppercase tracking-widest mt-2">
                             {activeTurma ? `${activeTurma.classLevel} • ${activeTurma.name}` : student.desiredClass}
                        </p>
                    </div>
                    <div className="bg-indigo-600 p-6 rounded-3xl text-center min-w-[160px] border border-indigo-400/30 shadow-2xl">
                        <p className="text-[10px] font-black uppercase text-indigo-100 mb-1 tracking-widest">Média Global Anual</p>
                        <p className="text-5xl font-black">{academicSummary.globalAvg || '--'}</p>
                        <p className={`text-[10px] font-bold mt-1 ${academicSummary.passed ? 'text-emerald-300' : 'text-rose-300'}`}>
                            {academicSummary.passed ? 'APROVADO' : 'PENDENTE'}
                        </p>
                    </div>
                </div>
            </div>

            <div className="flex bg-slate-50 border-b overflow-x-auto no-scrollbar p-2 gap-2">
                {[
                    { id: 'grades', label: 'Notas', icon: <ChartBarIcon className="w-4 h-4" /> },
                    { id: 'attendance', label: 'Assiduidade', icon: <CalendarIcon className="w-4 h-4" /> },
                    { id: 'discipline', label: 'Ocorrências', icon: <ExclamationTriangleIcon className="w-4 h-4" /> },
                    { id: 'behavior', label: 'Conduta', icon: <StarIcon className="w-4 h-4" /> },
                    { id: 'financial', label: 'Financeiro', icon: <CurrencyDollarIcon className="w-4 h-4" /> }
                ].map(tab => (
                    <button 
                        key={tab.id} 
                        onClick={() => setActiveTab(tab.id as any)} 
                        className={`flex items-center px-6 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all whitespace-nowrap ${
                            activeTab === tab.id 
                            ? 'bg-white text-indigo-600 shadow-md border border-indigo-100' 
                            : 'text-slate-400 hover:text-slate-600'
                        }`}
                    >
                        <span className="mr-2">{tab.icon}</span>{tab.label}
                    </button>
                ))}
            </div>

            <div className="p-4 md:p-10">
                {activeTab === 'grades' && (
                    <div className="overflow-x-auto -mx-4 md:mx-0 rounded-2xl border border-slate-100">
                        <table className="min-w-full text-[10px] border-collapse">
                            <thead>
                                <tr className="bg-slate-900 text-white font-black uppercase tracking-tighter">
                                    <th className="p-4 text-left border-r border-white/10 sticky left-0 bg-slate-900 z-10">Disciplina</th>
                                    <th colSpan={5} className="p-2 text-center border-r border-white/10 bg-indigo-900/50">1º Trimestre</th>
                                    <th colSpan={5} className="p-2 text-center border-r border-white/10 bg-slate-800">2º Trimestre</th>
                                    <th colSpan={5} className="p-2 text-center border-r border-white/10 bg-indigo-900/50">3º Trimestre</th>
                                    <th className="p-4 text-right bg-indigo-600">Média Anual</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100 text-[11px]">
                                {subjects.length > 0 ? subjects.map((sub: Subject) => {
                                    const grades = ensureArray(student.grades);
                                    const t1 = grades.find(g => g.subject === sub.name && g.period === '1º Trimestre' && Number(g.academicYear) === Number(selectedYear));
                                    const t2 = grades.find(g => g.subject === sub.name && g.period === '2º Trimestre' && Number(g.academicYear) === Number(selectedYear));
                                    const t3 = grades.find(g => g.subject === sub.name && g.period === '3º Trimestre' && Number(g.academicYear) === Number(selectedYear));
                                    const mf1 = t1 ? calcMF(t1.acs1, t1.acs2, t1.at) : 0;
                                    const mf2 = t2 ? calcMF(t2.acs1, t2.acs2, t2.at) : 0;
                                    const mf3 = t3 ? calcMF(t3.acs1, t3.acs2, t3.at) : 0;
                                    const valMfs = [mf1, mf2, mf3].filter(m => m > 0);
                                    const medI = valMfs.length > 0 ? valMfs.reduce((a,b)=>a+b,0)/valMfs.length : 0;
                                    return (
                                        <tr key={sub.id} className="hover:bg-indigo-50/30">
                                            <td className="p-3 font-bold text-slate-700 border-r sticky left-0 bg-white z-10">{sub.name}</td>
                                            <td colSpan={5} className="p-1 text-center border-r font-black text-indigo-600">{mf1 > 0 ? mf1.toFixed(1) : '-'}</td>
                                            <td colSpan={5} className="p-1 text-center border-r font-black text-slate-600">{mf2 > 0 ? mf2.toFixed(1) : '-'}</td>
                                            <td colSpan={5} className="p-1 text-center border-r font-black text-indigo-600">{mf3 > 0 ? mf3.toFixed(1) : '-'}</td>
                                            <td className="p-3 text-right font-black bg-indigo-100/30">{medI > 0 ? medI.toFixed(1) : '-'}</td>
                                        </tr>
                                    );
                                }) : <tr><td colSpan={20} className="py-20 text-center text-slate-400 font-black uppercase">Sem pauta disponível.</td></tr>}
                            </tbody>
                        </table>
                    </div>
                )}

                {activeTab === 'attendance' && (
                    <div className="space-y-6">
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                            <div className="bg-emerald-50 p-4 rounded-2xl border border-emerald-100 flex items-center justify-between">
                                <div><p className="text-[8px] font-black text-emerald-600 uppercase mb-0.5">Presenças</p><p className="text-2xl font-black text-emerald-700">{attendanceSummary.present}</p></div>
                                <div className="bg-white p-2 rounded-xl text-emerald-500"><CheckCircleIcon className="w-6 h-6" /></div>
                            </div>
                            <div className="bg-rose-50 p-4 rounded-2xl border border-rose-100 flex items-center justify-between">
                                <div><p className="text-[8px] font-black text-rose-600 uppercase mb-0.5">Faltas</p><p className="text-2xl font-black text-rose-700">{attendanceSummary.absent}</p></div>
                                <div className="bg-white p-2 rounded-xl text-rose-500"><CloseIcon className="w-6 h-6" /></div>
                            </div>
                        </div>
                    </div>
                )}

                {activeTab === 'financial' && (
                    <div className="bg-slate-50 p-10 rounded-[3rem] border border-slate-100 flex flex-col md:flex-row justify-between items-center gap-10">
                        <div className="text-center md:text-left flex-1">
                            <h4 className="text-3xl font-black text-slate-800 tracking-tight leading-tight">Extrato de Conta Corrente</h4>
                            <p className="text-sm text-slate-500 mt-2 font-medium">Histórico completo de mensalidades e pagamentos efetuados.</p>
                        </div>
                        <button 
                            onClick={() => onOpenStatement(student)}
                            className="w-full md:w-auto bg-slate-900 text-white px-12 py-5 rounded-[2rem] font-black uppercase text-xs tracking-widest hover:bg-indigo-600 transition-all shadow-2xl flex items-center justify-center"
                        >
                            <PrinterIcon className="w-5 h-5 mr-3" />
                            Ver Extrato Digital
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
};

// Added missing StatementModal component definition to display student transactions in the portal
const StatementModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    student: Student | null;
    year: number;
    financialSettings: FinancialSettings;
}> = ({ isOpen, onClose, student, year, financialSettings }) => {
    if (!isOpen || !student) return null;

    return (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col">
                <header className="p-6 border-b flex justify-between items-center bg-slate-50">
                    <h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">Extrato Digital: {student.name}</h3>
                    <button onClick={onClose} className="p-2 hover:bg-white rounded-full transition-all">
                        <CloseIcon className="w-6 h-6 text-slate-400" />
                    </button>
                </header>
                <div className="flex-1 overflow-y-auto p-8">
                   <div className="bg-amber-50 border border-amber-200 p-6 rounded-3xl text-amber-800 mb-8">
                        <p className="font-bold mb-2">Resumo de Conta - Ano {year}</p>
                        <p className="text-sm">Este extrato detalha todos os lançamentos e pagamentos realizados. Para uma versão impressa oficial, contacte a secretaria.</p>
                   </div>

                   <div className="space-y-4">
                        {ensureArray(student.payments).filter(p => p.academicYear === year).length > 0 ? (
                            ensureArray(student.payments).filter(p => p.academicYear === year).map(p => (
                                <div key={p.id} className="flex justify-between items-center p-4 bg-slate-50 rounded-2xl border border-slate-100">
                                    <div>
                                        <p className="text-[10px] font-black text-slate-400 uppercase">{new Date(p.date).toLocaleDateString()}</p>
                                        <p className="font-bold text-slate-700">{p.type} {p.referenceMonth ? `(Mês ${p.referenceMonth})` : ''}</p>
                                    </div>
                                    <div className="text-right">
                                        <p className="font-black text-indigo-600">{p.amount.toLocaleString('pt-MZ', { style: 'currency', currency: financialSettings.currency })}</p>
                                        <p className="text-[9px] text-slate-400 font-bold uppercase">{p.method}</p>
                                    </div>
                                </div>
                            ))
                        ) : (
                            <div className="text-center py-20">
                                <p className="text-slate-400 font-bold uppercase tracking-widest">Nenhum registo financeiro encontrado para este ano.</p>
                            </div>
                        )}
                   </div>
                </div>
                <footer className="p-6 bg-slate-50 border-t flex justify-end">
                    <button onClick={onClose} className="bg-slate-900 text-white px-8 py-3 rounded-2xl font-black uppercase text-xs tracking-widest">Fechar</button>
                </footer>
            </div>
        </div>
    );
};

const GuardianPortal: React.FC<GuardianPortalProps> = (props) => {
    const { user, onLogout, onUpdateCurrentUser, students, onStudentsChange, academicYears, schoolSettings, turmas, financialSettings, activeView, setActiveView, onAddNotifications, users, topics, onTopicsChange, messages, onMessagesChange, notifications, onMarkNotificationAsRead } = props;

    const myStudents = useMemo(() => students.filter(s => String(s.guardianName).trim().toLowerCase() === String(user.name).trim().toLowerCase()), [students, user.name]);
    const availableYears = useMemo(() => {
        const yearsSet = new Set<number>();
        myStudents.forEach(s => {
            ensureArray(s.attendance).forEach(a => { const y = safeExtractYear(a.date); if (y > 2000) yearsSet.add(y); });
            ensureArray(s.grades).forEach(g => { if (Number(g.academicYear) > 2000) yearsSet.add(Number(g.academicYear)); });
        });
        academicYears.forEach(ay => { if (Number(ay.year) > 2000) yearsSet.add(Number(ay.year)); });
        if (yearsSet.size === 0) yearsSet.add(new Date().getFullYear());
        return Array.from(yearsSet).sort((a, b) => b - a);
    }, [myStudents, academicYears]);

    const [selectedYear, setSelectedYear] = useState<number | null>(null);
    const [statementStudent, setStatementStudent] = useState<Student | null>(null);
    const [isStatementOpen, setIsStatementOpen] = useState(false);

    useEffect(() => { 
        if (availableYears.length > 0 && selectedYear === null) {
            const activeYear = academicYears.find(ay => ay.status === 'Em Curso')?.year;
            setSelectedYear(activeYear ? Number(activeYear) : Number(availableYears[0])); 
        }
    }, [availableYears, selectedYear, academicYears]);

    const handleConfirmPayment = (studentId: string, payment: PaymentRecord) => {
        if (!onStudentsChange) return;
        const updatedStudents = students.map(s => {
            if (s.id === studentId) return { ...s, payments: [...(s.payments || []), payment] };
            return s;
        });
        onStudentsChange(updatedStudents);

        // Notificar Admins
        const admins = users.filter(u => u.role === UserRole.ADMIN);
        const notifs: AppNotification[] = admins.map(admin => ({
            id: `notif_pay_${Date.now()}_${admin.id}`,
            userId: admin.id,
            type: 'admin_alert',
            title: 'Novo Pagamento via Portal',
            message: `O encarregado ${user.name} enviou um comprovativo de ${payment.amount} MT (Ref: ${payment.id}).`,
            read: false,
            timestamp: new Date().toISOString(),
            relatedId: studentId
        }));
        onAddNotifications(notifs);
    };

    const renderContent = () => {
        if (activeView === 'reuniao') {
            return (
                <InternalChat 
                    currentUser={user}
                    users={users}
                    topics={topics}
                    onTopicsChange={onTopicsChange}
                    messages={messages}
                    onMessagesChange={onMessagesChange}
                    onAddNotifications={onAddNotifications}
                />
            );
        }

        if (activeView === 'pagamentos') {
            return (
                <MobilePaymentPage 
                    user={user}
                    students={myStudents}
                    financialSettings={financialSettings}
                    academicYears={academicYears}
                    onConfirm={handleConfirmPayment}
                />
            );
        }

        return (
            <div className="max-w-6xl mx-auto">
                <div className="flex flex-col md:flex-row justify-between items-end mb-12 gap-6">
                    <div>
                        <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase">Meus Educandos</h2>
                        <p className="text-slate-500 font-bold mt-2">Acompanhamento em Tempo Real.</p>
                    </div>
                    {availableYears.length > 0 && (
                        <div className="bg-white p-3 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-3">
                            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Ano:</span>
                            <select 
                                value={selectedYear || ''} 
                                onChange={(e) => setSelectedYear(Number(e.target.value))} 
                                className="border-none rounded-xl text-sm font-black text-indigo-600 focus:ring-0 bg-slate-50 py-2 pr-10"
                            >
                                {availableYears.map(year => <option key={year} value={year}>Ano {year}</option>)}
                            </select>
                        </div>
                    )}
                </div>

                {myStudents.length > 0 ? myStudents.map(student => (
                    <StudentInfoCard 
                        key={student.id} 
                        student={student} 
                        selectedYear={selectedYear} 
                        academicYears={academicYears}
                        schoolSettings={schoolSettings}
                        turmas={turmas}
                        financialSettings={financialSettings}
                        onOpenStatement={(s) => { setStatementStudent(s); setIsStatementOpen(true); }}
                    />
                )) : (
                    <div className="bg-white text-center p-24 rounded-[3rem] shadow-xl border border-slate-100">
                        <UsersIcon className="w-20 h-20 text-slate-100 mx-auto mb-6" />
                        <h3 className="text-2xl font-black text-slate-800">Nenhum aluno vinculado</h3>
                        <p className="text-slate-400 mt-2">Contacte a secretaria para associar os educandos.</p>
                    </div>
                )}
            </div>
        );
    };

    return (
        <div className="flex h-screen bg-[#fcfcfd] font-sans overflow-hidden">
            <Sidebar user={user} activeView={activeView} setActiveView={setActiveView} />
            <div className="flex-1 flex flex-col overflow-hidden">
                <Header user={user} onLogout={onLogout} onUpdateProfile={onUpdateCurrentUser} title="Portal do Encarregado" notifications={notifications} onMarkNotificationAsRead={onMarkNotificationAsRead} />
                <main className="flex-1 overflow-y-auto p-4 md:p-12">
                    {renderContent()}
                </main>
            </div>

            <StatementModal 
                isOpen={isStatementOpen} 
                onClose={() => setIsStatementOpen(false)} 
                student={statementStudent} 
                year={selectedYear || 2024} 
                financialSettings={financialSettings}
            />
        </div>
    );
};

export default GuardianPortal;
